    resetOnboardingEmpresa:  () => post("/api/dev/reset/onboarding-empresa", {}),
    resetOnboardingOrcamento:() => post("/api/dev/reset/onboarding-orcamento", {}),
    resetTudo:               () => post("/api/dev/reset/tudo", {}),
