  const partes = (neg ? s.slice(1) : s).split(",");
  const inteira = (partes[0] || "").replace(/\B(?=(\d{3})+(?!\d))/g, ".");
  return (neg ? "-" : "") + inteira + (partes.length > 1 ? "," + partes[1] : "");
