// ── Texto → tela (só o que estes textos usam: títulos, listas, tabelas,
// negrito e itálico) ─────────────────────────────────────────────
function legalInline(txt, k) {
  const partes = [];
  const re = /\*\*([^*]+)\*\*|\*([^*]+)\*/g;
  let ult = 0, m, i = 0;
  while ((m = re.exec(txt))) {
    if (m.index > ult) partes.push(txt.slice(ult, m.index));
    partes.push(m[1] ? <b key={k + "b" + i++}>{m[1]}</b> : <i key={k + "i" + i++}>{m[2]}</i>);
    ult = re.lastIndex;
  }
  if (ult < txt.length) partes.push(txt.slice(ult));
  return partes;
}
function TextoLegal({ texto }) {
  const linhas = String(texto || "").split("\n");
  const out = [];
  let i = 0, k = 0;
  const celulas = (l) => l.trim().replace(/^\||\|$/g, "").split("|").map((c) => c.trim());
  while (i < linhas.length) {
    const l = linhas[i];
    if (!l.trim()) { i++; continue; }
    const h = /^(#{2,4})\s+(.*?)(?:\s*\{#([\w-]+)\})?$/.exec(l);
    if (h) {
      const Tag = h[1].length === 2 ? "h2" : h[1].length === 3 ? "h3" : "h4";
      out.push(<Tag key={k++} id={h[3] || undefined} data-vk-legal-titulo="1"
        style={{ margin: Tag === "h2" ? "28px 0 10px" : "20px 0 8px", fontSize: Tag === "h2" ? 22 : 16, color: "#111827", scrollMarginTop: 16 }}>{h[2]}</Tag>);
      i++; continue;
    }
    if (l.trim().startsWith("|")) {
      const cab = celulas(l);
      const corpo = [];
      i += 2;
      while (i < linhas.length && linhas[i].trim().startsWith("|")) { corpo.push(celulas(linhas[i])); i++; }
      out.push(
        <div key={k++} style={{ overflowX: "auto", margin: "10px 0", border: "1px solid rgba(38,36,33,0.14)", borderRadius: 10 }}>
          <table style={{ borderCollapse: "collapse", width: "100%", fontSize: 13, minWidth: cab.length > 2 ? 560 : 0 }}>
            <thead><tr>{cab.map((c, j) => <th key={j} style={{ textAlign: "left", padding: "8px 10px", background: "#f9fafb", borderBottom: "1px solid rgba(38,36,33,0.14)", color: "#374151" }}>{c}</th>)}</tr></thead>
            <tbody>{corpo.map((r, ri) => <tr key={ri}>{r.map((c, j) => <td key={j} style={{ padding: "8px 10px", borderTop: ri ? "1px solid rgba(38,36,33,0.08)" : "none", verticalAlign: "top", color: "#374151", lineHeight: 1.45 }}>{legalInline(c, "t" + ri + j)}</td>)}</tr>)}</tbody>
          </table>
        </div>);
      continue;
    }
    if (/^- /.test(l) || /^\d+\. /.test(l)) {
      const numerada = /^\d+\. /.test(l);
      const itens = [];
      while (i < linhas.length && (numerada ? /^\d+\. /.test(linhas[i]) : /^- /.test(linhas[i]))) { itens.push(linhas[i].replace(/^(- |\d+\. )/, "")); i++; }
      const Lista = numerada ? "ol" : "ul";
      out.push(<Lista key={k++} style={{ margin: "8px 0", paddingLeft: 22, lineHeight: 1.6, color: "#374151", fontSize: 14 }}>
        {itens.map((t, j) => <li key={j} style={{ marginBottom: 4 }}>{legalInline(t, "l" + j)}</li>)}</Lista>);
      continue;
    }
    out.push(<p key={k++} style={{ margin: "8px 0", lineHeight: 1.6, color: "#374151", fontSize: 14 }}>{legalInline(l, "p" + k)}</p>);
    i++;
  }
  return <div>{out}</div>;
}

// Página pública: /privacidade e /termos
function PaginaLegal({ qual }) {
  const ehTermos = qual === "termos";
  useEffect(() => {
    document.title = (ehTermos ? "Termos de Uso" : "Política de Privacidade") + " — VICKE";
    const alvo = (window.location.hash || "").slice(1);
    if (alvo) setTimeout(() => { const el = document.getElementById(alvo); if (el) el.scrollIntoView(); }, 50);
  }, [ehTermos]);
  const link = (ativo) => ({ fontSize: 13, fontWeight: ativo ? 700 : 500, color: ativo ? "#111827" : "#0474f4", textDecoration: "none" });
  return (
    <div data-vk-legal={qual} style={{ minHeight: "100vh", background: "#fafafa", fontFamily: "'Inter', system-ui, -apple-system, sans-serif" }}>
      <div style={{ maxWidth: 820, margin: "0 auto", padding: "20px 16px 60px" }}>
        <div style={{ display: "flex", alignItems: "center", justifyContent: "space-between", gap: 12, flexWrap: "wrap", marginBottom: 8 }}>
          <a href="/" style={{ fontSize: 20, fontWeight: 800, color: "#111827", textDecoration: "none", letterSpacing: 0.5 }}>VICKE</a>
          <div style={{ display: "flex", gap: 16 }}>
            <a href="/privacidade" style={link(!ehTermos)}>Privacidade</a>
            <a href="/termos" style={link(ehTermos)}>Termos de uso</a>
          </div>
        </div>
        <div style={{ background: "#fff", border: "1px solid rgba(38,36,33,0.12)", borderRadius: 16, padding: "8px 22px 22px" }}>
          <TextoLegal texto={ehTermos ? LEGAL_TERMOS : LEGAL_PRIVACIDADE} />
        </div>
      </div>
    </div>
  );
}

// Escritório já cadastrado que ainda não aceitou a versão vigente: o admin
// aceita uma vez (fica no backend com data, versão e quem aceitou). Quem
// não é admin segue usando — o aceite é da empresa.
function AvisoTermos({ usuario }) {
  const [pendente, setPendente] = useState(false);
  const [aceitou, setAceitou] = useState(false);
  const [enviando, setEnviando] = useState(false);
  const [erro, setErro] = useState("");
  const ehAdmin = usuario && usuario.perfil === "escritorio" && usuario.nivel === "admin";
  useEffect(() => {
    if (!ehAdmin || typeof api === "undefined" || !api.termos) return;
    let vivo = true;
    api.termos.situacao().then((r) => {
      if (vivo && r && (!r.aceite || r.aceite.versao !== r.versaoAtual)) setPendente(true);
    }).catch(() => {});
    return () => { vivo = false; };
  }, [ehAdmin]);
  if (!pendente) return null;
  async function aceitar() {
    if (!aceitou) { setErro("Marque que leu e aceita para continuar."); return; }
    setEnviando(true); setErro("");
    try { await api.termos.aceitar(LEGAL_VERSAO); setPendente(false); }
    catch (e) { setErro(e.message || "Não foi possível registrar o aceite."); }
    finally { setEnviando(false); }
  }
  const doc = (href, titulo, linha) => (
    <a href={href} target="_blank" rel="noopener noreferrer" data-vk-termos-doc="1"
      style={{ display: "flex", alignItems: "center", gap: 12, padding: "11px 14px", border: "1px solid rgba(38,36,33,0.12)",
        borderRadius: 12, textDecoration: "none", background: "#fafafa" }}>
      <span aria-hidden="true" style={{ width: 30, height: 30, borderRadius: 8, background: "#fff", border: "1px solid rgba(38,36,33,0.12)",
        display: "flex", alignItems: "center", justifyContent: "center", flexShrink: 0 }}>
        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="#4b5563" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
          <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" /><path d="M14 2v6h6" /><path d="M16 13H8" /><path d="M16 17H8" />
        </svg>
      </span>
      <span style={{ flex: 1, minWidth: 0 }}>
        <span style={{ display: "block", fontSize: 13.5, fontWeight: 600, color: "#262421" }}>{titulo}</span>
        <span style={{ display: "block", fontSize: 12, color: "#6b7280", marginTop: 1 }}>{linha}</span>
      </span>
      <span aria-hidden="true" style={{ color: "#9ca3af", fontSize: 14 }}>↗</span>
    </a>
  );
  return (
    <div data-vk-aviso-termos="1" style={{ position: "fixed", inset: 0, background: "rgba(0,0,0,0.4)", zIndex: 100040, display: "flex",
      alignItems: "center", justifyContent: "center", padding: 20, fontFamily: "'Inter', system-ui, -apple-system, sans-serif" }}>
      <div style={{ background: "#fff", border: "1px solid rgba(38,36,33,0.14)", borderRadius: 16, padding: "24px 26px 22px", maxWidth: 460,
        width: "100%", boxShadow: "0 20px 40px rgba(0,0,0,0.15)", boxSizing: "border-box" }}>
        <div style={{ fontSize: 12, fontWeight: 600, color: "#0474f4", letterSpacing: 0.3, marginBottom: 6 }}>VICKE · versão {LEGAL_VERSAO}</div>
        <div style={{ fontSize: 17, fontWeight: 700, color: "#262421", marginBottom: 8 }}>Termos de Uso e Privacidade</div>
        <div style={{ fontSize: 13.5, color: "#4b5563", lineHeight: 1.55, marginBottom: 16 }}>
          Publicamos as regras de uso do VICKE e de como cuidamos dos dados que o seu escritório coloca aqui.
          Como administrador, confirme o aceite em nome do escritório.
        </div>
        <div style={{ display: "grid", gap: 8, marginBottom: 16 }}>
          {doc("/termos", "Termos de Uso e Acordo de Tratamento de Dados", "o escritório decide sobre os dados; o VICKE só os trata para prestar o serviço")}
          {doc("/privacidade", "Política de Privacidade", "quais dados, para quê, com quem e por quanto tempo")}
        </div>
        <label style={{ display: "flex", gap: 10, alignItems: "flex-start", fontSize: 13, color: "#374151", lineHeight: 1.5, cursor: "pointer",
          padding: "10px 12px", borderRadius: 12, background: aceitou ? "#eff6ff" : "transparent", marginBottom: 14 }}>
          <input type="checkbox" data-vk-aceite-termos="1" checked={aceitou} onChange={(e) => { setAceitou(e.target.checked); setErro(""); }}
            style={{ marginTop: 3, accentColor: "#0474f4", width: 15, height: 15, flexShrink: 0 }} />
          <span>Li e aceito, em nome do escritório, os Termos de Uso, o Acordo de Tratamento de Dados e a Política de Privacidade.</span>
        </label>
        {erro && <div style={{ fontSize: 12.5, color: "#b91c1c", marginBottom: 10 }}>{erro}</div>}
        <div style={{ display: "flex", justifyContent: "flex-end", gap: 10, flexWrap: "wrap" }}>
          {/* toda janela tem como sair: "agora não" volta a perguntar no próximo acesso */}
          <button type="button" data-vk-termos-depois="1" onClick={() => setPendente(false)} disabled={enviando}
            style={{ background: "#fff", color: "#4b5563", border: "1.5px solid rgba(38,36,33,0.16)", borderRadius: 12, padding: "8px 18px",
              fontSize: 13, cursor: "pointer", fontFamily: "inherit" }}>
            Agora não
          </button>
          <button type="button" data-vk-aceitar-termos="1" onClick={aceitar} disabled={enviando}
            style={{ background: aceitou ? "#262421" : "#a8a29e", color: "#fff", border: "none", borderRadius: 12, padding: "8px 20px",
              fontSize: 13, fontWeight: 600, cursor: aceitou ? "pointer" : "default", fontFamily: "inherit", opacity: enviando ? 0.7 : 1 }}>
            {enviando ? "Registrando…" : "Aceitar e continuar"}
          </button>
        </div>
      </div>
    </div>
  );
}

if (typeof window !== "undefined") {
  window.PaginaLegal = PaginaLegal;
}


// ════════════════════════════════════════════════════════════
// login.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// LOGIN + CADASTRO SELF-SERVICE — Vicke
// ═══════════════════════════════════════════════════════════════
// 3 telas alternantes (controladas por estado local):
//   1. "login"           — entrada normal por email/senha
//   2. "cadastro-form"   — usuário novo: nome empresa, CNPJ, email, senha
//   3. "cadastro-codigo" — digite código de 6 dígitos enviado por email
//
// Após validar código, recebe JWT e usuário direto via auto-login
// (chama onLogin do pai) — sem precisar fazer login manual depois.

const TOKEN_KEY = "vicke-token";
const USER_KEY  = "vicke-user";

function getToken()   { try { return localStorage.getItem(TOKEN_KEY); } catch { return null; } }
function getUser()    { try { return JSON.parse(localStorage.getItem(USER_KEY)); } catch { return null; } }
function saveAuth(token, usuario) {
  localStorage.setItem(TOKEN_KEY, token);
  localStorage.setItem(USER_KEY, JSON.stringify(usuario));
}
function clearAuth() {
  localStorage.removeItem(TOKEN_KEY);
  localStorage.removeItem(USER_KEY);
}

// POST sem Authorization (auth não tem token ainda)
async function apiPost(path, body) {
  const _url = (typeof API_URL !== "undefined" && API_URL)
    || "https://orbi-production-5f5c.up.railway.app";
  const res = await fetch(_url + path, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(body),
  });
  return res.json();
}

// ───────────────────────────────────────────────────────────────
// Estilos compartilhados pelas 3 telas
// ───────────────────────────────────────────────────────────────
// Paleta oficial do Vicke (grafite + cobre) — ver memória "vicke_paleta_cores".
function getEstilos(loading) {
  return {
    wrap: {
      fontFamily: "'Inter', system-ui, -apple-system, sans-serif",
      minHeight: "100vh",
      display: "flex",
      alignItems: "center",
      justifyContent: "center",
      background: "#fafafb",
      padding: "20px",
    },
    box: { width: "100%", maxWidth: 360 },
    header: { textAlign: "center", marginBottom: 32 },
    titulo: { fontSize: 22, fontWeight: 800, color: "#111827", letterSpacing: -0.5, margin: 0 },
    sub: { fontSize: 13, color: "#4b5563", marginTop: 6 },
    card: { background: "#fff", border: "1.5px solid rgba(38,36,33,0.14)", borderRadius: 16, padding: "28px 24px", boxShadow: "0 18px 50px -28px rgba(38,36,33,0.35)" },
    label: { fontSize: 13, color: "#4b5563", display: "block", marginBottom: 6 },
    input: {
      width: "100%",
      border: "1.5px solid rgba(38,36,33,0.16)",
      borderRadius: 12,
      padding: "11px 14px",
      fontSize: 14,
      color: "#111827",
      outline: "none",
      background: "#fff",
      boxSizing: "border-box",
      fontFamily: "inherit",
      transition: "border-color 0.15s",
    },
    grupo: { marginBottom: 16 },
    btn: {
      width: "100%",
      background: "#262421",
      color: "#fff",
      border: "none",
      borderRadius: 12,
      padding: "12px 0",
      fontSize: 14,
      fontWeight: 600,
      cursor: "pointer",
      fontFamily: "inherit",
      marginTop: 8,
      opacity: loading ? 0.6 : 1,
    },
    btnSec: {
      width: "100%",
      background: "#fff",
      color: "#111827",
      border: "1.5px solid rgba(38,36,33,0.16)",
      borderRadius: 12,
      padding: "12px 0",
      fontSize: 14,
      fontWeight: 500,
      cursor: "pointer",
      fontFamily: "inherit",
      marginTop: 8,
    },
    erro: { fontSize: 13, color: "#dc2626", textAlign: "center", marginTop: 12, minHeight: 20 },
    info: { fontSize: 13, color: "#059669", textAlign: "center", marginTop: 12, minHeight: 20 },
    rodape: { textAlign: "center", marginTop: 24, fontSize: 12, color: "#6b7280" },
    // Link "Criar conta" / "Voltar pro login"
    linkSec: {
      textAlign: "center",
      marginTop: 16,
      fontSize: 13,
      color: "#4b5563",
    },
    linkBtn: {
      background: "none",
      border: "none",
      color: "#0474f4",
      fontWeight: 600,
      cursor: "pointer",
      padding: 0,
      fontSize: 13,
      fontFamily: "inherit",
      textDecoration: "underline",
      textUnderlineOffset: 3,
    },
  };
}

// ═══════════════════════════════════════════════════════════════
// TelaAuth — wrapper que decide entre login / cadastro / código
// ═══════════════════════════════════════════════════════════════
function TelaLogin({ onLogin }) {
  // Estado da tela ativa: "login" | "cadastro-form" | "cadastro-codigo"
  // | "recuperar-senha" | "redefinir-senha"
  // Detecta token de recuperação na URL ao iniciar — se tiver, abre direto
  // a tela de redefinir. Token chega como ?recuperar=xxx.
  const tokenRecuperarInicial = (() => {
    try {
      const params = new URLSearchParams(window.location.search);
      return params.get("recuperar") || null;
    } catch { return null; }
  })();
  const [tela, setTela] = useState(tokenRecuperarInicial ? "redefinir-senha" : "login");
  const [tokenRecuperar] = useState(tokenRecuperarInicial);
  // Email persistido entre telas: usuário digitou no cadastro,
  // precisamos lembrar dele ao mostrar a tela do código.
  const [emailCadastro, setEmailCadastro] = useState("");

  if (tela === "cadastro-form") {
    return (
      <TelaCadastro
        onVoltar={() => setTela("login")}
        onCodigoEnviado={email => {
          setEmailCadastro(email);
          setTela("cadastro-codigo");
        }}
      />
    );
  }

  if (tela === "cadastro-codigo") {
    return (
      <TelaCadastroCodigo
        email={emailCadastro}
        onVoltar={() => setTela("cadastro-form")}
        onValidado={(usuario, token) => {
          saveAuth(token, usuario);
          onLogin(usuario, token);
        }}
      />
    );
  }

  if (tela === "recuperar-senha") {
    return (
      <TelaRecuperarSenha onVoltar={() => setTela("login")} />
    );
  }

  if (tela === "redefinir-senha") {
    return (
      <TelaRedefinirSenha
        token={tokenRecuperar}
        onConcluido={() => {
          // Limpa token da URL pra não ficar visível ao login
          try {
            const url = new URL(window.location.href);
            url.searchParams.delete("recuperar");
            window.history.replaceState({}, "", url.pathname + url.search);
          } catch {}
          setTela("login");
        }}
      />
    );
  }

  return <TelaLoginEntrada onLogin={onLogin} onCriarConta={() => setTela("cadastro-form")} onEsqueciSenha={() => setTela("recuperar-senha")} />;
}

// ═══════════════════════════════════════════════════════════════
// 1. Tela de Login (email + senha)
// ═══════════════════════════════════════════════════════════════
function TelaLoginEntrada({ onLogin, onCriarConta, onEsqueciSenha }) {
  const [email, setEmail]               = useState("");
  const [senha, setSenha]               = useState("");
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [erro, setErro]                 = useState("");
  const [loading, setLoading]           = useState(false);
  const S = getEstilos(loading);

  async function handleLogin() {
    if (!email || !senha) { setErro("Preencha e-mail e senha."); return; }
    setErro("");
    setLoading(true);
    try {
      const res = await apiPost("/auth/login", { email, senha });
      if (res.ok) {
        saveAuth(res.data.token, res.data.usuario);
        onLogin(res.data.usuario, res.data.token);
      } else {
        setErro(res.error || "E-mail ou senha inválidos.");
      }
    } catch (e) {
      console.error("Erro de login:", e);
      setErro("Não foi possível conectar ao servidor.");
    }
    setLoading(false);
  }

  function handleKey(e) { if (e.key === "Enter") handleLogin(); }

  return (
    <div style={S.wrap}>
      <div style={S.box}>
        <div style={S.header}>
          <div style={S.titulo}>Vicke</div>
          <div style={S.sub}>Entre na sua conta</div>
        </div>
        <div style={S.card}>
          <div style={S.grupo}>
            <label style={S.label}>E-mail</label>
            <input
              style={S.input}
              type="email"
              placeholder="seu@email.com"
              value={email}
              onChange={e => setEmail(e.target.value)}
              onKeyDown={handleKey}
              autoFocus
            />
          </div>
          <div style={S.grupo}>
            <label style={S.label}>Senha</label>
            <div style={{ position:"relative" }}>
              <input
                style={{ ...S.input, paddingRight: 40 }}
                type={mostrarSenha ? "text" : "password"}
                placeholder="••••••••"
                value={senha}
                onChange={e => setSenha(e.target.value)}
                onKeyDown={handleKey}
              />
              <button
                type="button"
                onClick={() => setMostrarSenha(v => !v)}
                aria-label={mostrarSenha ? "Ocultar senha" : "Mostrar senha"}
                title={mostrarSenha ? "Ocultar senha" : "Mostrar senha"}
                style={{
                  position:"absolute", right: 8, top:"50%", transform:"translateY(-50%)",
                  background:"none", border:"none", padding: 6, cursor:"pointer",
                  color:"#4b5563", display:"flex", alignItems:"center", justifyContent:"center",
                  borderRadius: 6,
                }}
                onMouseEnter={e => { e.currentTarget.style.color = "#374151"; e.currentTarget.style.background = "#f3f4f6"; }}
                onMouseLeave={e => { e.currentTarget.style.color = "#9ca3af"; e.currentTarget.style.background = "none"; }}
              >
                {mostrarSenha ? (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M9.88 9.88a3 3 0 1 0 4.24 4.24"/>
                    <path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"/>
                    <path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"/>
                    <line x1="2" y1="2" x2="22" y2="22"/>
                  </svg>
                ) : (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/>
                    <circle cx="12" cy="12" r="3"/>
                  </svg>
                )}
              </button>
            </div>
          </div>
          <button style={S.btn} onClick={handleLogin} disabled={loading}>
            {loading ? "Entrando..." : "Entrar"}
          </button>
          {erro && <div style={S.erro}>{erro}</div>}
          {/* Link de recuperação — discreto, abaixo do botão Entrar.
              Padrão UX universal pra logins. */}
          <div style={{ textAlign:"center", marginTop:14 }}>
            <button
              type="button"
              onClick={onEsqueciSenha}
              style={{
                background:"none", border:"none", padding:0, cursor:"pointer",
                fontFamily:"inherit", fontSize:12.5, color:"#4b5563",
                textDecoration:"underline", textUnderlineOffset:2,
              }}
              onMouseEnter={e => { e.currentTarget.style.color = "#374151"; }}
              onMouseLeave={e => { e.currentTarget.style.color = "#9ca3af"; }}>
              Esqueci minha senha
            </button>
          </div>
        </div>
        {/* Link de cadastro — caminho de baixa fricção pra novos usuários */}
        <div style={S.linkSec}>
          Não tem conta?{" "}
          <button style={S.linkBtn} onClick={onCriarConta}>Criar conta</button>
        </div>
        <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 2. Tela de Cadastro (form com dados da empresa + admin)
// ═══════════════════════════════════════════════════════════════
// Links da Política de Privacidade e dos Termos, no rodapé das telas de acesso
function LinksLegais() {
  const a = { color: "#6b7280", textDecoration: "underline", fontSize: 11.5 };
  return (
    <div data-vk-links-legais="1" style={{ marginTop: 6, display: "flex", gap: 12, justifyContent: "center" }}>
      <a href="/privacidade" target="_blank" rel="noopener noreferrer" style={a}>Privacidade</a>
      <a href="/termos" target="_blank" rel="noopener noreferrer" style={a}>Termos de uso</a>
    </div>
  );
}

function TelaCadastro({ onVoltar, onCodigoEnviado }) {
  const [nomeEmpresa, setNomeEmpresa]   = useState("");
  const [cnpjCpf, setCnpjCpf]           = useState("");
  const [nomeResp, setNomeResp]         = useState("");
  const [email, setEmail]               = useState("");
  const [senha, setSenha]               = useState("");
  const [mostrarSenha, setMostrarSenha] = useState(false);
  const [aceitouTermos, setAceitouTermos] = useState(false);
  const [erro, setErro]                 = useState("");
  const [loading, setLoading]           = useState(false);
  const S = getEstilos(loading);

  async function handleCadastrar() {
    setErro("");
    if (!nomeEmpresa.trim()) return setErro("Informe o nome do escritório.");
    if (!nomeResp.trim())    return setErro("Informe seu nome.");
    if (!email.trim())       return setErro("Informe seu e-mail.");
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) return setErro("E-mail inválido.");
    if (senha.length < 8)    return setErro("Senha deve ter no mínimo 8 caracteres.");
    if (!aceitouTermos)      return setErro("Para criar a conta, aceite os Termos de Uso, o Acordo de Tratamento de Dados e a Política de Privacidade.");

    setLoading(true);
    try {
      const res = await apiPost("/auth/signup-iniciar", {
        nome_empresa: nomeEmpresa,
        cnpj_cpf: cnpjCpf || null,
        nome_responsavel: nomeResp,
        email,
        senha,
        aceite_termos: typeof LEGAL_VERSAO !== "undefined" ? LEGAL_VERSAO : "",
      });
      if (res.ok) {
        // Sobe pra próxima tela com email memorizado
        onCodigoEnviado(email.trim().toLowerCase());
      } else {
        setErro(res.error || "Não foi possível criar a conta.");
      }
    } catch (e) {
      console.error("Erro signup:", e);
      setErro("Não foi possível conectar ao servidor.");
    }
    setLoading(false);
  }

  return (
    <div style={S.wrap}>
      <div style={S.box}>
        <div style={S.header}>
          <div style={S.titulo}>Criar conta</div>
          <div style={S.sub}>Preencha os dados pra começar</div>
        </div>
        <div style={S.card}>
          <div style={S.grupo}>
            <label style={S.label}>Nome do escritório *</label>
            <input
              style={S.input}
              placeholder="Ex: Vicke Associados"
              value={nomeEmpresa}
              onChange={e => setNomeEmpresa(e.target.value)}
              autoFocus
            />
          </div>
          <div style={S.grupo}>
            <label style={S.label}>CNPJ / CPF <span style={{ color:"#4b5563", fontWeight:400 }}>(opcional)</span></label>
            <input
              style={S.input}
              placeholder="00.000.000/0001-00"
              value={cnpjCpf}
              onChange={e => setCnpjCpf(e.target.value)}
            />
          </div>
          <div style={S.grupo}>
            <label style={S.label}>Seu nome *</label>
            <input
              style={S.input}
              placeholder="Como você quer ser chamado"
              value={nomeResp}
              onChange={e => setNomeResp(e.target.value)}
            />
          </div>
          <div style={S.grupo}>
            <label style={S.label}>E-mail *</label>
            <input
              style={S.input}
              type="email"
              placeholder="seu@email.com"
              value={email}
              onChange={e => setEmail(e.target.value)}
            />
          </div>
          <div style={S.grupo}>
            <label style={S.label}>Senha * <span style={{ color:"#4b5563", fontWeight:400 }}>(mínimo 8 caracteres)</span></label>
            <div style={{ position:"relative" }}>
              <input
                style={{ ...S.input, paddingRight: 40 }}
                type={mostrarSenha ? "text" : "password"}
                placeholder="••••••••"
                value={senha}
                onChange={e => setSenha(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter") handleCadastrar(); }}
              />
              <button
                type="button"
                onClick={() => setMostrarSenha(v => !v)}
                aria-label={mostrarSenha ? "Ocultar senha" : "Mostrar senha"}
                style={{
                  position:"absolute", right: 8, top:"50%", transform:"translateY(-50%)",
                  background:"none", border:"none", padding: 6, cursor:"pointer",
                  color:"#4b5563", display:"flex", alignItems:"center", justifyContent:"center",
                  borderRadius: 6,
                }}
                onMouseEnter={e => { e.currentTarget.style.color = "#374151"; e.currentTarget.style.background = "#f3f4f6"; }}
                onMouseLeave={e => { e.currentTarget.style.color = "#9ca3af"; e.currentTarget.style.background = "none"; }}
              >
                {mostrarSenha ? (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M9.88 9.88a3 3 0 1 0 4.24 4.24"/>
                    <path d="M10.73 5.08A10.43 10.43 0 0 1 12 5c7 0 10 7 10 7a13.16 13.16 0 0 1-1.67 2.68"/>
                    <path d="M6.61 6.61A13.526 13.526 0 0 0 2 12s3 7 10 7a9.74 9.74 0 0 0 5.39-1.61"/>
                    <line x1="2" y1="2" x2="22" y2="22"/>
                  </svg>
                ) : (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M2 12s3-7 10-7 10 7 10 7-3 7-10 7-10-7-10-7Z"/>
                    <circle cx="12" cy="12" r="3"/>
                  </svg>
                )}
              </button>
            </div>
          </div>
          <label data-vk-cadastro-termos="1" style={{ display:"flex", gap:8, alignItems:"flex-start", fontSize:12.5, color:"#374151", lineHeight:1.5, cursor:"pointer", margin:"4px 0 12px" }}>
            <input type="checkbox" checked={aceitouTermos} onChange={e => setAceitouTermos(e.target.checked)} style={{ marginTop:3, accentColor:"#0474f4" }} />
            <span>
              Li e aceito os <a href="/termos" target="_blank" rel="noopener noreferrer" style={{ color:"#0474f4" }}>Termos de Uso e o Acordo de Tratamento de Dados</a> e
              a <a href="/privacidade" target="_blank" rel="noopener noreferrer" style={{ color:"#0474f4" }}>Política de Privacidade</a>.
            </span>
          </label>
          <button style={S.btn} onClick={handleCadastrar} disabled={loading}>
            {loading ? "Enviando código..." : "Continuar"}
          </button>
          {erro && <div style={S.erro}>{erro}</div>}
        </div>
        <div style={S.linkSec}>
          Já tem conta?{" "}
          <button style={S.linkBtn} onClick={onVoltar}>Entrar</button>
        </div>
        <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 3. Tela do código (6 dígitos enviados por email)
// ═══════════════════════════════════════════════════════════════
function TelaCadastroCodigo({ email, onVoltar, onValidado }) {
  // 6 dígitos individuais — UX padrão de OTP (Stripe, Vercel, Linear)
  // Refs pra mover foco automaticamente entre inputs
  const [digitos, setDigitos] = useState(["", "", "", "", "", ""]);
  const [erro, setErro]       = useState("");
  const [info, setInfo]       = useState("");
  const [loading, setLoading] = useState(false);
  const [reenviando, setReenviando] = useState(false);
  // Cooldown do botão "Reenviar" (60s) — evita spam
  const [cooldown, setCooldown] = useState(0);
  const refsInputs = useRef([]);
  const S = getEstilos(loading);

  // Auto-foca primeiro input ao montar
  useEffect(() => {
    if (refsInputs.current[0]) refsInputs.current[0].focus();
  }, []);

  // Decrementa cooldown a cada segundo
  useEffect(() => {
    if (cooldown <= 0) return;
    const t = setTimeout(() => setCooldown(c => c - 1), 1000);
    return () => clearTimeout(t);
  }, [cooldown]);

  function handleChangeDigito(idx, valor) {
    // Aceita só dígitos. Se colaram número longo, distribui pelos campos.
    const limpo = valor.replace(/\D/g, "");
    if (!limpo) {
      setDigitos(d => { const n = [...d]; n[idx] = ""; return n; });
      return;
    }
    if (limpo.length === 1) {
      setDigitos(d => { const n = [...d]; n[idx] = limpo; return n; });
      // Auto-avança próximo input
      if (idx < 5 && refsInputs.current[idx + 1]) refsInputs.current[idx + 1].focus();
    } else {
      // Colaram >1 dígito: distribui a partir do idx atual
      setDigitos(d => {
        const n = [...d];
        for (let i = 0; i < limpo.length && idx + i < 6; i++) {
          n[idx + i] = limpo[i];
        }
        return n;
      });
      // Foca no próximo após o último preenchido (ou último input)
      const proxIdx = Math.min(idx + limpo.length, 5);
      if (refsInputs.current[proxIdx]) refsInputs.current[proxIdx].focus();
    }
  }

  function handleKeyDown(idx, e) {
    if (e.key === "Backspace" && !digitos[idx] && idx > 0) {
      // Backspace em campo vazio: volta pro anterior
      refsInputs.current[idx - 1].focus();
    }
    if (e.key === "Enter") {
      handleValidar();
    }
  }

  // Auto-valida quando todos 6 dígitos preenchem
  useEffect(() => {
    if (digitos.every(d => d !== "")) {
      handleValidar();
    }
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [digitos]);

  async function handleValidar() {
    const codigo = digitos.join("");
    if (codigo.length !== 6) return setErro("Digite os 6 dígitos.");
    setErro("");
    setInfo("");
    setLoading(true);
    try {
      const res = await apiPost("/auth/signup-validar", { email, codigo });
      if (res.ok) {
        // JWT + usuário retornados — auto-login
        onValidado(res.data.usuario, res.data.token);
      } else {
        setErro(res.error || "Código inválido.");
        // Limpa os dígitos pra usuário tentar de novo
        setDigitos(["", "", "", "", "", ""]);
        if (refsInputs.current[0]) refsInputs.current[0].focus();
      }
    } catch (e) {
      console.error("Erro validar código:", e);
      setErro("Não foi possível conectar ao servidor.");
    }
    setLoading(false);
  }

  async function handleReenviar() {
    if (cooldown > 0) return;
    setReenviando(true);
    setErro("");
    setInfo("");
    try {
      const res = await apiPost("/auth/signup-reenviar", { email });
      if (res.ok) {
        setInfo("Novo código enviado para seu e-mail.");
        setCooldown(60);
        setDigitos(["", "", "", "", "", ""]);
        if (refsInputs.current[0]) refsInputs.current[0].focus();
      } else {
        setErro(res.error || "Não foi possível reenviar o código.");
      }
    } catch (e) {
      console.error("Erro reenviar:", e);
      setErro("Não foi possível conectar ao servidor.");
    }
    setReenviando(false);
  }

  // Estilo dos 6 inputs do código — quadradinhos grandes
  const inputCodigo = {
    width: 44,
    height: 52,
    border: "1.5px solid rgba(38,36,33,0.16)",
    borderRadius: 12,
    fontSize: 22,
    fontWeight: 600,
    color: "#111827",
    textAlign: "center",
    outline: "none",
    background: "#fff",
    fontFamily: "'SF Mono', Menlo, Consolas, monospace",
    padding: 0,
    transition: "border-color 0.15s, box-shadow 0.15s",
  };

  return (
    <div style={S.wrap}>
      <div style={S.box}>
        <div style={S.header}>
          <div style={S.titulo}>Digite o código</div>
          <div style={S.sub}>
            Enviamos um código de 6 dígitos para<br/>
            <span style={{ color:"#111827", fontWeight:500 }}>{email}</span>
          </div>
        </div>
        <div style={S.card}>
          {/* 6 quadradinhos pra dígito */}
          <div style={{ display:"flex", justifyContent:"space-between", gap:6, marginBottom:20 }}>
            {digitos.map((d, idx) => (
              <input
                key={idx}
                ref={el => { refsInputs.current[idx] = el; }}
                type="text"
                inputMode="numeric"
                maxLength={6}
                value={d}
                onChange={e => handleChangeDigito(idx, e.target.value)}
                onKeyDown={e => handleKeyDown(idx, e)}
                onFocus={e => { e.currentTarget.style.borderColor = "#0474f4"; }}
                onBlur={e => { e.currentTarget.style.borderColor = "rgba(38,36,33,0.16)"; }}
                style={inputCodigo}
                disabled={loading}
              />
            ))}
          </div>
          <button style={S.btn} onClick={handleValidar} disabled={loading}>
            {loading ? "Validando..." : "Confirmar"}
          </button>
          {erro && <div style={S.erro}>{erro}</div>}
          {info && <div style={S.info}>{info}</div>}
          <div style={{ textAlign:"center", marginTop:16 }}>
            <button
              style={{
                background:"none", border:"none", color: cooldown > 0 ? "#c9c4bd" : "#6b7280",
                fontSize: 13, cursor: cooldown > 0 ? "default" : "pointer", fontFamily:"inherit",
                padding: 4,
              }}
              onClick={handleReenviar}
              disabled={cooldown > 0 || reenviando}
            >
              {reenviando ? "Reenviando..." : cooldown > 0 ? `Reenviar código em ${cooldown}s` : "Não recebeu? Reenviar código"}
            </button>
          </div>
        </div>
        <div style={S.linkSec}>
          <button style={S.linkBtn} onClick={onVoltar}>← Voltar</button>
        </div>
        <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 4. Tela de Recuperar Senha (digite email → recebe link)
// ═══════════════════════════════════════════════════════════════
// Anti-enumeração: backend sempre retorna sucesso, então UI também
// mostra a mesma mensagem de "se existir, vai receber". Não vazamos
// se o email existe ou não.
function TelaRecuperarSenha({ onVoltar }) {
  const [email, setEmail]   = useState("");
  const [loading, setLoading] = useState(false);
  const [enviado, setEnviado] = useState(false);
  const [erro, setErro]     = useState("");
  const S = getEstilos(loading);

  async function handleEnviar() {
    const e = email.trim();
    if (!e) { setErro("Digite seu e-mail."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e)) { setErro("E-mail inválido."); return; }
    setErro("");
    setLoading(true);
    try {
      const res = await apiPost("/auth/recuperar-senha", { email: e });
      if (res.ok) {
        setEnviado(true);
      } else {
        setErro(res.error || "Não foi possível processar a solicitação.");
      }
    } catch (err) {
      console.error("Erro recuperar senha:", err);
      setErro("Não foi possível conectar ao servidor.");
    }
    setLoading(false);
  }

  function handleKey(ev) { if (ev.key === "Enter") handleEnviar(); }

  // Tela de confirmação após envio. Texto é genérico de propósito —
  // não confirma se o email realmente existe (anti-enumeração).
  if (enviado) {
    return (
      <div style={S.wrap}>
        <div style={S.box}>
          <div style={S.header}>
            <div style={S.titulo}>Vicke</div>
            <div style={S.sub}>Verifique seu e-mail</div>
          </div>
          <div style={S.card}>
            <div style={{ fontSize:13.5, color:"#111827", lineHeight:1.6, textAlign:"center" }}>
              Se houver uma conta com o e-mail informado, você receberá em instantes um link para redefinir sua senha.
            </div>
            <div style={{ fontSize:12, color:"#4b5563", lineHeight:1.5, marginTop:14, textAlign:"center" }}>
              O link expira em 1 hora. Verifique também a pasta de spam.
            </div>
          </div>
          <div style={S.linkSec}>
            <button style={S.linkBtn} onClick={onVoltar}>← Voltar para o login</button>
          </div>
          <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
        </div>
      </div>
    );
  }

  return (
    <div style={S.wrap}>
      <div style={S.box}>
        <div style={S.header}>
          <div style={S.titulo}>Vicke</div>
          <div style={S.sub}>Recuperar senha</div>
        </div>
        <div style={S.card}>
          <div style={{ fontSize:12.5, color:"#4b5563", lineHeight:1.5, marginBottom:16 }}>
            Digite o e-mail da sua conta. Vamos te enviar um link para criar uma nova senha.
          </div>
          <div style={S.grupo}>
            <label style={S.label}>E-mail</label>
            <input
              style={S.input}
              type="email"
              placeholder="seu@email.com"
              value={email}
              onChange={ev => setEmail(ev.target.value)}
              onKeyDown={handleKey}
              autoFocus
            />
          </div>
          <button style={S.btn} onClick={handleEnviar} disabled={loading}>
            {loading ? "Enviando..." : "Enviar link"}
          </button>
          {erro && <div style={S.erro}>{erro}</div>}
        </div>
        <div style={S.linkSec}>
          <button style={S.linkBtn} onClick={onVoltar}>← Voltar para o login</button>
        </div>
        <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
      </div>
    </div>
  );
}

// ═══════════════════════════════════════════════════════════════
// 5. Tela de Redefinir Senha (com token vindo do link do email)
// ═══════════════════════════════════════════════════════════════
function TelaRedefinirSenha({ token, onConcluido }) {
  const [senha, setSenha]                 = useState("");
  const [confirmar, setConfirmar]         = useState("");
  const [mostrarSenha, setMostrarSenha]   = useState(false);
  const [erro, setErro]                   = useState("");
  const [loading, setLoading]             = useState(false);
  const [sucesso, setSucesso]             = useState(false);
  const S = getEstilos(loading);

  async function handleRedefinir() {
    if (!token) { setErro("Link inválido ou expirado."); return; }
    if (senha.length < 8) { setErro("A senha precisa ter pelo menos 8 caracteres."); return; }
    if (senha !== confirmar) { setErro("As senhas não coincidem."); return; }
    setErro("");
    setLoading(true);
    try {
      const res = await apiPost("/auth/redefinir-senha", { token, senha_nova: senha });
      if (res.ok) {
        setSucesso(true);
        // Volta pro login automaticamente após 2.5s
        setTimeout(onConcluido, 2500);
      } else {
        setErro(res.error || "Não foi possível redefinir a senha.");
      }
    } catch (e) {
      console.error("Erro redefinir senha:", e);
      setErro("Não foi possível conectar ao servidor.");
    }
    setLoading(false);
  }

  function handleKey(ev) { if (ev.key === "Enter") handleRedefinir(); }

  // Sem token na URL — usuário caiu aqui sem clicar no link válido.
  // Não acontece em fluxo normal (TelaLogin só roteia aqui se tiver token).
  // Mas defesa em profundidade.
  if (!token) {
    return (
      <div style={S.wrap}>
        <div style={S.box}>
          <div style={S.header}>
            <div style={S.titulo}>Vicke</div>
            <div style={S.sub}>Link inválido</div>
          </div>
          <div style={S.card}>
            <div style={{ fontSize:13.5, color:"#111827", lineHeight:1.6, textAlign:"center" }}>
              Este link de redefinição de senha não é válido ou já foi usado.
            </div>
          </div>
          <div style={S.linkSec}>
            <button style={S.linkBtn} onClick={onConcluido}>← Voltar para o login</button>
          </div>
          <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
        </div>
      </div>
    );
  }

  if (sucesso) {
    return (
      <div style={S.wrap}>
        <div style={S.box}>
          <div style={S.header}>
            <div style={S.titulo}>Vicke</div>
            <div style={S.sub}>Senha redefinida</div>
          </div>
          <div style={S.card}>
            <div style={{ display:"flex", justifyContent:"center", marginBottom:14 }}>
              <div style={{
                width:48, height:48, borderRadius:"50%",
                background:"#262421", color:"#fff",
                display:"flex", alignItems:"center", justifyContent:"center",
              }}>
                <svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                  <polyline points="20 6 9 17 4 12"/>
                </svg>
              </div>
            </div>
            <div style={{ fontSize:14, fontWeight:600, color:"#111827", textAlign:"center", marginBottom:6 }}>
              Pronto!
            </div>
            <div style={{ fontSize:13, color:"#4b5563", textAlign:"center", lineHeight:1.5 }}>
              Sua senha foi redefinida. Você já pode entrar com a nova senha.
            </div>
          </div>
          <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
        </div>
      </div>
    );
  }

  return (
    <div style={S.wrap}>
      <div style={S.box}>
        <div style={S.header}>
          <div style={S.titulo}>Vicke</div>
          <div style={S.sub}>Crie uma nova senha</div>
        </div>
        <div style={S.card}>
          <div style={{ fontSize:12.5, color:"#4b5563", lineHeight:1.5, marginBottom:16 }}>
            Digite a nova senha que você quer usar a partir de agora. Mínimo de 8 caracteres.
          </div>
          <div style={S.grupo}>
            <label style={S.label}>Nova senha</label>
            <div style={{ position:"relative" }}>
              <input
                style={{ ...S.input, paddingRight: 40 }}
                type={mostrarSenha ? "text" : "password"}
                placeholder="••••••••"
                value={senha}
                onChange={ev => setSenha(ev.target.value)}
                onKeyDown={handleKey}
                autoFocus
              />
              <button
                type="button"
                onClick={() => setMostrarSenha(v => !v)}
                aria-label={mostrarSenha ? "Ocultar senha" : "Mostrar senha"}
                style={{
                  position:"absolute", right: 8, top:"50%", transform:"translateY(-50%)",
                  background:"none", border:"none", padding: 6, cursor:"pointer",
                  color:"#4b5563", display:"flex", alignItems:"center", justifyContent:"center",
                  borderRadius: 6,
                }}>
                {mostrarSenha ? (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M17.94 17.94A10.07 10.07 0 0 1 12 20c-7 0-11-8-11-8a18.45 18.45 0 0 1 5.06-5.94M9.9 4.24A9.12 9.12 0 0 1 12 4c7 0 11 8 11 8a18.5 18.5 0 0 1-2.16 3.19m-6.72-1.07a3 3 0 1 1-4.24-4.24"/>
                    <line x1="1" y1="1" x2="23" y2="23"/>
                  </svg>
                ) : (
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M1 12s4-8 11-8 11 8 11 8-4 8-11 8-11-8-11-8z"/>
                    <circle cx="12" cy="12" r="3"/>
                  </svg>
                )}
              </button>
            </div>
          </div>
          <div style={S.grupo}>
            <label style={S.label}>Confirmar nova senha</label>
            <input
              style={S.input}
              type={mostrarSenha ? "text" : "password"}
              placeholder="••••••••"
              value={confirmar}
              onChange={ev => setConfirmar(ev.target.value)}
              onKeyDown={handleKey}
            />
          </div>
          <button style={S.btn} onClick={handleRedefinir} disabled={loading}>
            {loading ? "Redefinindo..." : "Redefinir senha"}
          </button>
          {erro && <div style={S.erro}>{erro}</div>}
        </div>
        <div style={S.linkSec}>
          <button style={S.linkBtn} onClick={onConcluido}>← Voltar para o login</button>
        </div>
        <div style={S.rodape}>Vicke — Conectando elos<LinksLegais /></div>
      </div>
    </div>
  );
}


// ════════════════════════════════════════════════════════════
// mensagens.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// MENSAGENS — Caixa de email do Time VICKE (Sprint 3 Bloco E)
// ═══════════════════════════════════════════════════════════════
// Master vê todas as mensagens recebidas em qualquer endereço
// @vicke.com.br (time@, contato@, suporte@, etc).
// Webhook do Resend salva tudo na tabela mensagem_recebida; aqui
// listamos, lemos detalhe e marcamos como lida/excluímos.
//
// Layout 2 colunas estilo email client:
//   - Esquerda: lista de threads (remetente, assunto, preview, data)
//   - Direita: detalhe da mensagem selecionada (HTML renderizado)
//
// Backend endpoints:
//   GET    /admin/mensagens               — lista paginada
//   GET    /admin/mensagens/:id           — detalhe completo
//   PUT    /admin/mensagens/:id/lida      — marca como lida
//   PUT    /admin/mensagens/:id/nao-lida  — marca como não lida
//   DELETE /admin/mensagens/:id           — apaga

function Mensagens({ usuario }) {
  const [mensagens, setMensagens] = useState([]);
  const [naoLidas, setNaoLidas]   = useState(0);
  const [loading, setLoading]     = useState(true);
  const [erro, setErro]           = useState(null);
  const [filtro, setFiltro]       = useState("todas"); // "todas" | "nao-lidas"
  // Mensagem selecionada (objeto com body completo carregado sob demanda)
  const [selecionada, setSelecionada] = useState(null);
  // No celular não cabem lista e mensagem lado a lado: mostra uma de cada
  // vez (a lista; tocou, a mensagem com "← Voltar").
  const [estreito, setEstreito] = useState(typeof window !== "undefined" && window.innerWidth < 700);
  useEffect(() => {
    const f = () => setEstreito(window.innerWidth < 700);
    window.addEventListener("resize", f);
    return () => window.removeEventListener("resize", f);
  }, []);
  const [carregandoDet, setCarregandoDet] = useState(false);
  // Modal de Responder
  const [respondendo, setRespondendo]       = useState(null); // mensagem a responder, ou null
  const [respAssunto, setRespAssunto]       = useState("");
  const [respCorpo, setRespCorpo]           = useState("");
  const [enviandoResp, setEnviandoResp]     = useState(false);

  // Carrega lista quando filtro muda ou ao montar
  useEffect(() => {
    carregarLista();
    // Polling a cada 30s pra detectar novas mensagens.
    // Não é tempo real (precisaria SSE/WebSocket), mas pra volume baixo
    // de email do Master é suficiente e simples.
    const t = setInterval(carregarLista, 30000);
    return () => clearInterval(t);
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [filtro]);

  async function carregarLista() {
    try {
      const filtroParam = filtro === "nao-lidas" ? "nao-lidas" : null;
      const data = await api.admin.mensagens.list(filtroParam);
      // api retorna json.data direto (req() já desempacota), então `data` aqui
      // é { mensagens, total, nao_lidas }
      setMensagens(data.mensagens || []);
      setNaoLidas(data.nao_lidas || 0);
    } catch (e) {
      console.error("Erro carregar mensagens:", e);
      setErro(e.message);
    }
    setLoading(false);
  }

  async function abrirMensagem(msg) {
    // Otimista: já mostra os dados que temos (preview, etc)
    setSelecionada(msg);
    setCarregandoDet(true);
    try {
      const detalhe = await api.admin.mensagens.get(msg.id);
      setSelecionada(detalhe);
      // Se ainda não lida, marca como lida automaticamente ao abrir
      if (!detalhe.lida) {
        await api.admin.mensagens.marcarLida(msg.id);
        // Atualiza lista local sem refetch
        setMensagens(ms => ms.map(m => m.id === msg.id ? { ...m, lida: true } : m));
        setNaoLidas(n => Math.max(0, n - 1));
      }
    } catch (e) {
      console.error("Erro ao abrir mensagem:", e);
    }
    setCarregandoDet(false);
  }

  async function marcarNaoLida(msg) {
    try {
      await api.admin.mensagens.marcarNaoLida(msg.id);
      setMensagens(ms => ms.map(m => m.id === msg.id ? { ...m, lida: false } : m));
      setNaoLidas(n => n + 1);
      if (selecionada?.id === msg.id) {
        setSelecionada({ ...selecionada, lida: false });
      }
    } catch (e) {
      toast.erro("Erro ao marcar como não lida");
    }
  }

  async function excluirMensagem(msg) {
    const ok = await dialogo.confirmar({
      titulo: "Excluir mensagem?",
      mensagem: `Esta ação não pode ser desfeita. A mensagem de "${msg.de}" será apagada permanentemente.`,
      confirmar: "Excluir",
      destrutivo: true,
    });
    if (!ok) return;
    try {
      await api.admin.mensagens.delete(msg.id);
      setMensagens(ms => ms.filter(m => m.id !== msg.id));
      if (selecionada?.id === msg.id) setSelecionada(null);
      if (!msg.lida) setNaoLidas(n => Math.max(0, n - 1));
      toast.sucesso("Mensagem excluída");
    } catch (e) {
      toast.erro("Erro ao excluir");
    }
  }

  function abrirResponder(msg) {
    // Pré-preenche o assunto com "Re: " se ainda não tiver.
    // Isso é convenção universal de email reply.
    const assuntoOriginal = msg.assunto || "";
    const novoAssunto = assuntoOriginal.match(/^re:\s/i)
      ? assuntoOriginal
      : `Re: ${assuntoOriginal || "(sem assunto)"}`;

    // Quote do email original (padrão de email client). Usa body_text;
    // se só tem HTML, faz um stripping simples pra não poluir a resposta.
    const dataFormatada = new Date(msg.recebido_em).toLocaleString("pt-BR", {
      day:"2-digit", month:"long", year:"numeric",
      hour:"2-digit", minute:"2-digit",
    });
    let textoOriginal = msg.body_text || "";
    if (!textoOriginal && msg.body_html) {
      // Strip HTML simples — só pra ter algo no quote. Não é parser robusto
      // mas é suficiente pra dar contexto na resposta.
      textoOriginal = msg.body_html
        .replace(/<style[^>]*>[\s\S]*?<\/style>/gi, "")
        .replace(/<script[^>]*>[\s\S]*?<\/script>/gi, "")
        .replace(/<br\s*\/?>/gi, "\n")
        .replace(/<\/p>/gi, "\n\n")
        .replace(/<[^>]+>/g, "")
        .replace(/&nbsp;/g, " ")
        .replace(/&amp;/g, "&")
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/\n{3,}/g, "\n\n")
        .trim();
    }
    const quote = textoOriginal
      ? `\n\n\n\nEm ${dataFormatada}, ${msg.de} escreveu:\n${textoOriginal.split("\n").map(l => `> ${l}`).join("\n")}`
      : "";

    setRespondendo(msg);
    setRespAssunto(novoAssunto);
    setRespCorpo(quote);
  }

  function fecharResponder() {
    setRespondendo(null);
    setRespAssunto("");
    setRespCorpo("");
  }

  async function enviarResposta() {
    if (!respondendo) return;
    if (!respAssunto.trim()) {
      toast.erro("Informe o assunto");
      return;
    }
    if (!respCorpo.trim()) {
      toast.erro("Escreva uma mensagem");
      return;
    }
    setEnviandoResp(true);
    try {
      const resp = await api.admin.mensagens.responder(respondendo.id, {
        assunto: respAssunto.trim(),
        corpo: respCorpo,
      });
      toast.sucesso(`Resposta enviada para ${resp.destinatario}`);
      fecharResponder();
    } catch (e) {
      console.error("Erro ao responder:", e);
      toast.erro("Falha ao enviar: " + (e.message || "erro desconhecido"));
    }
    setEnviandoResp(false);
  }

  // Helper: parser do "from" do Resend — vem como "Nome <email@dominio>"
  // Extrai nome (se houver) e email separados pra exibição.
  function parsearRemetente(de) {
    if (!de) return { nome: "", email: "" };
    const match = de.match(/^(.+?)\s*<(.+?)>$/);
    if (match) return { nome: match[1].trim().replace(/^"|"$/g, ""), email: match[2].trim() };
    return { nome: "", email: de.trim() };
  }

  function formatarData(iso) {
    if (!iso) return "";
    const d = new Date(iso);
    const agora = new Date();
    const ms = agora - d;
    const min = Math.floor(ms / 60000);
    const hr = Math.floor(ms / 3600000);
    const dias = Math.floor(ms / 86400000);
    if (min < 1) return "agora";
    if (min < 60) return `${min}m`;
    if (hr < 24) return `${hr}h`;
    if (dias < 7) return `${dias}d`;
    return d.toLocaleDateString("pt-BR", { day: "2-digit", month: "short" });
  }

  const S = {
    wrap: { fontFamily:"'Inter', system-ui, -apple-system, sans-serif", height:"100vh", display:"flex", flexDirection:"column", background:"#fff" },
    header: { borderBottom:"1.5px solid rgba(38,36,33,0.16)", padding:"20px 32px", display:"flex", justifyContent:"space-between", alignItems:"center" },
    titulo: { fontSize:18, fontWeight:700, color:"#111827", margin:0 },
    sub: { fontSize:13, color:"#4b5563", marginTop:3 },
    filtros: { display:"flex", gap:4, padding:"12px 32px", borderBottom:"1px solid #f3f4f6" },
    btnFiltro: (ativo) => ({
      background: "transparent",
      color: ativo ? "#0474f4" : "#4b5563",
      border: "none",
      borderRadius: 6,
      padding: "6px 12px",
      fontSize: 12.5,
      fontWeight: ativo ? 600 : 400,
      cursor: "pointer",
      fontFamily: "inherit",
    }),
    body: { flex:1, display:"flex", overflow:"hidden" },
    listaCol: { width:380, minWidth:380, borderRight:"1.5px solid rgba(38,36,33,0.16)", overflowY:"auto", background:"#fff" },
    detalheCol: { flex:1, overflowY:"auto", background:"#fafbfc" },
    item: (selecionada, lida) => ({
      padding:"14px 18px",
      borderBottom:"1px solid #f3f4f6",
      cursor:"pointer",
      background: selecionada ? "#f9fafb" : "#fff",
      borderLeft: selecionada ? "3px solid #262421" : "3px solid transparent",
      transition: "background 0.1s",
      paddingLeft: selecionada ? 15 : 18,
    }),
    nome: (lida) => ({ fontSize:13, fontWeight: lida ? 400 : 700, color:"#111827", marginBottom:2, display:"flex", justifyContent:"space-between", alignItems:"center" }),
    assunto: (lida) => ({ fontSize:13, fontWeight: lida ? 400 : 600, color: lida ? "#374151" : "#262421", marginBottom:3, overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }),
    preview: { fontSize:12, color:"#4b5563", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" },
    data: { fontSize:11, color:"#4b5563", fontWeight:400 },
    pontoNaoLida: { display:"inline-block", width:8, height:8, background:"#3b82f6", borderRadius:"50%", marginRight:8, flexShrink:0 },
    vazio: { fontSize:13, color:"#4b5563", textAlign:"center", padding:"60px 20px" },

    detHeader: { padding:"24px 32px", borderBottom:"1.5px solid rgba(38,36,33,0.16)", background:"#fff" },
    detAssunto: { fontSize:18, fontWeight:700, color:"#111827", marginBottom:12 },
    detLinha: { fontSize:13, color:"#4b5563", marginBottom:4 },
    detLinhaForte: { fontSize:14, color:"#111827", fontWeight:500 },
    detAcoes: { display:"flex", gap:8, marginTop:16 },
    detBody: { padding:"32px", background:"#fff", margin:"24px 32px", borderRadius: 12, border:"1px solid #f3f4f6" },
    detHtml: { fontSize:14, color:"#111827", lineHeight:1.6 },
    btnAcao: { background:"#fff", color:"#111827", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius:7, padding:"6px 12px", fontSize:12.5, cursor:"pointer", fontFamily:"inherit", display:"inline-flex", alignItems:"center", gap:6 },
    btnAcaoPrimaria: { background:"#262421", color:"#fff", border:"1px solid #262421", borderRadius:7, padding:"6px 14px", fontSize:12.5, fontWeight:600, cursor:"pointer", fontFamily:"inherit", display:"inline-flex", alignItems:"center", gap:6 },
    btnAcaoDestrutiva: { background:"#fff", color:"#dc2626", border:"1px solid #fecaca", borderRadius:7, padding:"6px 12px", fontSize:12.5, cursor:"pointer", fontFamily:"inherit", display:"inline-flex", alignItems:"center", gap:6 },
    badge: { display:"inline-block", fontSize:11, fontWeight:600, color:"#7c3aed", background:"#f5f3ff", border:"1px solid #ddd6fe", borderRadius: 14, padding:"2px 8px", marginLeft:8 },
    // Modal de Responder
    overlay: { position:"fixed", inset:0, background:"rgba(0,0,0,0.4)", zIndex:9999, display:"flex", alignItems:"center", justifyContent:"center", padding:20 },
    modal: { background:"#fff", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 16, width:"100%", maxWidth:680, maxHeight:"85vh", display:"flex", flexDirection:"column", boxShadow:"0 8px 32px rgba(0,0,0,0.12)" },
    modalHeader: { padding:"20px 24px 16px", borderBottom:"1px solid #f3f4f6" },
    modalTitulo: { fontSize:16, fontWeight:700, color:"#111827", margin:0 },
    modalBody: { padding:"20px 24px", flex:1, overflowY:"auto", display:"flex", flexDirection:"column", gap:14 },
    modalLabel: { fontSize:11, fontWeight:600, color:"#4b5563", textTransform:"uppercase", letterSpacing:0.5, marginBottom:4, display:"block" },
    modalInput: { width:"100%", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 12, padding:"10px 12px", fontSize:13, fontFamily:"inherit", outline:"none", boxSizing:"border-box" },
    modalReadonly: { fontSize:13, color:"#111827", padding:"10px 12px", background:"#f9fafb", border:"1px solid #f3f4f6", borderRadius: 12 },
    modalTextarea: { width:"100%", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 12, padding:"12px", fontSize:13, fontFamily:"inherit", outline:"none", boxSizing:"border-box", minHeight:200, resize:"vertical", lineHeight:1.5 },
    modalFooter: { padding:"14px 24px 18px", borderTop:"1px solid #f3f4f6", display:"flex", justifyContent:"flex-end", gap:10 },
    btnEnviar: { background:"#262421", color:"#fff", border:"none", borderRadius: 12, padding:"10px 20px", fontSize:13, fontWeight:600, cursor:"pointer", fontFamily:"inherit" },
    btnCancelar: { background:"#fff", color:"#4b5563", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 12, padding:"10px 20px", fontSize:13, cursor:"pointer", fontFamily:"inherit" },
  };

  if (loading) {
    return (
      <div style={S.wrap}>
        <div style={{ ...S.vazio, paddingTop:120 }}>Carregando mensagens…</div>
      </div>
    );
  }

  return (
    <div style={S.wrap}>
      <div style={S.header}>
        <div>
          <div style={{ display:"flex", alignItems:"center" }}>
            <h1 style={S.titulo}>Mensagens</h1>
            {naoLidas > 0 && <span style={S.badge}>{naoLidas} não {naoLidas === 1 ? "lida" : "lidas"}</span>}
          </div>
          <div style={S.sub}>Caixa de entrada do time VICKE — emails recebidos em @vicke.com.br</div>
        </div>
        <button onClick={carregarLista} style={S.btnAcao}>↻ Atualizar</button>
      </div>

      <div style={S.filtros}>
        <button style={S.btnFiltro(filtro === "todas")} onClick={() => setFiltro("todas")}>
          Todas
        </button>
        <button style={S.btnFiltro(filtro === "nao-lidas")} onClick={() => setFiltro("nao-lidas")}>
          Não lidas{naoLidas > 0 && ` (${naoLidas})`}
        </button>
      </div>

      <div style={S.body}>
        <div style={estreito ? { ...S.listaCol, width: "100%", minWidth: 0, borderRight: "none", display: selecionada ? "none" : "block" } : S.listaCol}>
          {mensagens.length === 0 ? (
            <div style={S.vazio}>
              {filtro === "nao-lidas"
                ? "Nenhuma mensagem não lida."
                : "Nenhuma mensagem ainda. Os emails enviados para qualquer endereço @vicke.com.br aparecerão aqui."}
            </div>
          ) : (
            mensagens.map(m => {
              const { nome, email } = parsearRemetente(m.de);
              const ehSelecionada = selecionada?.id === m.id;
              return (
                <div
                  key={m.id}
                  style={S.item(ehSelecionada, m.lida)}
                  onClick={() => abrirMensagem(m)}
                  onMouseEnter={e => { if (!ehSelecionada) e.currentTarget.style.background = "#fafbfc"; }}
                  onMouseLeave={e => { if (!ehSelecionada) e.currentTarget.style.background = "#fff"; }}
                >
                  <div style={S.nome(m.lida)}>
                    <span style={{ display:"flex", alignItems:"center", overflow:"hidden", textOverflow:"ellipsis", whiteSpace:"nowrap" }}>
                      {!m.lida && <span style={S.pontoNaoLida}></span>}
                      {nome || email}
                    </span>
                    <span style={S.data}>{formatarData(m.recebido_em)}</span>
                  </div>
                  <div style={S.assunto(m.lida)}>{m.assunto || "(sem assunto)"}</div>
                  {m.preview && <div style={S.preview}>{m.preview}</div>}
                </div>
              );
            })
          )}
        </div>

        <div style={estreito ? { ...S.detalheCol, display: selecionada ? "block" : "none" } : S.detalheCol}>
          {estreito && selecionada && (
            <button type="button" onClick={() => setSelecionada(null)} data-vk-msg-voltar
              style={{ background: "none", border: "none", color: "#0474f4", fontSize: 13, padding: "12px 16px 0", cursor: "pointer", fontFamily: "inherit" }}>
              ← Voltar
            </button>
          )}
          {!selecionada ? (
            <div style={{ ...S.vazio, paddingTop:120 }}>
              Selecione uma mensagem para visualizar
            </div>
          ) : carregandoDet && !selecionada.body_html && !selecionada.body_text ? (
            <div style={{ ...S.vazio, paddingTop:120 }}>Carregando…</div>
          ) : (
            <>
              <div style={S.detHeader}>
                <div style={S.detAssunto}>{selecionada.assunto || "(sem assunto)"}</div>
                <div style={{ display:"flex", justifyContent:"space-between", alignItems:"flex-start" }}>
                  <div>
                    <div style={S.detLinhaForte}>{selecionada.de}</div>
                    <div style={S.detLinha}>
                      Para: {Array.isArray(selecionada.para) ? selecionada.para.join(", ") : (selecionada.para || "")}
                    </div>
                    <div style={S.detLinha}>
                      {new Date(selecionada.recebido_em).toLocaleString("pt-BR", {
                        day:"2-digit", month:"long", year:"numeric",
                        hour:"2-digit", minute:"2-digit",
                      })}
                    </div>
                  </div>
                </div>
                <div style={S.detAcoes}>
                  <button style={S.btnAcaoPrimaria} onClick={() => abrirResponder(selecionada)}>
                    ↪ Responder
                  </button>
                  {selecionada.lida ? (
                    <button style={S.btnAcao} onClick={() => marcarNaoLida(selecionada)}>
                      ↩ Marcar como não lida
                    </button>
                  ) : null}
                  <button style={S.btnAcaoDestrutiva} onClick={() => excluirMensagem(selecionada)}>
                    🗑 Excluir
                  </button>
                </div>
              </div>
              <div style={S.detBody}>
                {selecionada.body_html ? (
                  // O HTML vem de e-mail de fora: qualquer um manda. Direto na
                  // página (dangerouslySetInnerHTML), um <img onerror> rodava
                  // aqui dentro e levava o token do master do localStorage.
                  // No iframe com sandbox e SEM allow-scripts, nada do e-mail
                  // executa, e sem allow-same-origin ele nem enxerga esta
                  // página. allow-popups: link do e-mail abre em outra aba
                  // (o <base target="_blank"> do srcDoc), não dentro do quadro.
                  <iframe
                    title="Conteúdo da mensagem"
                    sandbox="allow-popups allow-popups-to-escape-sandbox"
                    referrerPolicy="no-referrer"
                    srcDoc={'<!doctype html><html><head><meta charset="utf-8"><base target="_blank">'
                      + '<style>body{margin:0;font-family:-apple-system,Segoe UI,Roboto,sans-serif;font-size:14px;line-height:1.6;color:#111827;word-wrap:break-word}img{max-width:100%;height:auto}</style>'
                      + '</head><body>' + selecionada.body_html + '</body></html>'}
                    style={{ display:"block", width:"100%", height:"max(360px, calc(100vh - 340px))", border:"none", background:"#fff" }}
                  />
                ) : selecionada.body_text ? (
                  <pre style={{ ...S.detHtml, whiteSpace:"pre-wrap", fontFamily:"inherit", margin:0 }}>
                    {selecionada.body_text}
                  </pre>
                ) : (
                  <div style={{ color:"#4b5563", fontStyle:"italic", fontSize:13 }}>
                    Conteúdo ainda sendo processado pelo servidor… Recarregue em alguns segundos.
                  </div>
                )}
              </div>
            </>
          )}
        </div>
      </div>

      {/* Modal de Responder mensagem */}
      {respondendo && (
        <div style={S.overlay}>
          <div style={S.modal} onClick={e => e.stopPropagation()}>
            <div style={S.modalHeader}>
              <h2 style={S.modalTitulo}>Responder mensagem</h2>
            </div>
            <div style={S.modalBody}>
              <div>
                <label style={S.modalLabel}>Para</label>
                <div style={S.modalReadonly}>{respondendo.de}</div>
              </div>
              <div>
                <label style={S.modalLabel}>De</label>
                <div style={S.modalReadonly}>Time VICKE &lt;time@vicke.com.br&gt;</div>
              </div>
              <div>
                <label style={S.modalLabel}>Assunto</label>
                <input
                  style={S.modalInput}
                  value={respAssunto}
                  onChange={e => setRespAssunto(e.target.value)}
                  disabled={enviandoResp}
                />
              </div>
              <div>
                <label style={S.modalLabel}>Mensagem</label>
                <textarea
                  style={S.modalTextarea}
                  value={respCorpo}
                  onChange={e => setRespCorpo(e.target.value)}
                  placeholder="Escreva sua resposta…"
                  disabled={enviandoResp}
                  autoFocus
                />
              </div>
            </div>
            <div style={S.modalFooter}>
              <button style={S.btnCancelar} onClick={fecharResponder} disabled={enviandoResp}>
                Cancelar
              </button>
              <button style={{ ...S.btnEnviar, opacity: enviandoResp ? 0.6 : 1 }} onClick={enviarResposta} disabled={enviandoResp}>
                {enviandoResp ? "Enviando…" : "Enviar resposta"}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}


// ════════════════════════════════════════════════════════════
// onboarding.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// ONBOARDING — Sprint 3
// ═══════════════════════════════════════════════════════════════
// Tela bloqueante que aparece pra empresas novas (precisa_fazer_onboarding=true).
// Coleta perfil do escritório em 7 perguntas + estado, calcula pct_matriz,
// permite calibragem (digitar valor desejado pra casa exemplo) e salva.
//
// Estilo: vertical scrolling igual Claude.ai. Pergunta clicada → próxima
// aparece logo abaixo com fade-in suave. Pode voltar e mudar respostas
// anteriores — recálculos acontecem automaticamente.
//
// Visual: paleta neutra preto/branco, alinhada ao resto do app.
//
// Backend usa nomenclatura oficial NBR 12721 ("Normal" pro padrão médio),
// mas no UI mostramos "Médio" (mais intuitivo pro usuário). Mapeamento
// fica isolado nas constantes ESTADOS / labels da matriz.

// ── Constantes ─────────────────────────────────────────────────
// Estados que têm CUB coletado (alinhado com ESTADOS_VALIDOS_ONBOARDING do backend)
const ESTADOS_DISPONIVEIS = [
  { sigla: "SP", nome: "São Paulo (SP)" },
  { sigla: "RJ", nome: "Rio de Janeiro (RJ)" },
  { sigla: "MG", nome: "Minas Gerais (MG)" },
  { sigla: "SC", nome: "Santa Catarina (SC)" },
];

// Mapeia chave do backend → label de exibição.
// Padrão: backend manda "medio", mostramos "Maior parte médio padrão".
// Fonte da verdade são os labels que vêm de /api/onboarding/matriz, mas
// mantemos esses fallbacks caso a API esteja indisponível por algum motivo.
const ORDEM_PORTE = ["1-3", "4-10", "11-30", "30+"];
const ORDEM_EXPERIENCIA = ["0-2", "3-5", "6-10", "11-20", "20+"];
// "Referência no mercado" foi renomeada pra "Momento atual da carreira" — escala
// de 7 níveis cobrindo do iniciante ao referência internacional. O nome do
// campo no DB continua sendo `referencia` pra evitar migration de schema.
const ORDEM_REFERENCIA = [
  "iniciando",
  "alguns_projetos",
  "projetos_crescendo",
  "referencia_cidade",
  "referencia_alem",
  "nacional",
  "internacional",
];
const ORDEM_PADRAO = ["baixo", "medio", "alto"];

// ════════════════════════════════════════════════════════════════
// CASA EXEMPLO — usada pra calibragem e simulação
// ════════════════════════════════════════════════════════════════
// Composição "típica" residencial padrão Médio. DEVE BATER com a CASA_EXEMPLO
// definida no backend (server.js). Se mudar uma, mudar a outra — senão o
// pct_calibrado reverso vai sair errado quando o usuário calibrar.
//
// Espelha a estrutura do app real: índices de cômodos vêm de COMODOS de
// shared.jsx, áreas são as do tamanho "Médio".
const CASA_EXEMPLO = {
  comodos: [
    { nome: "Suíte Master",   qtd: 1, indice: 0.05, area: 32.50 }, // 5 × 6.5
    { nome: "Suíte",          qtd: 2, indice: 0.05, area: 25.30 }, // 4.6 × 5.5
    { nome: "Living",         qtd: 1, indice: 0.05, area: 32.00 }, // 8 × 4
    { nome: "Sala de jantar", qtd: 1, indice: 0.05, area: 12.00 }, // 4 × 3
    { nome: "Cozinha",        qtd: 1, indice: 0.08, area: 12.00 }, // 4 × 3
    { nome: "Lavabo",         qtd: 1, indice: 0.05, area:  2.80 }, // 2 × 1.4
    { nome: "Lavanderia",     qtd: 1, indice: 0.05, area:  6.00 }, // 3 × 2
    { nome: "Garagem",        qtd: 2, indice: 0.03, area: 15.60 }, // 5.2 × 3
  ],
  acrescimoCirk: 0.25,
  faixasDesconto: [
    { ate: 200,      desconto: 0.00 },
    { ate: 300,      desconto: 0.30 },
    { ate: 400,      desconto: 0.35 },
    { ate: 500,      desconto: 0.40 },
    { ate: 600,      desconto: 0.45 },
    { ate: Infinity, desconto: 0.50 },
  ],
};

// Calcula honorário da casa exemplo dado o precoBase (R$/m²) e o padrão.
// Reproduz a fórmula do orcamento-teste.jsx: indiceComodos somado, fator
// multiplicador, faixas de desconto progressivas. INDICE_PADRAO: baixo=-0.1,
// medio=0, alto=+0.1 (mesmos valores do shared.jsx).
function calcularCasaExemplo(precoBase, padrao = "medio") {
  const INDICE_PADRAO = { baixo: -0.1, medio: 0, alto: 0.1 };
  const indicePadrao = INDICE_PADRAO[padrao] ?? 0;

  let indiceComodos = 0;
  let areaBruta = 0;
  for (const c of CASA_EXEMPLO.comodos) {
    indiceComodos += c.indice * c.qtd;
    areaBruta     += c.area   * c.qtd;
  }
  indiceComodos = Math.round(indiceComodos * 1000) / 1000;
  const areaTotal = Math.round(areaBruta * (1 + CASA_EXEMPLO.acrescimoCirk) * 100) / 100;
  const fatorMult = Math.round((1 + indiceComodos + indicePadrao) * 1000) / 1000;
  const precoM2Ef = precoBase * fatorMult;

  const faixas = [];
  let acum = 0, rest = areaTotal, total = 0;
  for (const f of CASA_EXEMPLO.faixasDesconto) {
    const chunk = Math.min(rest, f.ate - acum);
    if (chunk <= 0) break;
    const valorChunk = chunk * precoM2Ef * (1 - f.desconto);
    total += valorChunk;
    faixas.push({
      m2: Math.round(chunk * 100) / 100,
      desconto: f.desconto,
      precoM2Efetivo: Math.round(precoM2Ef * (1 - f.desconto) * 100) / 100,
      subtotal: Math.round(valorChunk * 100) / 100,
    });
    rest -= chunk; acum += chunk;
    if (rest <= 0) break;
  }

  return {
    areaBruta:     Math.round(areaBruta * 100) / 100,
    areaTotal,
    indiceComodos,
    indicePadrao,
    fatorMult,
    padrao,
    precoBase:     Math.round(precoBase * 100) / 100,
    precoM2:       Math.round(precoM2Ef * 100) / 100,
    faixas,
    honorario:     Math.round(total * 100) / 100,
  };
}

// Limites pra disparar aviso de "valor absurdo" na calibragem.
const RATIO_MUITO_BAIXO = 0.5;  // valor < 50% do calculado
const RATIO_MUITO_ALTO  = 2.0;  // valor > 200% do calculado

// ── Componente principal ───────────────────────────────────────
function TelaOnboarding({ usuario, escritorio, onConcluido, onLogout }) {
  // Detecta se o escritório já tem cadastro preenchido em sessão anterior.
  // Critério: nome + cidade (campos obrigatórios do BlocoCadastroEscritorio).
  // Usado pra pular a tela de cadastro do escritório no fluxo de
  // recalibragem (Configurações → "Resetar e refazer calibragem"), evitando
  // re-pedir dados que já existem e que sobrescreveriam o cadastro salvo.
  const escritorioJaPreenchido = !!(escritorio?.nome && escritorio?.cidade);
  // Estado das respostas. null = ainda não respondeu.
  const [profissao, setProfissao]       = useState(null);  // "arquiteto" | "engenheiro"
  const [porte, setPorte]               = useState(null);
  const [experiencia, setExperiencia]   = useState(null);
  const [referencia, setReferencia]     = useState(null);
  const [padrao, setPadrao]             = useState(null);
  const [capital, setCapital]           = useState(null);  // boolean
  const [estado, setEstado]             = useState(null);

  // Matriz vinda do backend (com labels e ratings).
  const [matriz, setMatriz]             = useState(null);
  const [matrizErro, setMatrizErro]     = useState(null);

  // CUB do estado escolhido — buscado quando seleciona estado, usado pro
  // exemplo de cálculo na tela de resumo/calibragem.
  const [cubEstado, setCubEstado]       = useState(null);
  const [cubErro, setCubErro]           = useState(null);

  // Calibragem: null = ainda não decidiu, true = aceita o calculado,
  // false = quer ajustar (mostra campo de input).
  const [aceitouCalculado, setAceitouCalculado] = useState(null);
  const [valorCalibragem, setValorCalibragem]   = useState(""); // string em digitação no input
  // Valor calibrado CONFIRMADO (em number) — só seta quando o usuário aperta
  // Enter ou clica fora do input. Esse é o valor que substitui o pct_matriz
  // nos cálculos do gráfico/tabela. Enquanto o usuário digita, esse valor não
  // muda — evita flicker e dá controle pro usuário.
  const [valorCalibradoConfirmado, setValorCalibradoConfirmado] = useState(null);
  const [confirmandoAbsurdo, setConfirmandoAbsurdo] = useState(false);
  // Reconfirmação após o usuário ajustar o preço (caminho "Quero ajustar").
  // null = ainda não respondeu, true = "Sim, prosseguir" → abre cadastro inline,
  // false = "Quero ajustar mais" → continua editando o input.
  // Reseta automaticamente quando valorCalibradoConfirmado muda (preço novo
  // precisa ser reconfirmado).
  const [precoRecalibradoOk, setPrecoRecalibradoOk] = useState(null);

  useEffect(() => {
    setPrecoRecalibradoOk(null);
  }, [valorCalibradoConfirmado]);

  // Estado de salvamento.
  const [salvando, setSalvando] = useState(false);
  const [erroSalvar, setErroSalvar] = useState(null);

  // Após salvar com sucesso, mostra tela de transição com explicação do
  // que vem em seguida (cadastro do escritório). Usuário clica e libera.
  const [concluido, setConcluido] = useState(false);

  // Cadastro do escritório (inline, abre quando aceitouCalculado === true).
  // Step 2: campos básicos — nome, cidade, estado, e-mail, telefone, instagram, logo.
  // Logo é base64 (mesma estratégia da aba Escritório). logoErro é mensagem inline.
  const [escLogo, setEscLogo]             = useState(null);
  const [escLogoErro, setEscLogoErro]     = useState(null);
  const [escNome, setEscNome]             = useState("");
  const [escCidade, setEscCidade]         = useState("");
  const [escEstado, setEscEstado]         = useState("");
  const [escEmail, setEscEmail]           = useState("");
  const [escTelefone, setEscTelefone]     = useState("");
  const [escInstagram, setEscInstagram]   = useState("");
  // Responsável técnico (Step 3) — primeiro responsável vai pro
  // responsaveis[0] do escritório. Outros podem ser adicionados depois
  // pela aba Escritório.
  const [escRespNome, setEscRespNome]         = useState("");
  const [escRespRegistro, setEscRespRegistro] = useState("");
  // PIX e Banco (Step 4) — todos opcionais. Linha PIX só aparece no
  // PDF/preview se a chave estiver preenchida.
  const [escPixTipo, setEscPixTipo]           = useState("");
  const [escPixChave, setEscPixChave]         = useState("");
  const [escBanco, setEscBanco]               = useState("");

  // Pré-preenche estado (resposta da pergunta 7) e e-mail (do JWT) quando o
  // bloco de cadastro abre pela primeira vez. Usa `prev || ...` pra preservar
  // edição manual posterior — se o usuário já mexeu, não sobrescreve.
  useEffect(() => {
    if (aceitouCalculado === true) {
      setEscEstado(prev => prev || estado || "");
      setEscEmail(prev => prev || usuario?.email || "");
    }
  }, [aceitouCalculado, estado, usuario]);

  // Calibragem confirmada: usuário aceitou o calculado OU reajustou e
  // reconfirmou. Usada como pré-condição pra concluir o onboarding em ambos
  // os fluxos (primeiro acesso e recalibragem).
  const calibragemConfirmada = aceitouCalculado === true || precoRecalibradoOk === true;

  // Caminho inline do cadastro: ativo SOMENTE no primeiro acesso (quando
  // o escritório ainda não tem cadastro). No fluxo de recalibragem em
  // escritório já cadastrado, NÃO mostra o BlocoCadastroEscritorio — o
  // usuário só confirma a nova calibragem e volta direto pro app.
  const cadastroInlineAtivo = !escritorioJaPreenchido && calibragemConfirmada;

  // Quando o cadastro inline abre (qualquer um dos dois caminhos), posiciona
  // o topo do bloco no topo da viewport pra ele ver o cabeçalho + texto
  // explicativo. Roda em 2 frames pra garantir que o DOM já montou o bloco.
  useEffect(() => {
    if (cadastroInlineAtivo) {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          cadastroRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
        });
      });
    }
  }, [cadastroInlineAtivo]);

  // Ref pra rolar o conteúdo conforme novas perguntas aparecem.
  const containerRef = useRef(null);
  // Ref pro cabeçalho do bloco de cadastro do escritório, usada pra alinhar
  // o topo dele com o topo da viewport quando o usuário aceita o valor calculado.
  const cadastroRef = useRef(null);

  // Busca matriz do backend ao montar.
  useEffect(() => {
    api.onboarding.matriz()
      .then(setMatriz)
      .catch(e => setMatrizErro(e.message || "Falha ao carregar perguntas"));
  }, []);

  // Indicador sutil de "atualizando referências de mercado" mostrado quando
  // o usuário troca de estado pelo resumo lateral. Não limpa o cubEstado
  // anterior — assim a UI não pisca em branco enquanto o fetch roda.
  const [cubLoading, setCubLoading] = useState(false);

  // Busca CUB quando estado é selecionado (pra mostrar exemplo de cálculo).
  useEffect(() => {
    if (!estado) { setCubEstado(null); setCubErro(null); setCubLoading(false); return; }
    setCubErro(null);
    setCubLoading(true);
    // Carrega os 3 níveis de CUB R-1 (Baixo/Normal/Alto) do estado escolhido.
    // O padrão escolhido pelo usuário define qual será usado na simulação:
    // Baixo→Baixo, Médio→Normal, Alto→Alto. Carrega tudo de uma vez pra que
    // a UI possa alternar entre padrões sem fazer fetch novo.
    //
    // IMPORTANTE: NÃO setamos cubEstado(null) antes do fetch — assim a tela
    // não pisca em branco quando o usuário troca de estado pelo resumo lateral.
    // Mantemos o conteúdo antigo até o novo chegar, então substituímos.
    Promise.all([
      api.cub.atual(estado, "R-1", "Baixo"),
      api.cub.atual(estado, "R-1", "Normal"),
      api.cub.atual(estado, "R-1", "Alto"),
    ])
      .then(([baixo, normal, alto]) => {
        setCubEstado({ estado, baixo, normal, alto });
      })
      .catch(e => setCubErro(e.message || "Falha ao carregar referência de mercado"))
      .finally(() => setCubLoading(false));
  }, [estado]);

  // Auto-scroll suave pro fim do conteúdo quando uma pergunta nova aparece.
  // Detectamos "pergunta nova" quando qualquer resposta muda — aí esperamos
  // 1 frame pra DOM atualizar e rolamos.
  const lastAnswerCount = useRef(0);
  useEffect(() => {
    const respondidas = [profissao, porte, experiencia, referencia, padrao, capital, estado].filter(v => v !== null && v !== undefined).length;
    if (respondidas > lastAnswerCount.current) {
      lastAnswerCount.current = respondidas;
      // Esperar 1 tick pra DOM atualizar e medir altura corretamente
      requestAnimationFrame(() => {
        if (containerRef.current) {
          containerRef.current.scrollTo({ top: containerRef.current.scrollHeight, behavior: "smooth" });
        }
      });
    } else {
      lastAnswerCount.current = respondidas;
    }
  }, [profissao, porte, experiencia, referencia, padrao, capital, estado]);

  // Rating efetivo somando as respostas atuais. Retorna null se ainda
  // faltam respostas (não dá pra mostrar resultado).
  const todasRespondidas = profissao && porte && experiencia && referencia && padrao && (capital !== null) && estado;
  const pctMatriz = useMemo(() => {
    if (!matriz || !todasRespondidas) return null;
    return (matriz.profissao?.[profissao]?.rating || 0)
         + (matriz.porte?.[porte]?.rating || 0)
         + (matriz.experiencia?.[experiencia]?.rating || 0)
         + (matriz.referencia?.[referencia]?.rating || 0)
         + (matriz.padrao_projetos?.[padrao]?.rating || 0)
         + (matriz.capital?.[String(capital)]?.rating || 0);
  }, [matriz, profissao, porte, experiencia, referencia, padrao, capital, todasRespondidas]);

  // Cálculo completo da casa exemplo com o PADRÃO escolhido pelo usuário.
  // CUB usado depende do padrão: Baixo→R-1 Baixo, Médio→Normal, Alto→Alto
  // (refletindo realidade do mercado: alto padrão tem custo unitário maior).
  // Quando o padrão muda, simulação atualiza instantaneamente sem refetch
  // porque cubEstado já tem os 3 níveis carregados.
  const cubAtualPorPadrao = useMemo(() => {
    if (!cubEstado) return null;
    return { baixo: cubEstado.baixo, medio: cubEstado.normal, alto: cubEstado.alto }[padrao || "medio"];
  }, [cubEstado, padrao]);

  // pct_efetivo: percentual aplicado nos cálculos do gráfico/tabela.
  // - Se o usuário CONFIRMOU um valor calibrado (Enter/blur), faz bisseção
  //   reversa pra encontrar o pct que produz esse valor → usa ele.
  // - Senão, usa o pct_matriz (calculado das 7 respostas do questionário).
  // Esse valor é o "preço base efetivo" do escritório — vai ser salvo no banco.
  const pctEfetivo = useMemo(() => {
    if (pctMatriz === null || !cubAtualPorPadrao) return null;
    // Se não houve calibração confirmada, usa pct_matriz puro
    if (valorCalibradoConfirmado === null || valorCalibradoConfirmado <= 0) {
      return pctMatriz;
    }
    // Bisseção: encontra pct tal que calcularCasaExemplo(pct * cub).honorario ≈ valor
    // Tolerância centavos. O resíduo final (centavos) é corrigido pelo fator
    // proporcional aplicado no casaCalc, garantindo display EXATO.
    let lo = 0.001, hi = 0.20;
    for (let i = 0; i < 60; i++) {
      const mid = (lo + hi) / 2;
      const honor = calcularCasaExemplo(mid * cubAtualPorPadrao.valor_m2, padrao || "medio").honorario;
      if (honor < valorCalibradoConfirmado) lo = mid; else hi = mid;
      if (Math.abs(honor - valorCalibradoConfirmado) < 0.01) break;
    }
    return (lo + hi) / 2;
  }, [pctMatriz, cubAtualPorPadrao, padrao, valorCalibradoConfirmado]);

  const casaCalc = useMemo(() => {
    if (pctEfetivo === null || !cubAtualPorPadrao) return null;
    const precoBase = pctEfetivo * cubAtualPorPadrao.valor_m2;
    const calc = calcularCasaExemplo(precoBase, padrao || "medio");

    // GOAL SEEK PERFEITO (Opção C): se o usuário confirmou um valor exato,
    // a bisseção encontra um pct que se aproxima MUITO mas tem resíduo de
    // alguns centavos por causa dos arredondamentos internos da fórmula
    // (Math.round em precoM2, em cada subtotal de faixa, etc).
    //
    // Pra garantir que o honorário final mostre EXATAMENTE o valor digitado,
    // aplicamos um fator de correção proporcional em todos os valores
    // monetários do calc. Isso preserva a consistência do waterfall:
    // base × (1 + complexidade) × (1 ± padrão) − desconto = honorário.
    //
    // O fator é geralmente algo como 1.00003 — visualmente imperceptível,
    // mas garante que a soma do waterfall bata centavo a centavo.
    if (valorCalibradoConfirmado !== null && valorCalibradoConfirmado > 0 && calc.honorario > 0) {
      const fator = valorCalibradoConfirmado / calc.honorario;
      return {
        ...calc,
        precoBase: Math.round(calc.precoBase * fator * 100) / 100,
        precoM2:   Math.round(calc.precoM2   * fator * 100) / 100,
        faixas:    calc.faixas.map(f => ({
          ...f,
          precoM2Efetivo: Math.round(f.precoM2Efetivo * fator * 100) / 100,
          subtotal:       Math.round(f.subtotal       * fator * 100) / 100,
        })),
        honorario: valorCalibradoConfirmado,  // EXATO
      };
    }

    return calc;
  }, [pctEfetivo, cubAtualPorPadrao, padrao, valorCalibradoConfirmado]);
  const honorarioCalculado = casaCalc?.honorario ?? null;

  // Análise da calibragem: detecta se o valor digitado é absurdo (muito baixo
  // ou muito alto comparado ao calculado pela matriz). Usado pra mostrar
  // warning vermelho/amarelo. SEMPRE compara contra o honorário da MATRIZ
  // (não do calibrado), senão a comparação fica circular.
  const honorarioMatriz = useMemo(() => {
    if (pctMatriz === null || !cubAtualPorPadrao) return null;
    return calcularCasaExemplo(pctMatriz * cubAtualPorPadrao.valor_m2, padrao || "medio").honorario;
  }, [pctMatriz, cubAtualPorPadrao, padrao]);

  const analiseCalibragem = useMemo(() => {
    if (aceitouCalculado !== false || !valorCalibragem || !honorarioMatriz || !cubAtualPorPadrao) return null;
    const v = parseFloat(String(valorCalibragem).replace(/\./g, "").replace(",", "."));
    if (!v || v <= 0) return { invalido: true };

    let lo = 0.001, hi = 0.20;
    for (let i = 0; i < 50; i++) {
      const mid = (lo + hi) / 2;
      const honor = calcularCasaExemplo(mid * cubAtualPorPadrao.valor_m2, padrao || "medio").honorario;
      if (honor < v) lo = mid; else hi = mid;
      if (Math.abs(honor - v) < 1) break;
    }
    const pctCalibrado = (lo + hi) / 2;

    const ratio = v / honorarioMatriz;
    return {
      valor: v,
      ratio,
      muitoBaixo: ratio < RATIO_MUITO_BAIXO,
      muitoAlto:  ratio > RATIO_MUITO_ALTO,
      pctCalibrado,
    };
  }, [valorCalibragem, honorarioMatriz, aceitouCalculado, cubAtualPorPadrao, padrao]);

  // Loading / erro inicial.
  if (matrizErro) {
    return (
      <div style={tela}>
        <div style={card}>
          <div style={{ fontSize:15, fontWeight:600, color:"#991b1b", marginBottom:8 }}>Erro ao carregar configuração</div>
          <div style={{ fontSize:13, color:"#4b5563", marginBottom:14 }}>{matrizErro}</div>
          <button onClick={() => location.reload()} style={btnPrimario}>Tentar novamente</button>
          <button onClick={onLogout} style={btnSecundario}>Sair</button>
        </div>
      </div>
    );
  }
  if (!matriz) {
    return (
      <div style={tela}>
        <div style={{ fontSize:13, color:"#4b5563" }}>Carregando…</div>
      </div>
    );
  }

  // Cadastro do escritório: campos obrigatórios pra liberar o save quando
  // o usuário aceitou o valor calculado (Step 5a). Logo, e-mail, telefone,
  // instagram, PIX e Banco são opcionais e podem ser completados depois.
  const cadastroValido =
    escNome.trim() !== "" &&
    escCidade.trim() !== "" &&
    escRespNome.trim() !== "" &&
    escRespRegistro.trim() !== "";

  // Análise de calibragem é considerada válida quando: existe, não é inválida,
  // e o valor está dentro da faixa OU o usuário confirmou um valor absurdo.
  // Usado pra decidir quando mostrar a pergunta de reconfirmação no caminho
  // "Quero ajustar".
  const analiseCalibragemValida = aceitouCalculado === false &&
    analiseCalibragem && !analiseCalibragem.invalido && (
      (!analiseCalibragem.muitoBaixo && !analiseCalibragem.muitoAlto) || confirmandoAbsurdo
    );

  // Pode "concluir" em duas situações:
  // (a) Primeiro acesso: cadastro inline ativo + cadastro válido (precisa
  //     digitar nome, cidade, etc.);
  // (b) Recalibragem: escritório já preenchido + calibragem confirmada
  //     (não exige cadastro inline, já que ele é pulado).
  const podeConcluir = todasRespondidas && (
    (cadastroInlineAtivo && cadastroValido) ||
    (escritorioJaPreenchido && calibragemConfirmada)
  );

  async function handleConcluir() {
    if (!podeConcluir) return;
    setSalvando(true);
    setErroSalvar(null);
    try {
      const valor_calibrado = aceitouCalculado === false && analiseCalibragem && !analiseCalibragem.invalido
        ? analiseCalibragem.valor
        : null;
      const resultOnboarding = await api.onboarding.concluir({
        profissao,
        porte,
        experiencia,
        referencia,
        padrao_projetos: padrao,
        capital,
        estado,
        valor_calibrado,
      });

      // Se backend retornou novo token (com estado + pct inclusos), atualiza localStorage
      if (resultOnboarding.token) {
        localStorage.setItem("vicke-token", resultOnboarding.token);
      }

      // Cadastro inline: ambos os caminhos ("Sim, está bom" e "Quero ajustar"
      // + reconfirmação) salvam o escritório inline. Falha aqui não bloqueia
      // o fluxo: onboarding já tá marcado como concluído no backend, e o
      // usuário pode completar/corrigir pela aba Escritório depois.
      //
      // Fluxo de RECALIBRAGEM (escritório já preenchido): pula o save
      // inteiramente. O form do BlocoCadastroEscritorio nem foi mostrado
      // nesse caso — fazer o save mandaria strings vazias e sobrescreveria
      // o cadastro existente.
      if (!escritorioJaPreenchido) {
        try {
          // O registro do escritório guarda mais que o cadastro (financeiro,
          // cartões, equipe, cronograma): parte do que está gravado e põe o
          // cadastro por cima. Sem conseguir ler o gravado, não grava nada.
          const gravado = await api.escritorio.get();
          const { logo: _logoAntigo, ...restoGravado } = (gravado && typeof gravado === "object") ? gravado : {};
          await api.escritorio.save({
            ...restoGravado,
            nome:      escNome.trim(),
            email:     escEmail.trim(),
            telefone:  escTelefone.trim(),
            cidade:    escCidade.trim(),
            estado:    escEstado,
            instagram: escInstagram.trim(),
            banco:     escBanco.trim(),
            pixTipo:   escPixTipo,
            pixChave:  escPixChave.trim(),
            logo:      escLogo,
            responsaveis: [{
              id:   "r1",
              nome: escRespNome.trim(),
              cau:  escRespRegistro.trim(),
              cpf:  "",
            }],
          });
        } catch (e) {
          console.warn("[onboarding] escritorio.save falhou:", e);
        }
      }
      // Pula TelaTransicao e vai direto pro app. Flag avisa o parent que o
      // escritório já foi salvo inline — assim ele NÃO refaz o pré-preenchimento
      // de estado (que sobrescreveria os dados completos com cache stale).
      // Em recalibragem, o escritório também não deve ser pré-preenchido,
      // então a flag vai true em ambos os casos.
      onConcluido(estado, { escritorioJaSalvo: true });
    } catch (e) {
      setErroSalvar(e.message || "Falha ao salvar perfil");
    } finally {
      setSalvando(false);
    }
  }

  // Após salvar com sucesso, mostra tela de transição amigável que prepara
  // o usuário pra próxima etapa (cadastro do escritório). Não usa o mesmo
  // layout do questionário porque é momento de "respirar" e celebrar a
  // conclusão antes de seguir.
  if (concluido) {
    return (
      <TelaTransicao
        usuarioNome={usuario?.nome}
        onContinuar={() => onConcluido(estado)}
      />
    );
  }

  return (
    <div ref={containerRef} style={tela}>
      {/* Largura adapta ao modo: 560 pro questionário (perguntas centralizadas e
          legíveis), expande pra 960 quando resultado aparece. */}
      <div style={{
        width:"100%",
        maxWidth: todasRespondidas ? 960 : 560,
        padding: todasRespondidas ? "32px 24px 40px" : "40px 20px 80px",
        transition:"max-width 0.3s ease",
      }}>

        {/* ── Cabeçalho — só aparece enquanto questionário ativo ── */}
        {!todasRespondidas && (
          <div style={{ marginBottom:32 }}>
            <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1, marginBottom:8 }}>VICKE</div>
            <div style={{ fontSize:24, fontWeight:300, color:"#111827", letterSpacing:-0.5, marginBottom:6 }}>
              Bem-vindo, {(usuario?.nome || "").split(" ")[0]}!
            </div>
            <div style={{ fontSize:14, color:"#4b5563", lineHeight:1.5 }}>
              Configure seu perfil profissional para personalizar seus orçamentos. Vai levar 2 minutos.
            </div>
          </div>
        )}

        {/* ── Questionário (1-7) — escondido quando o resultado aparece ── */}
        {!todasRespondidas && (<>

        {/* ── 1. Profissão ── */}
        <PerguntaBlock pergunta="Qual é a sua profissão?">
          <Opcao
            label={matriz.profissao.arquiteto.label}
            selecionada={profissao === "arquiteto"}
            onClick={() => setProfissao("arquiteto")}
          />
          <Opcao
            label={matriz.profissao.engenheiro.label}
            selecionada={profissao === "engenheiro"}
            onClick={() => setProfissao("engenheiro")}
          />
        </PerguntaBlock>

        {/* ── 2. Porte ── */}
        {profissao && (
          <PerguntaBlock pergunta="Quantas pessoas trabalham no seu escritório?">
            {ORDEM_PORTE.map(k => (
              <Opcao key={k}
                label={matriz.porte[k].label}
                selecionada={porte === k}
                onClick={() => setPorte(k)}
              />
            ))}
          </PerguntaBlock>
        )}

        {/* ── 3. Experiência ── */}
        {porte && (
          <PerguntaBlock pergunta="Quantos anos de experiência tem o(a) profissional responsável?">
            {ORDEM_EXPERIENCIA.map(k => (
              <Opcao key={k}
                label={matriz.experiencia[k].label}
                selecionada={experiencia === k}
                onClick={() => setExperiencia(k)}
              />
            ))}
          </PerguntaBlock>
        )}

        {/* ── 4. Momento atual da carreira ── */}
        {experiencia && (
          <PerguntaBlock
            pergunta="Em que momento da sua carreira você está?"
            sub="Pense no estágio atual, não no que pretende alcançar — você poderá refazer essa calibragem quando seu momento mudar."
          >
            {ORDEM_REFERENCIA
              .filter(k => matriz.referencia?.[k])  // resilência: ignora itens que sumiram da matriz (em vez de quebrar a tela)
              .map(k => (
                <Opcao key={k}
                  label={matriz.referencia[k].label}
                  selecionada={referencia === k}
                  onClick={() => setReferencia(k)}
                />
              ))}
          </PerguntaBlock>
        )}

        {/* ── 5. Padrão de projetos ── */}
        {referencia && (
          <PerguntaBlock pergunta="Qual o padrão da maioria dos seus projetos?">
            {ORDEM_PADRAO.map(k => (
              <Opcao key={k}
                label={matriz.padrao_projetos[k].label}
                selecionada={padrao === k}
                onClick={() => setPadrao(k)}
              />
            ))}
          </PerguntaBlock>
        )}

        {/* ── 6. Capital ── */}
        {padrao && (
          <PerguntaBlock pergunta="Seu escritório está localizado em uma capital?">
            <Opcao
              label={matriz.capital.true.label}
              selecionada={capital === true}
              onClick={() => setCapital(true)}
            />
            <Opcao
              label={matriz.capital.false.label}
              selecionada={capital === false}
              onClick={() => setCapital(false)}
            />
          </PerguntaBlock>
        )}

        {/* ── 7. Estado ── */}
        {capital !== null && (
          <PerguntaBlock
            pergunta="Em qual estado fica o escritório?"
            sub="Usamos os dados do seu estado pra calcular o preço base dos projetos."
          >
            {ESTADOS_DISPONIVEIS.map(e => (
              <Opcao key={e.sigla}
                label={e.nome}
                selecionada={estado === e.sigla}
                onClick={() => setEstado(e.sigla)}
              />
            ))}
          </PerguntaBlock>
        )}

        </>)}{/* ── fim do questionário condicional ── */}

        {/* ── Resultado + calibragem ── */}
        {todasRespondidas && (
          <BlocoResultado
            pctMatriz={pctMatriz}
            cubEstado={cubEstado}
            cubErro={cubErro}
            casaCalc={casaCalc}
            honorarioCalculado={honorarioCalculado}
            aceitouCalculado={aceitouCalculado}
            setAceitouCalculado={setAceitouCalculado}
            valorCalibragem={valorCalibragem}
            setValorCalibragem={(v) => { setValorCalibragem(v); setConfirmandoAbsurdo(false); }}
            valorCalibradoConfirmado={valorCalibradoConfirmado}
            setValorCalibradoConfirmado={setValorCalibradoConfirmado}
            analiseCalibragem={analiseCalibragem}
            confirmandoAbsurdo={confirmandoAbsurdo}
            setConfirmandoAbsurdo={setConfirmandoAbsurdo}
            precoRecalibradoOk={precoRecalibradoOk}
            setPrecoRecalibradoOk={setPrecoRecalibradoOk}
            analiseCalibragemValida={analiseCalibragemValida}
            cadastroInlineAtivo={cadastroInlineAtivo}
            // Respostas atuais (pra resumo lateral) e setters (pra editar)
            respostas={{ profissao, porte, experiencia, referencia, padrao, capital, estado }}
            setters={{ setProfissao, setPorte, setExperiencia, setReferencia, setPadrao, setCapital, setEstado }}
            matriz={matriz}
            containerRef={containerRef}
            cubLoading={cubLoading}
          />
        )}

        {/* ── Cadastro do escritório (Sim direto OU Quero ajustar reconfirmado) ── */}
        {todasRespondidas && cadastroInlineAtivo && (
          <BlocoCadastroEscritorio
            outerRef={cadastroRef}
            logo={escLogo} setLogo={setEscLogo}
            logoErro={escLogoErro} setLogoErro={setEscLogoErro}
            nome={escNome} setNome={setEscNome}
            cidade={escCidade} setCidade={setEscCidade}
            estado={escEstado} setEstado={setEscEstado}
            email={escEmail} setEmail={setEscEmail}
            telefone={escTelefone} setTelefone={setEscTelefone}
            instagram={escInstagram} setInstagram={setEscInstagram}
            respNome={escRespNome} setRespNome={setEscRespNome}
            respRegistro={escRespRegistro} setRespRegistro={setEscRespRegistro}
            profissao={profissao}
            pixTipo={escPixTipo} setPixTipo={setEscPixTipo}
            pixChave={escPixChave} setPixChave={setEscPixChave}
            banco={escBanco} setBanco={setEscBanco}
          />
        )}

        {/* ── Botão concluir ──
            Primeiro acesso: aparece quando cadastro inline está aberto.
            Recalibragem: aparece logo que a calibragem é confirmada (sem
            exigir cadastro inline). */}
        {todasRespondidas && (cadastroInlineAtivo || (escritorioJaPreenchido && calibragemConfirmada)) && (
          <div style={{ marginTop:32, paddingTop:24, borderTop:"1px solid #f3f4f6" }}>
            {erroSalvar && (
              <div style={{ fontSize:12.5, color:"#991b1b", background:"#fef2f2", border:"1px solid #fecaca", borderRadius: 12, padding:"8px 12px", marginBottom:14 }}>
                {erroSalvar}
              </div>
            )}
            <button
              onClick={handleConcluir}
              disabled={!podeConcluir || salvando}
              style={{
                ...btnPrimario,
                width:"100%",
                opacity: (!podeConcluir || salvando) ? 0.5 : 1,
                cursor: (!podeConcluir || salvando) ? "not-allowed" : "pointer",
              }}>
              {salvando
                ? "Salvando..."
                : escritorioJaPreenchido
                ? "Salvar calibragem e voltar"
                : "Salvar e começar a usar o VICKE"}
            </button>
            <button
              onClick={onLogout}
              disabled={salvando}
              style={{ ...btnSecundario, width:"100%", marginTop:8 }}>
              Sair sem concluir
            </button>
          </div>
        )}

      </div>
    </div>
  );
}

// ── Sub-componentes ────────────────────────────────────────────

// Bloco de uma pergunta + suas opções. Fade-in suave ao montar.
function PerguntaBlock({ pergunta, sub, children }) {
  return (
    <div style={{
      marginTop:28,
      animation:"vk-onb-fade-in 0.35s ease-out",
    }}>
      <style>{`
        @keyframes vk-onb-fade-in {
          from { opacity: 0; transform: translateY(8px); }
          to   { opacity: 1; transform: translateY(0); }
        }
      `}</style>
      <div style={{ fontSize:15, fontWeight:500, color:"#111827", marginBottom: sub ? 4 : 12, lineHeight:1.4 }}>
        {pergunta}
      </div>
      {sub && (
        <div style={{ fontSize:12.5, color:"#4b5563", marginBottom:12, lineHeight:1.5 }}>
          {sub}
        </div>
      )}
      <div style={{ display:"flex", flexDirection:"column", gap:8 }}>
        {children}
      </div>
    </div>
  );
}

// Botão de opção. Quando selecionada, fica destacada em cobre (borda + glow),
// seguindo a paleta oficial do Vicke (grafite + cobre).
function Opcao({ label, selecionada, onClick }) {
  return (
    <button
      onClick={onClick}
      style={{
        display:"flex", alignItems:"center", gap:10,
        padding:"12px 14px",
        background: "#fff",
        border: selecionada ? "1.5px solid #0474f4" : "1.5px solid rgba(38,36,33,0.16)",
        borderRadius: 12,
        boxShadow: selecionada ? "0 0 0 3px rgba(4,116,244,0.14)" : "none",
        cursor:"pointer",
        textAlign:"left",
        fontFamily:"inherit",
        fontSize:13.5,
        color:"#111827",
        fontWeight: selecionada ? 600 : 400,
        transition:"all 0.12s",
      }}
      onMouseEnter={e => { if (!selecionada) e.currentTarget.style.borderColor="#9ca3af"; }}
      onMouseLeave={e => { if (!selecionada) e.currentTarget.style.borderColor="rgba(38,36,33,0.16)"; }}>
      <span style={{
        flexShrink:0,
        width:18, height:18, borderRadius:"50%",
        border: selecionada ? "5px solid #0474f4" : "1.5px solid rgba(38,36,33,0.16)",
        background:"#fff",
        transition:"all 0.12s",
      }} />
      <span style={{ flex:1 }}>{label}</span>
    </button>
  );
}

// ───────────────────────────────────────────────────────────────
// InputMoedaBR — input de moeda com formato brasileiro automático.
//
// Comportamento:
// - Texto-instrução "Insira o valor R$" some quando usuário clica/digita.
// - Enquanto digita, formata automaticamente: 52000 → 52.000,00
// - Confirma valor (chama onConfirmar com number) quando usuário aperta
//   Enter ou clica fora (blur). Antes disso, gráfico/tabela NÃO mudam.
//
// A formatação extrai apenas os dígitos do que foi digitado e divide por 100
// pra interpretar os 2 últimos dígitos como centavos. Ex: digitar "52000"
// vira 520,00 — incorreto. Pra corrigir, somente dígitos pra esquerda da
// vírgula são interpretados como reais (ex: "52000" → 52.000,00). Implementa
// abordagem "campo formatado" — usuário digita só números inteiros (R$) e
// se quiser centavos, digita ",XX" no fim.
// ───────────────────────────────────────────────────────────────
function InputMoedaBR({ valor, setValor, onConfirmar }) {
  const [focado, setFocado] = useState(false);

  // Formata o valor digitado pra padrão BR.
  // Estratégia: separa parte inteira (antes da vírgula/ponto) e decimal, formata
  // a parte inteira com pontos a cada 3 dígitos. Aceita dígitos, ponto e vírgula.
  // Exemplos:
  //   "52000"      → "52.000"
  //   "52000,5"    → "52.000,5"
  //   "52000,50"   → "52.000,50"
  //   "1234567,89" → "1.234.567,89"
  function formatarBR(input) {
    const limpo = String(input).replace(/[^\d,]/g, "");
    const [inteira = "", decimal] = limpo.split(",");
    const inteiraFmt = inteira.replace(/\B(?=(\d{3})+(?!\d))/g, ".");
    return decimal !== undefined ? `${inteiraFmt},${decimal}` : inteiraFmt;
  }

  // Converte string formatada BR pra number (R$ 52.000,50 → 52000.5)
  function parseBR(str) {
    if (!str) return 0;
    const limpo = String(str).replace(/\./g, "").replace(",", ".");
    const n = parseFloat(limpo);
    return isNaN(n) ? 0 : n;
  }

  function handleChange(e) {
    setValor(formatarBR(e.target.value));
  }

  function confirmar() {
    onConfirmar(parseBR(valor));
  }

  function handleKeyDown(e) {
    if (e.key === "Enter") {
      e.preventDefault();
      e.target.blur();   // dispara o blur que chama confirmar via onBlur
    }
  }

  // Mostra texto-instrução só quando vazio E não focado.
  // Quando vazio + focado, mostra só o cursor (input em branco).
  const mostrarInstrucao = !valor && !focado;

  return (
    <div style={{ position:"relative", maxWidth:360 }}>
      <span style={{
        position:"absolute", left:14, top:"50%",
        transform:"translateY(-50%)",
        fontSize:13, color:"#4b5563",
        pointerEvents:"none",
        fontVariantNumeric:"tabular-nums",
      }}>R$</span>
      <input
        type="text"
        inputMode="decimal"
        value={valor}
        onChange={handleChange}
        onFocus={() => setFocado(true)}
        onBlur={() => { setFocado(false); confirmar(); }}
        onKeyDown={handleKeyDown}
        placeholder={mostrarInstrucao ? "Insira o valor" : ""}
        autoFocus
        style={{
          width:"100%", boxSizing:"border-box",
          border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 12,
          padding:"11px 14px 11px 38px",
          fontSize:14, fontFamily:"inherit", outline:"none",
          fontVariantNumeric:"tabular-nums",
        }}
      />
    </div>
  );
}

// ════════════════════════════════════════════════════════════════
// Bloco final: 2 etapas.
//   Etapa 1: análise digitando + botão "Próximo"
//   Etapa 2: tabela compacta + gráfico waterfall + pergunta calibragem
// ════════════════════════════════════════════════════════════════
function BlocoResultado({
  pctMatriz, cubEstado, cubErro, casaCalc, honorarioCalculado,
  aceitouCalculado, setAceitouCalculado,
  valorCalibragem, setValorCalibragem,
  valorCalibradoConfirmado, setValorCalibradoConfirmado,
  analiseCalibragem,
  confirmandoAbsurdo, setConfirmandoAbsurdo,
  precoRecalibradoOk, setPrecoRecalibradoOk,
  analiseCalibragemValida, cadastroInlineAtivo,
  respostas, setters, matriz, containerRef, cubLoading,
}) {
  // Etapa atual: 1 = só texto, 2 = simulação completa
  const [etapa, setEtapa] = useState(1);
  // Nota: NÃO resetamos etapa quando casaCalc muda. Edições inline pelo
  // resumo lateral devem só atualizar os valores reativamente — gráfico,
  // tabela e números recalculam sozinhos pelo useMemo do componente pai.

  // Scroll pro TOPO quando entra na etapa 2 — o título "Resultado da sua
  // calibragem" deve ficar visível na chegada da tela completa. Roda em 2
  // frames pra esperar o layout da etapa 2 montar antes de scrollar.
  useEffect(() => {
    if (etapa === 2 && containerRef?.current) {
      requestAnimationFrame(() => {
        requestAnimationFrame(() => {
          containerRef.current?.scrollTo({ top: 0, behavior: "smooth" });
        });
      });
    }
  }, [etapa, containerRef]);

  // Scroll pro FIM apenas quando o usuário escolhe "Quero ajustar" (revela o
  // input). Quando o cadastro inline está ativo, o TelaOnboarding controla o
  // scroll pra alinhar o topo do cadastro com a viewport — então pulamos
  // aqui pra evitar conflito. Não dispara na entrada da etapa 2 (essa já tem
  // o useEffect acima que leva pro topo).
  useEffect(() => {
    if (!containerRef?.current) return;
    if (cadastroInlineAtivo) return;
    if (aceitouCalculado === null) return;
    requestAnimationFrame(() => {
      requestAnimationFrame(() => {
        if (containerRef.current) {
          containerRef.current.scrollTo({
            top: containerRef.current.scrollHeight,
            behavior: "smooth",
          });
        }
      });
    });
  }, [aceitouCalculado, cadastroInlineAtivo, containerRef]);

  if (cubErro) {
    return (
      <div style={{ marginTop:32, padding:"16px 18px", background:"#fef2f2", border:"1px solid #fecaca", borderRadius: 12 }}>
        <div style={{ fontSize:13, color:"#991b1b", fontWeight:600, marginBottom:4 }}>Referência indisponível</div>
        <div style={{ fontSize:12.5, color:"#7f1d1d" }}>{cubErro}</div>
      </div>
    );
  }
  if (!cubEstado || honorarioCalculado === null || !casaCalc) {
    return (
      <div style={{ marginTop:32, fontSize:13, color:"#4b5563" }}>Calculando…</div>
    );
  }

  return (
    <div style={{ animation:"vk-onb-fade-in 0.4s ease-out" }}>
      {/* Header da apresentação — kicker e título lado a lado pra economizar
          altura. Em etapa 2, ganha marginLeft 232px (sidebar 220 + gap 12)
          pra alinhar com o início do fluxograma à direita. Em mobile o grid
          colapsa e o marginLeft é zerado via CSS abaixo. */}
      <div style={{
        display:"flex", flexWrap:"wrap", alignItems:"baseline", gap:14,
        marginBottom: etapa === 1 ? 24 : 28,
        marginLeft: etapa === 2 ? 232 : 0,
        transition: "margin-left 0.3s ease-out",
      }} className="vk-onb-header">
        <div style={{ fontSize:10.5, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1.2, flexShrink:0 }}>
          VICKE · Análise Inteligente
        </div>
        <div style={{ fontSize: etapa === 1 ? 22 : 16, fontWeight:300, color:"#111827", letterSpacing:-0.4, lineHeight:1.2, display:"flex", alignItems:"center", gap:10 }}>
          Resultado da sua calibragem
          {/* Indicador sutil quando troca de estado e CUB recarrega — evita
              flash em branco. Spinner pequeno + texto delicado. */}
          {cubLoading && etapa === 2 && (
            <span style={{ display:"inline-flex", alignItems:"center", gap:6, fontSize:11, color:"#4b5563", fontStyle:"italic", fontWeight:400 }}>
              <span style={{
                display:"inline-block",
                width:10, height:10,
                border:"1.5px solid rgba(38,36,33,0.14)",
                borderTopColor:"#6b7280",
                borderRadius:"50%",
                animation:"vk-spin 0.8s linear infinite",
              }} />
              atualizando referências…
            </span>
          )}
        </div>
      </div>

      {/* Etapa 1: layout limpo, sem resumo lateral. Texto centralizado pra
          foco total na apresentação inicial. */}
      {etapa === 1 ? (
        <EtapaTexto casaCalc={casaCalc} onProximo={() => setEtapa(2)} />
      ) : (
        <>
          {/* Linha 1: resumo lateral + tabela */}
          <div style={{
            display:"grid",
            gridTemplateColumns:"minmax(0, 220px) minmax(0, 1fr)",
            gap:12,
            marginBottom:6,
          }} className="vk-onb-grid">
            <ResumoLateral respostas={respostas} setters={setters} matriz={matriz} />
            <FluxogramaCasa casaCalc={casaCalc} />
          </div>

          {/* Linha 2: gráfico waterfall */}
          <Waterfall casaCalc={casaCalc} honorarioCalculado={honorarioCalculado} />

          {/* Pergunta de calibragem — IDÊNTICA ao estilo do questionário */}
          <div style={{ marginTop:4, animation:"vk-onb-fade-in 0.3s ease-out" }}>
            <PerguntaBlock pergunta="Esse valor está alinhado com o que você cobraria?">
              <Opcao
                label="Sim, esse valor está bom"
                selecionada={aceitouCalculado === true}
                onClick={() => {
                  setAceitouCalculado(true);
                  setValorCalibragem("");
                  setValorCalibradoConfirmado(null);  // restaura cálculo da matriz
                  setConfirmandoAbsurdo(false);
                }}
              />
              <Opcao
                label="Quero ajustar — eu cobraria valor diferente"
                selecionada={aceitouCalculado === false}
                onClick={() => setAceitouCalculado(false)}
              />
            </PerguntaBlock>

            {aceitouCalculado === false && (
              <div style={{ marginTop:14, animation:"vk-onb-fade-in 0.3s ease-out" }}>
                <div style={{ fontSize:13, color:"#111827", marginBottom:4 }}>
                  Quanto você cobraria pela casa de {casaCalc.areaTotal.toLocaleString("pt-BR")}m² descrita acima?
                </div>
                <div style={{ fontSize:11.5, color:"#4b5563", marginBottom:10, lineHeight:1.4 }}>
                  Insira novo valor e aperte <strong style={{ color:"#4b5563", fontWeight:600 }}>ENTER</strong>
                </div>
                <InputMoedaBR
                  valor={valorCalibragem}
                  setValor={setValorCalibragem}
                  onConfirmar={(numero) => {
                    if (numero && numero > 0) setValorCalibradoConfirmado(numero);
                    else setValorCalibradoConfirmado(null);
                  }}
                />

                {analiseCalibragem && !analiseCalibragem.invalido && (analiseCalibragem.muitoBaixo || analiseCalibragem.muitoAlto) && (
                  <div style={{
                    marginTop:14, padding:"12px 14px",
                    background: analiseCalibragem.muitoAlto ? "#fffbeb" : "#fef2f2",
                    border: analiseCalibragem.muitoAlto ? "1px solid #fde68a" : "1px solid #fecaca",
                    borderRadius: 12, maxWidth:560,
                  }}>
                    <div style={{ fontSize:12.5, fontWeight:600, color: analiseCalibragem.muitoAlto ? "#92400e" : "#991b1b", marginBottom:6 }}>
                      {analiseCalibragem.muitoAlto ? "Valor parece muito alto" : "Valor parece muito baixo"}
                    </div>
                    <div style={{ fontSize:12, color:"#4b5563", lineHeight:1.5, marginBottom:10 }}>
                      {moeda(analiseCalibragem.valor)} é {analiseCalibragem.ratio.toFixed(1)}× {analiseCalibragem.muitoAlto ? "maior" : "menor"} que o sugerido pela análise ({moeda(honorarioCalculado)}).
                    </div>
                    <label style={{ display:"flex", alignItems:"center", gap:8, fontSize:12.5, color:"#111827", cursor:"pointer" }}>
                      <input
                        type="checkbox"
                        checked={confirmandoAbsurdo}
                        onChange={e => setConfirmandoAbsurdo(e.target.checked)}
                        style={{ cursor:"pointer" }}
                      />
                      Confirmo que quero usar esse valor mesmo assim
                    </label>
                  </div>
                )}

                {analiseCalibragem && !analiseCalibragem.invalido && !analiseCalibragem.muitoBaixo && !analiseCalibragem.muitoAlto && (
                  <div style={{ marginTop:12, fontSize:12, color:"#4b5563", lineHeight:1.5 }}>
                    {moeda(analiseCalibragem.valor)} será o seu novo preço de referência.
                  </div>
                )}

                {/* Reconfirmação — só aparece quando análise está válida (faixa
                    normal, OU absurdo + checkbox confirmando) E o usuário ainda
                    não prosseguiu. Botão "Prosseguir ↓" abre o cadastro inline.
                    Pra ajustar mais, basta editar o input acima e Enter — o
                    estado reseta automaticamente via useEffect. */}
                {analiseCalibragemValida && precoRecalibradoOk !== true && (
                  <div style={{ marginTop: 18, animation: "vk-onb-fade-in 0.3s ease-out" }}>
                    <button
                      onClick={() => setPrecoRecalibradoOk(true)}
                      style={{
                        background: "#262421", color: "#fff",
                        border: "none", borderRadius: 12,
                        padding: "11px 20px",
                        fontSize: 13, fontWeight: 600,
                        cursor: "pointer", fontFamily: "inherit",
                        display: "inline-flex", alignItems: "center", gap: 8,
                        transition: "background 0.15s",
                      }}
                      onMouseEnter={e => e.currentTarget.style.background = "#000"}
                      onMouseLeave={e => e.currentTarget.style.background = "#262421"}>
                      Prosseguir
                      <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
                        <line x1="12" y1="5" x2="12" y2="19"/>
                        <polyline points="5 12 12 19 19 12"/>
                      </svg>
                    </button>
                    <div style={{ marginTop: 10, fontSize: 12, color: "#6b7280", lineHeight: 1.5 }}>
                      Quer ajustar mais? Edite o valor acima e aperte <strong style={{ color: "#4b5563", fontWeight: 600 }}>Enter</strong>.
                    </div>
                  </div>
                )}
              </div>
            )}
          </div>
        </>
      )}

      {/* CSS — animações + responsivo + cursor digitando */}
      <style>{`
        @media (max-width: 720px) {
          .vk-onb-grid { grid-template-columns: 1fr !important; }
          .vk-onb-header { margin-left: 0 !important; }
        }
        @keyframes vk-bar-grow {
          from { transform: scaleY(0); }
          to   { transform: scaleY(1); }
        }
        @keyframes vk-fade-up {
          from { opacity:0; transform: translateY(6px); }
          to   { opacity:1; transform: translateY(0); }
        }
        @keyframes vk-cursor-blink {
          0%, 49%   { opacity:1; }
          50%, 100% { opacity:0; }
        }
        @keyframes vk-spin {
          to { transform: rotate(360deg); }
        }
      `}</style>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────
// EtapaTexto: bloco da etapa 1 — texto digitando + botão "Próximo"
// Texto fica ao lado do resumo lateral, ocupando a coluna direita.
// ───────────────────────────────────────────────────────────────
function EtapaTexto({ casaCalc, onProximo }) {
  // Texto pedido pelo usuário — versão analítica e direta. Substitui {valor}
  // pela R$ do preço base.
  const textoAnalise = useMemo(() => {
    return `Cruzamos seu perfil de carreira, porte de escritório, padrão de projetos e localização com a base VICKE de mercado. O preço base sugerido é ${moeda(casaCalc.precoBase)} por m² — ele varia com a complexidade do projeto, sobe com padrão alto e tem desconto progressivo em obras maiores. Veja como isso se aplica numa casa típica:`;
  }, [casaCalc.precoBase]);

  const [chars, setChars] = useState(0);
  const [terminou, setTerminou] = useState(false);

  useEffect(() => {
    setChars(0);
    setTerminou(false);
  }, [textoAnalise]);

  useEffect(() => {
    if (chars >= textoAnalise.length) { setTerminou(true); return; }
    const t = setTimeout(() => setChars(c => c + 1), 22);
    return () => clearTimeout(t);
  }, [chars, textoAnalise]);

  const handleSkip = () => {
    if (!terminou) { setChars(textoAnalise.length); setTerminou(true); }
  };

  // Layout: alinhado à esquerda como o resto da página (texto justificado).
  // O "C" de "Cruzamos" começa alinhado verticalmente com o "R" de "Resultado".
  return (
    <div style={{
      padding: "8px 0 32px",
    }}>
      <div
        onClick={handleSkip}
        style={{
          fontSize:16, color:"#111827", lineHeight:1.7,
          maxWidth: 760,
          textAlign:"justify",
          textAlignLast:"left",
          cursor: terminou ? "default" : "pointer",
          marginBottom: 24,
        }}>
        {textoAnalise.slice(0, chars)}
        {!terminou && (
          <span style={{
            display:"inline-block",
            width:2, height:"1em",
            background:"#262421",
            verticalAlign:"text-bottom",
            marginLeft:2,
            animation:"vk-cursor-blink 1s steps(2) infinite",
          }} />
        )}
      </div>

      {/* Botão "Próximo" — só habilita quando o texto termina de digitar */}
      <div style={{
        animation: terminou ? "vk-fade-up 0.3s ease-out" : "none",
        opacity: terminou ? 1 : 0,
        transition:"opacity 0.3s",
      }}>
        <button
          onClick={onProximo}
          disabled={!terminou}
          style={{
            background:"#262421", color:"#fff",
            border:"none", borderRadius: 12,
            padding:"12px 24px",
            fontSize:13, fontWeight:600,
            cursor: terminou ? "pointer" : "default",
            fontFamily:"inherit",
            display:"inline-flex", alignItems:"center", gap:8,
            transition:"background 0.15s",
          }}
          onMouseEnter={e => terminou && (e.currentTarget.style.background = "#000")}
          onMouseLeave={e => terminou && (e.currentTarget.style.background = "#262421")}>
          Próximo
          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <line x1="5" y1="12" x2="19" y2="12"/>
            <polyline points="12 5 19 12 12 19"/>
          </svg>
        </button>
      </div>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────
// ResumoLateral — header preto/branco arredondado, linhas zebra.
// Clicar num campo abre um popover com as opções daquele campo,
// permitindo alterar SEM zerar as respostas posteriores.
// Atualização do gráfico/tabela é automática (state reativo).
// ───────────────────────────────────────────────────────────────
function ResumoLateral({ respostas, setters, matriz }) {
  // Campo atualmente sendo editado (null = nenhum). Quando setado, mostra
  // popover com opções daquele campo. Clicar numa opção atualiza o setter
  // correspondente e fecha o popover.
  const [editando, setEditando] = useState(null);

  // Fecha popover ao clicar fora
  useEffect(() => {
    if (!editando) return;
    const onDocClick = (e) => {
      // Só fecha se o click foi fora de qualquer elemento do resumo lateral
      if (!e.target.closest("[data-resumo-lateral]")) {
        setEditando(null);
      }
    };
    document.addEventListener("mousedown", onDocClick);
    return () => document.removeEventListener("mousedown", onDocClick);
  }, [editando]);

  const labelOu = (cat, key, fallback) => {
    if (key === null || key === undefined) return fallback || "—";
    const k = typeof key === "boolean" ? String(key) : key;
    return matriz?.[cat]?.[k]?.label || fallback || String(key);
  };

  // Cada linha: campo no banco + label exibida + valor formatado + ordem das
  // opções na hora de editar + setter pra aplicar a mudança.
  // Importante: ORDEM das opções deve bater com ORDEM_* do questionário pra
  // experiência consistente (do menos pro mais "alto").
  const linhas = [
    {
      campo: "profissao", label: "Profissão",
      valor: labelOu("profissao", respostas.profissao),
      opcoes: ["arquiteto", "engenheiro"],
      catMatriz: "profissao",
      setter: setters.setProfissao,
    },
    {
      campo: "porte", label: "Porte",
      valor: labelOu("porte", respostas.porte),
      opcoes: ["1-3", "4-10", "11-30", "30+"],
      catMatriz: "porte",
      setter: setters.setPorte,
    },
    {
      campo: "experiencia", label: "Experiência",
      valor: labelOu("experiencia", respostas.experiencia),
      opcoes: ["0-2", "3-5", "6-10", "11-20", "20+"],
      catMatriz: "experiencia",
      setter: setters.setExperiencia,
    },
    {
      campo: "referencia", label: "Momento",
      valor: labelOu("referencia", respostas.referencia),
      opcoes: ["iniciando", "alguns_projetos", "projetos_crescendo", "referencia_cidade", "referencia_alem", "nacional", "internacional"],
      catMatriz: "referencia",
      setter: setters.setReferencia,
    },
    {
      campo: "padrao", label: "Padrão",
      valor: labelOu("padrao_projetos", respostas.padrao),
      opcoes: ["baixo", "medio", "alto"],
      catMatriz: "padrao_projetos",
      setter: setters.setPadrao,
    },
    {
      campo: "capital", label: "Localização",
      valor: labelOu("capital", respostas.capital),
      // capital é boolean — armazenamos a chave como "true"/"false"
      opcoes: ["true", "false"],
      catMatriz: "capital",
      setter: (v) => setters.setCapital(v === "true"),
      valorAtual: String(respostas.capital),
    },
    {
      campo: "estado", label: "Estado",
      valor: respostas.estado || "—",
      // Estado: lista hardcoded (não tem matriz — labels são as siglas)
      opcoes: ["SP", "RJ", "MG", "SC"],
      catMatriz: null,
      setter: setters.setEstado,
    },
  ];

  return (
    <div data-resumo-lateral style={{
      alignSelf: "start",
      position: "relative",  // popover ancora nas linhas (relative dentro)
    }}>
      {/* Header em texto cinza (sem fundo preto). fontSize/lineHeight casam
          com a primeira linha da descrição no FluxogramaCasa ("Em uma
          simulação...") pra ficarem alinhados horizontalmente no topo das
          colunas do grid. */}
      <div style={{
        fontSize: 12, fontWeight: 600, color: "#6b7280",
        textTransform: "uppercase", letterSpacing: 0.8,
        lineHeight: 1.5,
        marginBottom: 10, paddingLeft: 2,
      }}>
        Suas respostas
      </div>

      {/* Pilha de botões card-style */}
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        {linhas.map(l => {
          const aberto = editando === l.campo;
          const valorAtualKey = l.valorAtual ?? respostas[l.campo];
          return (
            <div key={l.campo} style={{ position: "relative" }}>
              <button
                type="button"
                onClick={() => setEditando(aberto ? null : l.campo)}
                style={{
                  width: "100%",
                  border: aberto ? "1.5px solid #0474f4" : "1.5px solid rgba(38,36,33,0.16)",
                  borderRadius: 14,
                  padding: "10px 12px",
                  background: "#fff",
                  cursor: "pointer",
                  fontFamily: "inherit",
                  textAlign: "left",
                  display: "flex",
                  alignItems: "center",
                  justifyContent: "space-between",
                  gap: 8,
                  transition: "border-color 0.12s, background 0.12s",
                }}
                onMouseEnter={e => {
                  if (!aberto) {
                    e.currentTarget.style.borderColor = "#9ca3af";
                    e.currentTarget.style.background = "#fafbfc";
                  }
                }}
                onMouseLeave={e => {
                  if (!aberto) {
                    e.currentTarget.style.borderColor="rgba(38,36,33,0.16)";
                    e.currentTarget.style.background = "#fff";
                  }
                }}
                title="Clique pra alterar">
                <div style={{ flex: 1, minWidth: 0 }}>
                  <div style={{
                    fontSize: 9.5, fontWeight: 700, color: "#6b7280",
                    textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 4,
                  }}>
                    {l.label}
                  </div>
                  <div style={{
                    fontSize: 12.5, color: "#111827", fontWeight: 500, lineHeight: 1.25,
                    overflow: "hidden", textOverflow: "ellipsis", whiteSpace: "nowrap",
                  }}>
                    {l.valor}
                  </div>
                </div>
                <div style={{
                  fontSize: 12, color: "#6b7280", flexShrink: 0,
                  display: "inline-block", lineHeight: 1,
                  transform: aberto ? "rotate(180deg)" : "rotate(0deg)",
                  transition: "transform 0.15s ease-out",
                }}>⌄</div>
              </button>

              {/* Popover com opções desse campo. Anchorado à direita do botão,
                  zIndex alto pra ficar sobre tabela/gráfico. */}
              {aberto && (
                <div style={{
                  position: "absolute",
                  top: 0, left: "calc(100% + 8px)",
                  background: "#fff",
                  border: "1.5px solid rgba(38,36,33,0.16)",
                  borderRadius: 14,
                  boxShadow: "0 8px 24px rgba(0,0,0,0.12)",
                  padding: 6,
                  zIndex: 100,
                  minWidth: 200,
                  animation: "vk-fade-up 0.15s ease-out",
                }}>
                  <div style={{ fontSize: 9, color: "#6b7280", textTransform: "uppercase", letterSpacing: 0.5, fontWeight: 700, padding: "4px 8px 6px" }}>
                    Alterar {l.label.toLowerCase()}
                  </div>
                  {l.opcoes.map(opt => {
                    const optLabel = l.catMatriz
                      ? (matriz?.[l.catMatriz]?.[opt]?.label || opt)
                      : opt;
                    const selecionada = String(valorAtualKey) === String(opt);
                    return (
                      <div key={opt}
                        onClick={() => {
                          l.setter(opt);
                          setEditando(null);
                        }}
                        style={{
                          padding: "7px 10px",
                          fontSize: 12,
                          borderRadius: 6,
                          cursor: "pointer",
                          background: "transparent",
                          color: selecionada ? "#0474f4" : "#374151",
                          fontWeight: selecionada ? 600 : 400,
                          transition: "background 0.1s",
                        }}
                        onMouseEnter={e => !selecionada && (e.currentTarget.style.background = "#f9fafb")}
                        onMouseLeave={e => !selecionada && (e.currentTarget.style.background = "transparent")}>
                        {optLabel}
                      </div>
                    );
                  })}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────
// FluxogramaCasa — substitui a TabelaCasaExemplo. Apresenta o cálculo
// de área como um fluxograma horizontal: COMPOSIÇÃO DOS AMBIENTES (lista
// detalhada com áreas) → SETA ANIMADA com label "+25% paredes e circulação"
// → ÁREA TOTAL (card destaque com count-up). Estilo moderno (sem zebra,
// borders rounded, espaçamento generoso). Animação sequencial em ~2s no mount.
// ───────────────────────────────────────────────────────────────
function FluxogramaCasa({ casaCalc }) {
  const labelPadrao = { baixo: "baixo", medio: "médio", alto: "alto" };
  const padraoLabel = labelPadrao[casaCalc.padrao] || casaCalc.padrao || "médio";

  // Phases controladas por flags individuais — cada elemento aparece na
  // sua hora, com a transição CSS apropriada.
  const [showDesc, setShowDesc]             = useState(false);
  const [showCardC, setShowCardC]           = useState(false);
  const [linhasReveladas, setLinhasReveladas] = useState(0);
  const [showSubtotal, setShowSubtotal]     = useState(false);
  const [showLabelOp, setShowLabelOp]       = useState(false);
  const [arrowDrawing, setArrowDrawing]     = useState(false);
  const [arrowDone, setArrowDone]           = useState(false);
  const [showCardA, setShowCardA]           = useState(false);
  // Count-up: começa em areaBruta e cresce até areaTotal junto com o
  // fade-in do card "Área total". Lazy initializer evita flash inicial.
  const [areaCountValue, setAreaCountValue] = useState(() => casaCalc.areaBruta);

  const totalLines = CASA_EXEMPLO.comodos.length;

  // Sequência de animação — só roda no mount. Mudanças de respostas
  // (padrão, estado, etc) atualizam números reativamente sem re-animar.
  useEffect(() => {
    const timeouts = [];
    let raf;

    timeouts.push(setTimeout(() => setShowDesc(true), 50));
    timeouts.push(setTimeout(() => setShowCardC(true), 250));

    // Stagger das linhas dos cômodos — 30ms entre cada
    for (let i = 0; i < totalLines; i++) {
      timeouts.push(setTimeout(() => setLinhasReveladas(i + 1), 550 + i * 30));
    }

    const linesEnd = 550 + totalLines * 30;

    timeouts.push(setTimeout(() => setShowSubtotal(true), linesEnd + 100));
    timeouts.push(setTimeout(() => setShowLabelOp(true), linesEnd + 350));
    timeouts.push(setTimeout(() => setArrowDrawing(true), linesEnd + 550));
    timeouts.push(setTimeout(() => setArrowDone(true), linesEnd + 1050));
    timeouts.push(setTimeout(() => setShowCardA(true), linesEnd + 1100));

    // Count-up animado: areaBruta → areaTotal em 500ms (ease-out cubic)
    timeouts.push(setTimeout(() => {
      const start = performance.now();
      const startVal = casaCalc.areaBruta;
      const target = casaCalc.areaTotal;
      const duration = 500;
      const tick = (now) => {
        const t = Math.min(1, (now - start) / duration);
        const eased = 1 - Math.pow(1 - t, 3);
        setAreaCountValue(startVal + (target - startVal) * eased);
        if (t < 1) raf = requestAnimationFrame(tick);
      };
      raf = requestAnimationFrame(tick);
    }, linesEnd + 1100));

    return () => {
      timeouts.forEach(t => clearTimeout(t));
      if (raf) cancelAnimationFrame(raf);
    };
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  // Pluralização específica dos cômodos da CASA_EXEMPLO
  const displayName = (nome, qtd) => {
    if (qtd <= 1) return nome;
    const plurais = { "Suíte": "Suítes", "Garagem": "Vagas de garagem" };
    return `${qtd} ${plurais[nome] || nome + "s"}`;
  };

  const adicaoCirc = casaCalc.areaTotal - casaCalc.areaBruta;

  // Dimensões do SVG da seta
  const arrW = 160, arrH = 40;
  const lineSX = 12, lineEX = 144, lineY = arrH / 2;
  const lineLen = lineEX - lineSX;

  return (
    <div style={{ animation: "vk-fade-up 0.4s ease-out" }}>
      <style>{`
        @media (max-width: 640px) {
          .vk-fluxo-grid {
            grid-template-columns: 1fr !important;
            gap: 14px !important;
          }
        }
      `}</style>

      {/* Descrição introdutória */}
      <div style={{
        opacity: showDesc ? 1 : 0,
        transform: showDesc ? "translateY(0)" : "translateY(6px)",
        transition: "opacity 0.3s ease-out, transform 0.3s ease-out",
        marginBottom: 24,
      }}>
        <div style={{ fontSize: 12, color: "#6b7280", lineHeight: 1.5 }}>
          Em uma simulação com as seguintes características:
        </div>
        <div style={{ fontSize: 14, color: "#111827", fontWeight: 500, marginTop: 4 }}>
          Casa de padrão {padraoLabel} com ambientes médios
        </div>
      </div>

      {/* Fluxograma — grid 3 colunas: cômodos | seta | área total */}
      <div className="vk-fluxo-grid" style={{
        display: "grid",
        gridTemplateColumns: "1fr 160px 1fr",
        gap: 16,
        alignItems: "center",
      }}>
        {/* ─── CARD CÔMODOS ──────────────────────────────────── */}
        <div style={{
          background: "#fff",
          border: "1.5px solid rgba(38,36,33,0.16)",
          borderRadius: 14,
          padding: "22px 24px",
          opacity: showCardC ? 1 : 0,
          transform: showCardC ? "translateY(0)" : "translateY(8px)",
          transition: "opacity 0.35s ease-out, transform 0.35s ease-out",
        }}>
          <div style={{
            fontSize: 11, fontWeight: 600, color: "#6b7280",
            textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 16,
          }}>
            Composição dos ambientes
          </div>

          {CASA_EXEMPLO.comodos.map((c, i) => {
            const revealed = i < linhasReveladas;
            const total = c.area * c.qtd;
            return (
              <div key={i} style={{
                display: "flex", justifyContent: "space-between", alignItems: "baseline",
                padding: "5px 0",
                fontSize: 13, fontVariantNumeric: "tabular-nums",
                opacity: revealed ? 1 : 0,
                transform: revealed ? "translateX(0)" : "translateX(-4px)",
                transition: "opacity 0.25s ease-out, transform 0.25s ease-out",
              }}>
                <span style={{ color: "#111827" }}>{displayName(c.nome, c.qtd)}</span>
                <span style={{ color: "#111827", fontWeight: 500 }}>
                  {total.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} m²
                </span>
              </div>
            );
          })}

          {/* Subtotal área útil — divisor sutil + linha bold */}
          <div style={{
            marginTop: 12,
            paddingTop: 12,
            borderTop: "1px solid #f3f4f6",
            display: "flex", justifyContent: "space-between", alignItems: "baseline",
            fontSize: 13, fontVariantNumeric: "tabular-nums",
            opacity: showSubtotal ? 1 : 0,
            transform: showSubtotal ? "scale(1)" : "scale(0.96)",
            transition: "opacity 0.3s, transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1)",
          }}>
            <span style={{ color: "#4b5563", fontWeight: 500 }}>Subtotal área útil</span>
            <span style={{ color: "#111827", fontWeight: 600 }}>
              {casaCalc.areaBruta.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} m²
            </span>
          </div>
        </div>

        {/* ─── SETA + LABELS ─────────────────────────────────── */}
        <div style={{
          display: "flex", flexDirection: "column", alignItems: "center", gap: 6,
        }}>
          {/* Label "+25% paredes e circulação" */}
          <div style={{
            fontSize: 11, color: "#111827", textAlign: "center", lineHeight: 1.35,
            opacity: showLabelOp ? 1 : 0,
            transform: showLabelOp ? "translateY(0)" : "translateY(-4px)",
            transition: "opacity 0.3s ease-out, transform 0.3s ease-out",
          }}>
            <strong style={{ fontWeight: 600 }}>+25%</strong>
            <br />
            paredes e circulação
          </div>

          {/* SVG da seta animada */}
          <svg width={arrW} height={arrH} style={{ overflow: "visible", display: "block" }}>
            {/* Linha que se desenha */}
            <line
              x1={lineSX} y1={lineY}
              x2={lineEX} y2={lineY}
              stroke="#374151"
              strokeWidth="1.5"
              strokeLinecap="round"
              strokeDasharray={lineLen}
              strokeDashoffset={arrowDrawing ? 0 : lineLen}
              style={{ transition: "stroke-dashoffset 600ms cubic-bezier(0.4, 0, 0.2, 1)" }}
            />
            {/* Ponta brilhante seguindo a linha (some quando termina) */}
            <circle
              cx={arrowDrawing ? lineEX - 4 : lineSX}
              cy={lineY}
              r={4}
              fill="#374151"
              style={{
                transition: "cx 600ms cubic-bezier(0.4, 0, 0.2, 1), opacity 0.2s ease-out",
                filter: "drop-shadow(0 0 4px rgba(55, 65, 81, 0.5))",
                opacity: arrowDone ? 0 : (arrowDrawing ? 1 : 0),
              }}
            />
            {/* Cabeça da seta — minimalista (linha aberta →) */}
            <g style={{
              opacity: arrowDone ? 1 : 0,
              transform: arrowDone ? "scale(1)" : "scale(0.5)",
              transformOrigin: `${lineEX}px ${lineY}px`,
              transition: "opacity 0.2s ease-out, transform 0.25s cubic-bezier(0.34, 1.56, 0.64, 1)",
            }}>
              <line x1={lineEX - 6} y1={lineY - 5} x2={lineEX} y2={lineY}
                stroke="#374151" strokeWidth="1.5" strokeLinecap="round" />
              <line x1={lineEX - 6} y1={lineY + 5} x2={lineEX} y2={lineY}
                stroke="#374151" strokeWidth="1.5" strokeLinecap="round" />
            </g>
          </svg>

          {/* Annotation "+44.78 m²" embaixo */}
          <div style={{
            fontSize: 11, color: "#111827", textAlign: "center",
            fontVariantNumeric: "tabular-nums", fontWeight: 500,
            opacity: arrowDone ? 1 : 0,
            transform: arrowDone ? "translateY(0)" : "translateY(-4px)",
            transition: "opacity 0.3s ease-out, transform 0.3s ease-out",
          }}>
            +{adicaoCirc.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })} m²
          </div>
        </div>

        {/* ─── CARD ÁREA TOTAL ───────────────────────────────── */}
        <div style={{
          background: "#fff",
          border: "1.5px solid rgba(38,36,33,0.16)",
          borderRadius: 14,
          padding: "28px 24px",
          textAlign: "center",
          opacity: showCardA ? 1 : 0,
          transform: showCardA ? "scale(1)" : "scale(0.96)",
          transition: "opacity 0.4s ease-out, transform 0.4s cubic-bezier(0.34, 1.56, 0.64, 1)",
        }}>
          <div style={{
            fontSize: 11, fontWeight: 600, color: "#6b7280",
            textTransform: "uppercase", letterSpacing: 0.5, marginBottom: 8,
          }}>
            Área total
          </div>
          <div style={{
            fontSize: 30, fontWeight: 500, color: "#111827",
            letterSpacing: -0.5, fontVariantNumeric: "tabular-nums",
            lineHeight: 1.1,
          }}>
            {areaCountValue.toLocaleString("pt-BR", { minimumFractionDigits: 2, maximumFractionDigits: 2 })}
          </div>
          <div style={{ fontSize: 12, color: "#4b5563", marginTop: 4 }}>m²</div>
        </div>
      </div>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────
// Waterfall: SVG full-width, fundo transparente, header preto/branco.
// Cores #3b82f6 (azul) / #22c55e (verde) / #ef4444 (vermelho).
// Animação 700ms crescimento + 900ms entre barras.
// ───────────────────────────────────────────────────────────────
function Waterfall({ casaCalc, honorarioCalculado }) {
  const { areaTotal, indiceComodos, indicePadrao, precoBase } = casaCalc;

  const honorBaseSemFator    = precoBase * areaTotal;
  const honorComComplexidade = precoBase * (1 + indiceComodos) * areaTotal;
  const honorComPadrao       = precoBase * (1 + indiceComodos + indicePadrao) * areaTotal;
  const totalDescontoFaixas  = honorComPadrao - honorarioCalculado;

  const parcelaComplexidade = honorComComplexidade - honorBaseSemFator;
  const parcelaPadrao       = honorComPadrao - honorComComplexidade;

  const steps = [
    { tipo:"base",  label:"Preço base",      sub:`${moeda(precoBase)}/m² × ${areaTotal.toLocaleString("pt-BR")}m²`,
      delta: honorBaseSemFator, acumulado: honorBaseSemFator },
    { tipo:"add",   label:"+ Complexidade",  sub:`${(indiceComodos*100).toFixed(0)}% por ambientes`,
      delta: parcelaComplexidade, acumulado: honorComComplexidade },
    ...(Math.abs(parcelaPadrao) > 1 ? [{
      tipo: parcelaPadrao >= 0 ? "add" : "sub",
      label: parcelaPadrao >= 0 ? "+ Padrão alto" : "− Padrão baixo",
      sub:   parcelaPadrao >= 0 ? "+10% sobre subtotal" : "−10% sobre subtotal",
      delta: parcelaPadrao, acumulado: honorComPadrao,
    }] : []),
    ...(totalDescontoFaixas > 1 ? [{
      tipo:"sub",
      label:"− Desconto progressivo",
      sub:`m² acima de 200`,
      delta: -totalDescontoFaixas, acumulado: honorarioCalculado,
    }] : []),
    { tipo:"total", label:"Honorário final", sub:`casa de ${areaTotal.toLocaleString("pt-BR")}m²`,
      delta: honorarioCalculado, acumulado: honorarioCalculado },
  ];

  // Dimensões compactas. padLeft/padRight maiores que o necessário pras barras
  // pra que os textos centralizados acima/abaixo das barras das pontas (ex.
  // "R$ 90,30/m² × 223,88m²") não cortem nas bordas do SVG.
  // padTop generoso (40px): o texto do valor (12px de fonte, ~14px de altura
  // visual) fica em `topY - 10` acima da barra. Pra barra mais alta (topY ≈ padTop),
  // sobram 40 - 10 - 14 = 16px de margem entre o topo do SVG e o topo do texto.
  // Garante que nada corte mesmo com valores grandes ou alturas extremas.
  const W = 720, H = 200;
  // padBot aumentado de 56→76 pra acomodar a linha extra "R$ X,XX/m²" abaixo
  // do sub-label da última barra (Honorário final). innerH e yBase ficam iguais
  // — só mudou a margem inferior pra dar espaço pra esse novo elemento.
  const padTop = 40, padBot = 76, padLeft = 60, padRight = 60;
  const innerW = W - padLeft - padRight;
  const innerH = H - padTop - padBot;
  const barW = Math.min(54, innerW / steps.length - 24);
  const gap  = (innerW - barW * steps.length) / (steps.length - 1);

  const maxValor = Math.max(honorComPadrao, honorarioCalculado, honorBaseSemFator);
  const yScale = (v) => innerH * (v / maxValor);
  const yBase = padTop + innerH;

  // Paleta sóbria — versão clareada/dessaturada da palette anterior:
  // base/total cinza-azulado neutro, add verde sólido sóbrio, sub vermelho
  // pálido. Casa com o tom dos cards do fluxograma (cinza claro nos
  // detalhes, sem cores saturadas).
  const COR = {
    base:  "#64748b",   // slate-500 (era #3b82f6 azul saturado)
    add:   "#34d399",   // emerald-400 (era #22c55e verde saturado)
    sub:   "#f87171",   // red-400 (era #ef4444 vermelho saturado)
    total: "#64748b",
  };

  // Animação progressiva — 700ms crescimento + 900ms entre barras
  const [stepRevelado, setStepRevelado] = useState(0);
  useEffect(() => {
    setStepRevelado(0);
    let i = 0;
    const tick = () => {
      i++;
      setStepRevelado(i);
      if (i < steps.length) setTimeout(tick, 900);
    };
    setTimeout(tick, 300);
    // eslint-disable-next-line
  }, [casaCalc.honorario]);

  return (
    <div style={{
      background:"#fff",
      border:"1.5px solid rgba(38,36,33,0.16)",
      borderRadius:14,
      padding:"22px 24px",
      animation:"vk-fade-up 0.4s ease-out",
    }}>
      {/* Título — mesma tipografia dos cards do fluxograma */}
      <div style={{
        fontSize:11, fontWeight:600, color:"#4b5563",
        textTransform:"uppercase", letterSpacing:0.5,
        marginBottom:16,
      }}>
        Como chegamos no valor
      </div>

      {/* SVG dentro do card */}
      <div style={{ width:"100%" }}>
        <svg viewBox={`0 0 ${W} ${H}`} style={{ width:"100%", height:"auto", display:"block" }}>
          {/* Linha de base sutil */}
          <line x1={padLeft} y1={yBase} x2={W - padRight} y2={yBase} stroke="#e5e7eb" strokeWidth="1" />

          {steps.map((s, i) => {
            const x = padLeft + i * (barW + gap);
            const baseY = (s.tipo === "total" || s.tipo === "base") ? yBase : (yBase - yScale(s.acumulado - s.delta));
            const altura = Math.abs(yScale(s.delta));
            const topY = s.tipo === "sub" ? baseY : baseY - altura;
            const cor = COR[s.tipo] || COR.base;
            const visivel = i < stepRevelado;
            const isTotal = s.tipo === "total";
            const isSub   = s.tipo === "sub";

            // Path da barra com cantos arredondados só de UM lado (topo pra
            // barras normais; fundo pra barras "sub" que crescem pra baixo).
            // Estilo "pílula cortada" — igual ao gráfico de orçamentos do
            // dashboard. Raio adapta à largura da barra (limita a min(altura/2, 12)).
            const r = Math.min(barW * 0.18, altura * 0.5, 12);
            const barPath = isSub
              // Sub: cantos inferiores arredondados, topo reto
              ? `M ${x},${topY} L ${x + barW},${topY} L ${x + barW},${topY + altura - r} Q ${x + barW},${topY + altura} ${x + barW - r},${topY + altura} L ${x + r},${topY + altura} Q ${x},${topY + altura} ${x},${topY + altura - r} Z`
              // Normal/total: cantos superiores arredondados, fundo reto
              : `M ${x + r},${topY} L ${x + barW - r},${topY} Q ${x + barW},${topY} ${x + barW},${topY + r} L ${x + barW},${topY + altura} L ${x},${topY + altura} L ${x},${topY + r} Q ${x},${topY} ${x + r},${topY} Z`;

            return (
              <g key={i} style={{ opacity: visivel ? 1 : 0, transition: "opacity 0.35s" }}>
                {/* Barra com animação suave (700ms, easing bouncy) */}
                <path
                  d={barPath}
                  fill={cor}
                  style={{
                    transformOrigin: `${x + barW/2}px ${baseY}px`,
                    animation: visivel ? `vk-bar-grow 0.7s cubic-bezier(0.34, 1.4, 0.64, 1)` : "none",
                  }}
                />

                {/* Linha pontilhada conectando topo da barra anterior à atual.
                    A barra "total" puxa do topo do acumulado anterior até o topo dela
                    própria (que é igual ao acumulado), fechando visualmente o waterfall. */}
                {i > 0 && visivel && (
                  <line
                    x1={x - gap}
                    y1={isTotal ? yBase - yScale(s.acumulado) : (s.tipo === "sub" ? topY : baseY)}
                    x2={x}
                    y2={isTotal ? yBase - yScale(s.acumulado) : (s.tipo === "sub" ? topY : baseY)}
                    stroke="#9ca3af" strokeWidth="1" strokeDasharray="3,3"
                    style={{ animation: "vk-fade-up 0.4s ease-out 0.5s both" }}
                  />
                )}

                {/* Valor — em preto pra contraste neutro com qualquer barra.
                    Posição vertical:
                    - Sub: abaixo da barra (baseY + altura + 16)
                    - Add/base/total: 10px ACIMA do topo da barra (sempre, sem clamp).
                      Como `padTop` foi aumentado pra 36px, mesmo a barra mais
                      alta (que toca padTop) ainda deixa 10px + altura do texto
                      = ~22px de espaço acima dela, dentro do padTop. */}
                <text
                  x={x + barW/2}
                  y={s.tipo === "sub"
                    ? baseY + altura + 16
                    : topY - 10}
                  textAnchor="middle"
                  fontSize="12" fontWeight="600"
                  fill="#262421"
                  fontFamily="'Inter', system-ui, -apple-system, sans-serif"
                  style={{ animation: visivel ? `vk-fade-up 0.4s ease-out 0.5s both` : "none", opacity: visivel ? undefined : 0 }}>
                  {s.tipo === "sub" ? "−" : ""}{moeda(Math.abs(s.delta))}
                </text>

                {/* Label — posição relativa a yBase (não a H) pra ficar
                    independente do crescimento de H (que agora reserva espaço
                    pro R$/m² da última barra). */}
                <text
                  x={x + barW/2}
                  y={yBase + 20}
                  textAnchor="middle"
                  fontSize="11" fontWeight="500"
                  fill="#374151"
                  fontFamily="'Inter', system-ui, -apple-system, sans-serif"
                  style={{ animation: visivel ? `vk-fade-up 0.4s ease-out 0.55s both` : "none", opacity: visivel ? undefined : 0 }}>
                  {s.label}
                </text>
                <text
                  x={x + barW/2}
                  y={yBase + 36}
                  textAnchor="middle"
                  fontSize="10"
                  fill="#9ca3af"
                  fontFamily="'Inter', system-ui, -apple-system, sans-serif"
                  style={{ animation: visivel ? `vk-fade-up 0.4s ease-out 0.6s both` : "none", opacity: visivel ? undefined : 0 }}>
                  {s.sub}
                </text>

                {/* R$/m² apenas na última barra (Honorário final), abaixo do
                    sub-label, com seta horizontal apontando da esquerda pra
                    direita pro valor. */}
                {i === steps.length - 1 && visivel && (() => {
                  const cx = x + barW / 2;
                  const valorPorM2 = (honorarioCalculado / casaCalc.areaTotal).toLocaleString("pt-BR", {
                    minimumFractionDigits: 2, maximumFractionDigits: 2,
                  });
                  const ay = yBase + 56;             // baseline do texto/seta
                  const arrowStartX = cx - 38;
                  const arrowEndX = cx - 22;
                  const textX = cx - 18;
                  return (
                    <g style={{ animation: "vk-fade-up 0.4s ease-out 0.7s both", opacity: visivel ? undefined : 0 }}>
                      {/* Linha horizontal */}
                      <line
                        x1={arrowStartX} y1={ay - 3.5}
                        x2={arrowEndX}   y2={ay - 3.5}
                        stroke="#374151" strokeWidth="1" strokeLinecap="round"
                      />
                      {/* Cabeça → minimalista */}
                      <line
                        x1={arrowEndX - 3} y1={ay - 6}
                        x2={arrowEndX}     y2={ay - 3.5}
                        stroke="#374151" strokeWidth="1" strokeLinecap="round"
                      />
                      <line
                        x1={arrowEndX - 3} y1={ay - 1}
                        x2={arrowEndX}     y2={ay - 3.5}
                        stroke="#374151" strokeWidth="1" strokeLinecap="round"
                      />
                      {/* Valor R$ X,XX/m² */}
                      <text
                        x={textX} y={ay}
                        textAnchor="start"
                        fontSize="10" fontWeight="500"
                        fill="#262421"
                        fontFamily="'Inter', system-ui, -apple-system, sans-serif">
                        R$ {valorPorM2}/m²
                      </text>
                    </g>
                  );
                })()}

                {/* Seta indicativa: só pra steps de variação (add/sub).
                    Posição: logo ABAIXO da barra de variação (que termina em
                    `baseY` pra add ou `baseY` pra sub também), com folga pra
                    não tocar o label inferior. Centralizada na barra. */}
                {(s.tipo === "add" || s.tipo === "sub") && visivel && (() => {
                  // Ângulo de 40° em radianos pra calcular as pontas
                  const ang = 40 * Math.PI / 180;
                  // Comprimento da diagonal da seta
                  const len = 9;
                  const dx = Math.cos(ang) * len;
                  const dy = Math.sin(ang) * len;

                  // Posição vertical da seta: entre o PÉ visual da barra de
                  // variação e a linha de base do gráfico (yBase).
                  // - add: pé da barra = baseY (que está ACIMA de yBase). Seta
                  //   no meio entre baseY e yBase.
                  // - sub: pé da barra = baseY + altura (também ACIMA de yBase).
                  //   Seta no meio entre (baseY + altura) e yBase.
                  // Em ambos casos, a seta NÃO sobrepõe a barra e fica
                  // claramente separada do label inferior.
                  const peBarra = s.tipo === "sub" ? baseY + altura : baseY;
                  const setaCentroY = (peBarra + yBase) / 2;

                  // Centro horizontal da barra
                  const cx = x + barW / 2;

                  // Pontos da linha (inicia em baixo-esquerda, termina em cima-direita pra add;
                  // ao contrário pra sub)
                  const x1 = cx - dx / 2;
                  const x2 = cx + dx / 2;
                  const y1 = s.tipo === "add" ? setaCentroY + dy / 2 : setaCentroY - dy / 2;
                  const y2 = s.tipo === "add" ? setaCentroY - dy / 2 : setaCentroY + dy / 2;
                  const corSeta = s.tipo === "add" ? "#34d399" : "#f87171";
                  const texto   = s.tipo === "add" ? "preço sobe" : "preço desce";

                  // Cabeça da seta
                  const ahLen = 4;
                  const ux = (x2 - x1) / len;
                  const uy = (y2 - y1) / len;
                  const px = -uy;
                  const py = ux;
                  const ahx1 = x2 - ux * ahLen + px * ahLen * 0.6;
                  const ahy1 = y2 - uy * ahLen + py * ahLen * 0.6;
                  const ahx2 = x2 - ux * ahLen - px * ahLen * 0.6;
                  const ahy2 = y2 - uy * ahLen - py * ahLen * 0.6;

                  return (
                    <g style={{ animation: `vk-fade-up 0.4s ease-out 0.65s both` }}>
                      <line
                        x1={x1} y1={y1}
                        x2={x2} y2={y2}
                        stroke={corSeta} strokeWidth="1.3" strokeLinecap="round"
                      />
                      <polygon
                        points={`${x2},${y2} ${ahx1},${ahy1} ${ahx2},${ahy2}`}
                        fill={corSeta}
                      />
                      {/* Texto à direita da seta (não embaixo, pra não invadir o label) */}
                      <text
                        x={x2 + 4}
                        y={s.tipo === "add" ? y2 + 3 : y2 + 3}
                        fontSize="8.5"
                        fill="#262421"
                        fontStyle="italic"
                        fontWeight="400"
                        fontFamily="'Inter', system-ui, -apple-system, sans-serif">
                        {texto}
                      </text>
                    </g>
                  );
                })()}
              </g>
            );
          })}
        </svg>
      </div>
    </div>
  );
}

// ───────────────────────────────────────────────────────────────
// BlocoCadastroEscritorio — aparece inline depois que o usuário
// aceita o valor calculado ("Sim, esse valor está bom"). Coleta os
// dados do escritório que vão direto pro cabeçalho, rodapé e aceite
// das propostas/PDFs, evitando ter que editar cada proposta depois.
// Quando o usuário escolhe "Quero ajustar", esse bloco NÃO aparece —
// fluxo dele segue por TelaTransicao + aba Escritório (legado).
// ───────────────────────────────────────────────────────────────
function BlocoCadastroEscritorio({
  outerRef,
  logo, setLogo, logoErro, setLogoErro,
  nome, setNome,
  cidade, setCidade,
  estado, setEstado,
  email, setEmail,
  telefone, setTelefone,
  instagram, setInstagram,
  respNome, setRespNome,
  respRegistro, setRespRegistro,
  profissao,
  pixTipo, setPixTipo,
  pixChave, setPixChave,
  banco, setBanco,
}) {
  // Label do registro profissional — arquitetos têm CAU, engenheiros CREA.
  // Detectado pela resposta da pergunta 1. Fallback genérico se algo der errado.
  const labelRegistro =
    profissao === "arquiteto" ? "CAU" :
    profissao === "engenheiro" ? "CREA" :
    "CAU/CREA";

  // Auto-fill bidirecional do PIX: quando o tipo é E-mail ou Telefone,
  // a chave acompanha o campo correspondente do form. Mesma lógica de
  // escritorio.jsx:362-366. Se o tipo for outro (CNPJ/CPF/Aleatória), o
  // usuário digita manualmente.
  useEffect(() => {
    if (pixTipo === "E-mail" && email) setPixChave(email);
    if (pixTipo === "Telefone" && telefone) setPixChave(telefone);
  }, [pixTipo, email, telefone, setPixChave]);

  const BANCOS_COMUNS = [
    "Banco do Brasil", "Caixa Econômica Federal", "Itaú", "Bradesco", "Santander",
    "Nubank", "Inter", "Sicoob", "Sicredi", "BTG Pactual",
    "C6 Bank", "PicPay", "Mercado Pago", "Banco Original", "Banco Safra",
  ];
  // Drag & drop state — visual feedback quando arrasta sobre a área do logo.
  const [arrastando, setArrastando] = useState(false);

  // Validação + leitura do arquivo. Reusa a lógica de escritorio.jsx
  // (PNG/JPG/SVG, máx 1MB, base64). Diferença: erros aparecem inline em vez
  // de modal `dialogo.alertar`.
  async function lerArquivoLogo(arquivo) {
    setLogoErro(null);
    if (!arquivo) return;
    const tiposOk = ["image/png", "image/jpeg", "image/jpg", "image/svg+xml"];
    if (!tiposOk.includes(arquivo.type)) {
      setLogoErro("Formato não suportado. Use PNG, JPG ou SVG.");
      return;
    }
    if (arquivo.size > 1024 * 1024) {
      setLogoErro(`Arquivo grande demais (${(arquivo.size/1024).toFixed(0)}KB). Limite: 1MB.`);
      return;
    }
    try {
      const base64 = await new Promise((resolve, reject) => {
        const reader = new FileReader();
        reader.onload = () => resolve(reader.result);
        reader.onerror = () => reject(new Error("Falha ao ler arquivo"));
        reader.readAsDataURL(arquivo);
      });
      setLogo(base64);
    } catch (e) {
      setLogoErro(e.message || "Erro ao ler arquivo");
    }
  }

  function handleUploadLogo(evento) {
    const arquivo = evento.target.files?.[0];
    evento.target.value = ""; // permite re-selecionar o mesmo arquivo
    lerArquivoLogo(arquivo);
  }

  function handleDrop(e) {
    e.preventDefault();
    setArrastando(false);
    const arquivo = e.dataTransfer.files?.[0];
    lerArquivoLogo(arquivo);
  }

  // Estilo compartilhado dos inputs.
  const inputBase = {
    width: "100%", boxSizing: "border-box",
    border: "1.5px solid rgba(38,36,33,0.16)", borderRadius: 12,
    padding: "10px 12px", fontSize: 13, color: "#111827",
    outline: "none", background: "#fff", fontFamily: "inherit",
    transition: "border-color 0.12s",
  };
  const labelBase = {
    fontSize: 11.5, color: "#4b5563", fontWeight: 500,
    marginBottom: 5, display: "block",
  };
  const campoWrap = { display: "flex", flexDirection: "column", marginBottom: 16 };

  return (
    <div ref={outerRef} style={{
      marginTop: 32,
      paddingTop: 28,
      borderTop: "1px solid #f3f4f6",
      animation: "vk-onb-fade-in 0.4s ease-out",
      scrollMarginTop: 16,
    }}>
      <style>{`
        .vk-onb-cad input:focus, .vk-onb-cad select:focus { border-color: #0474f4 !important; box-shadow: 0 0 0 3px rgba(4,116,244,0.12); }
        @media (max-width: 720px) {
          .vk-onb-cad-grid { grid-template-columns: 1fr !important; }
        }
      `}</style>

      <div style={{
        fontSize: 10.5, fontWeight: 700, color: "#6b7280",
        textTransform: "uppercase", letterSpacing: 1.2, marginBottom: 8,
      }}>
        VICKE · Cadastro do Escritório
      </div>
      <div style={{
        fontSize: 22, fontWeight: 300, color: "#111827",
        letterSpacing: -0.4, lineHeight: 1.2, marginBottom: 12,
      }}>
        Quase lá — vamos completar o cadastro
      </div>
      <div style={{
        fontSize: 14, color: "#4b5563", lineHeight: 1.6, maxWidth: 700, marginBottom: 28,
      }}>
        Reserve alguns minutos para preencher os dados do seu escritório. Essas informações aparecem automaticamente no cabeçalho, no rodapé e na área de aceite de todas as propostas, orçamentos e PDFs que você gerar — preenchendo agora, você não precisa editar em cada proposta enviada ao cliente.
      </div>

      <div className="vk-onb-cad" style={{ maxWidth: 720 }}>

        {/* ── Logo do escritório ─────────────────────────────────── */}
        <div style={{ marginBottom: 8 }}>
          <div style={{
            fontSize: 11, fontWeight: 700, color: "#6b7280",
            textTransform: "uppercase", letterSpacing: 1, marginBottom: 12,
          }}>Logo do escritório <span style={{ fontWeight: 400, color: "#6b7280" }}>· opcional</span></div>
          <div style={{ display: "flex", gap: 16, alignItems: "flex-start", flexWrap: "wrap" }}>
            {/* Preview com drag & drop */}
            <label
              onDragOver={e => { e.preventDefault(); setArrastando(true); }}
              onDragLeave={() => setArrastando(false)}
              onDrop={handleDrop}
              style={{
                width: 160, height: 100,
                border: arrastando ? "1.5px solid #0474f4" : (logo ? "1.5px solid rgba(38,36,33,0.16)" : "1.5px dashed rgba(38,36,33,0.2)"),
                borderRadius: 12,
                display: "flex", alignItems: "center", justifyContent: "center",
                background: arrastando ? "#f3f4f6" : "#fafbfc",
                overflow: "hidden", flexShrink: 0,
                cursor: "pointer", transition: "all 0.12s",
              }}
              onMouseEnter={e => { if (!arrastando && !logo) e.currentTarget.style.borderColor = "#9ca3af"; }}
              onMouseLeave={e => { if (!arrastando && !logo) e.currentTarget.style.borderColor = "rgba(38,36,33,0.2)"; }}
              title={logo ? "Clique pra trocar ou arraste uma nova imagem" : "Clique ou arraste uma imagem"}>
              {logo ? (
                <img src={logo} alt="Logo" style={{ maxWidth: "100%", maxHeight: "100%", objectFit: "contain" }} />
              ) : (
                <span style={{ fontSize: 12, color: "#6b7280", textAlign: "center", padding: "0 8px" }}>
                  {arrastando ? "Solte aqui" : "Clique ou arraste"}
                </span>
              )}
              <input
                type="file"
                accept="image/png,image/jpeg,image/jpg,image/svg+xml"
                style={{ display: "none" }}
                onChange={handleUploadLogo}
              />
            </label>

            {/* Descrição + ações */}
            <div style={{ flex: 1, minWidth: 220 }}>
              <div style={{ fontSize: 12.5, color: "#4b5563", lineHeight: 1.55, marginBottom: 10 }}>
                Aparece no cabeçalho das propostas em PDF.<br/>
                PNG, JPG ou SVG · Máximo 1MB.
              </div>
              <div style={{ display: "flex", gap: 8, flexWrap: "wrap" }}>
                <label style={{
                  background: "#262421", color: "#fff", border: "none", borderRadius: 7,
                  padding: "7px 14px", fontSize: 12.5, fontWeight: 600,
                  cursor: "pointer", display: "inline-flex", alignItems: "center", fontFamily: "inherit",
                }}>
                  {logo ? "Trocar logo" : "Enviar logo"}
                  <input
                    type="file"
                    accept="image/png,image/jpeg,image/jpg,image/svg+xml"
                    style={{ display: "none" }}
                    onChange={handleUploadLogo}
                  />
                </label>
                {logo && (
                  <button
                    type="button"
                    onClick={() => { setLogo(null); setLogoErro(null); }}
                    style={{
                      background: "#fff", color: "#111827",
                      border: "1.5px solid rgba(38,36,33,0.16)", borderRadius: 7,
                      padding: "7px 14px", fontSize: 12.5, cursor: "pointer", fontFamily: "inherit",
                    }}>
                    Remover
                  </button>
                )}
              </div>
              {logoErro && (
                <div style={{ fontSize: 12, color: "#991b1b", marginTop: 8, lineHeight: 1.4 }}>
                  {logoErro}
                </div>
              )}
              {!logo && !logoErro && (
                <div style={{
                  fontSize: 11.5, color: "#6b7280", marginTop: 10,
                  lineHeight: 1.5, display: "flex", alignItems: "flex-start", gap: 6,
                }}>
                  <span style={{ flexShrink: 0, fontSize: 12 }}>ⓘ</span>
                  <span>
                    Sem o logo, o cabeçalho das propostas usa só o nome do escritório. Pode adicionar depois na aba <strong style={{ color: "#4b5563", fontWeight: 600 }}>Escritório</strong>.
                  </span>
                </div>
              )}
            </div>
          </div>
        </div>

        <hr style={{ border: "none", borderTop: "1px solid #f3f4f6", margin: "24px 0" }} />

        {/* ── Nome (full-width) ──────────────────────────────────── */}
        <div style={campoWrap}>
          <label style={labelBase}>Nome do escritório <span style={{ color: "#dc2626" }}>*</span></label>
          <input
            type="text"
            value={nome}
            onChange={e => setNome(e.target.value)}
            placeholder="Ex: Estúdio de Arquitetura João Silva"
            style={inputBase}
          />
        </div>

        {/* ── Cidade + Estado (2 cols) ───────────────────────────── */}
        <div className="vk-onb-cad-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div style={campoWrap}>
            <label style={labelBase}>Cidade <span style={{ color: "#dc2626" }}>*</span></label>
            <input
              type="text"
              value={cidade}
              onChange={e => setCidade(e.target.value)}
              placeholder="Ex: São Paulo"
              style={inputBase}
            />
          </div>
          <div style={campoWrap}>
            <label style={labelBase}>Estado</label>
            <Selecao
              value={estado}
              onChange={e => setEstado(e.target.value)}
              style={{ ...inputBase, cursor: "pointer" }}>
              <option value="">— Selecione —</option>
              {ESTADOS_DISPONIVEIS.map(e => (
                <option key={e.sigla} value={e.sigla}>{e.nome}</option>
              ))}
            </Selecao>
          </div>
        </div>

        {/* ── E-mail + Telefone (2 cols) ─────────────────────────── */}
        <div className="vk-onb-cad-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div style={campoWrap}>
            <label style={labelBase}>E-mail</label>
            <input
              type="email"
              value={email}
              onChange={e => setEmail(e.target.value)}
              placeholder="contato@escritorio.com"
              style={inputBase}
            />
          </div>
          <div style={campoWrap}>
            <label style={labelBase}>Telefone</label>
            <input
              type="tel"
              value={telefone}
              onChange={e => setTelefone(e.target.value)}
              placeholder="(11) 91234-5678"
              style={inputBase}
            />
          </div>
        </div>

        {/* ── Instagram (full-width) ─────────────────────────────── */}
        <div style={campoWrap}>
          <label style={labelBase}>Instagram</label>
          <input
            type="text"
            value={instagram}
            onChange={e => setInstagram(e.target.value)}
            placeholder="@seuescritorio"
            style={inputBase}
          />
        </div>

        <hr style={{ border: "none", borderTop: "1px solid #f3f4f6", margin: "24px 0" }} />

        {/* ── Responsável Técnico ────────────────────────────────── */}
        <div style={{
          fontSize: 11, fontWeight: 700, color: "#6b7280",
          textTransform: "uppercase", letterSpacing: 1, marginBottom: 8,
        }}>Responsável técnico</div>
        <div style={{ fontSize: 12.5, color: "#4b5563", lineHeight: 1.55, marginBottom: 16 }}>
          Aparece como assinatura técnica no aceite das propostas. Se houver mais de um responsável no escritório, você adiciona os outros depois na aba Escritório.
        </div>

        <div className="vk-onb-cad-grid" style={{ display: "grid", gridTemplateColumns: "1fr 1fr", gap: 14 }}>
          <div style={campoWrap}>
            <label style={labelBase}>Nome <span style={{ color: "#dc2626" }}>*</span></label>
            <input
              type="text"
              value={respNome}
              onChange={e => setRespNome(e.target.value)}
              placeholder="Ex: João Silva"
              style={inputBase}
            />
          </div>
          <div style={campoWrap}>
            <label style={labelBase}>{labelRegistro} <span style={{ color: "#dc2626" }}>*</span></label>
            <input
              type="text"
              value={respRegistro}
              onChange={e => setRespRegistro(e.target.value)}
              placeholder={profissao === "engenheiro" ? "Ex: 0123456789" : "Ex: A12345-6"}
              style={inputBase}
            />
          </div>
        </div>

        <hr style={{ border: "none", borderTop: "1px solid #f3f4f6", margin: "24px 0" }} />

        {/* ── PIX e Banco ────────────────────────────────────────── */}
        <div style={{
          fontSize: 11, fontWeight: 700, color: "#6b7280",
          textTransform: "uppercase", letterSpacing: 1, marginBottom: 8,
        }}>PIX e Banco <span style={{ fontWeight: 400, color: "#6b7280" }}>· opcional</span></div>
        <div style={{ fontSize: 12.5, color: "#4b5563", lineHeight: 1.55, marginBottom: 16 }}>
          Aparece embaixo da forma de pagamento nas propostas. Pode preencher depois se preferir — só aparece no PDF se você informar a chave.
        </div>

        <div className="vk-onb-cad-grid" style={{ display: "grid", gridTemplateColumns: "1fr 2fr", gap: 14 }}>
          <div style={campoWrap}>
            <label style={labelBase}>Tipo de chave</label>
            <Selecao
              value={pixTipo}
              onChange={e => setPixTipo(e.target.value)}
              style={{ ...inputBase, cursor: "pointer" }}>
              <option value="">— Selecione —</option>
              <option value="CNPJ">CNPJ</option>
              <option value="CPF">CPF</option>
              <option value="E-mail">E-mail</option>
              <option value="Telefone">Telefone</option>
              <option value="Aleatória">Aleatória</option>
            </Selecao>
          </div>
          <div style={campoWrap}>
            <label style={labelBase}>Chave PIX</label>
            <input
              type="text"
              value={pixChave}
              onChange={e => setPixChave(e.target.value)}
              placeholder={
                pixTipo === "CNPJ"     ? "00.000.000/0000-00" :
                pixTipo === "CPF"      ? "000.000.000-00" :
                pixTipo === "E-mail"   ? "contato@escritorio.com" :
                pixTipo === "Telefone" ? "(11) 91234-5678" :
                pixTipo === "Aleatória" ? "Cole a chave aleatória do banco" :
                "Selecione o tipo acima"
              }
              style={inputBase}
            />
          </div>
        </div>

        <div style={campoWrap}>
          <label style={labelBase}>Banco</label>
          <input
            type="text"
            value={banco}
            onChange={e => setBanco(e.target.value)}
            placeholder="Ex: Sicoob"
            list="vk-onb-bancos"
            style={inputBase}
          />
          <datalist id="vk-onb-bancos">
            {BANCOS_COMUNS.map(b => <option key={b} value={b} />)}
          </datalist>
        </div>

      </div>
    </div>
  );
}

// Tela exibida após onboarding concluído com sucesso. Prepara o usuário
// pra próxima etapa (cadastro do escritório) explicando POR QUE essas
// informações são necessárias — caso contrário cadastro parece
// "burocrático demais" e usuário pode pular pela aba.
function TelaTransicao({ usuarioNome, onContinuar }) {
  const primeiroNome = (usuarioNome || "").split(" ")[0] || "";
  return (
    <div style={tela}>
      <div style={{ width:"100%", maxWidth:520, padding:"60px 24px", textAlign:"center" }}>
        {/* Ícone de sucesso (check em círculo preto) */}
        <div style={{
          width:56, height:56, borderRadius:"50%",
          background:"#262421", color:"#fff",
          display:"flex", alignItems:"center", justifyContent:"center",
          margin:"0 auto 24px",
        }}>
          <svg width="26" height="26" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
            <polyline points="20 6 9 17 4 12"/>
          </svg>
        </div>

        <div style={{ fontSize:22, fontWeight:300, color:"#111827", letterSpacing:-0.4, marginBottom:10 }}>
          Tudo certo, {primeiroNome}!
        </div>
        <div style={{ fontSize:14, color:"#4b5563", lineHeight:1.55, marginBottom:36 }}>
          Seu perfil de pricing está configurado. Agora vamos completar o cadastro do seu escritório.
        </div>

        <div style={{
          background:"#fafbfc",
          border:"1px solid #f3f4f6",
          borderRadius: 14,
          padding:"20px 22px",
          textAlign:"left",
          marginBottom:32,
        }}>
          <div style={{ fontSize:11, fontWeight:700, color:"#4b5563", textTransform:"uppercase", letterSpacing:1, marginBottom:12 }}>
            Por que isso importa
          </div>
          <div style={{ fontSize:13, color:"#111827", lineHeight:1.7 }}>
            Os dados do escritório (logo, endereço, contatos) aparecem nos seus orçamentos, propostas e PDFs enviados aos clientes. É a sua identidade visual no sistema.
          </div>
        </div>

        <button
          onClick={onContinuar}
          style={{
            ...btnPrimario,
            width:"100%", maxWidth:320,
            padding:"13px 20px", fontSize:14,
          }}>
          Continuar para o cadastro →
        </button>
      </div>
    </div>
  );
}

// ── Estilos compartilhados ─────────────────────────────────────
const tela = {
  position:"fixed", inset:0,
  background:"#fafafa",
  fontFamily:"'Inter', system-ui, -apple-system, sans-serif",
  overflowY:"auto",
  display:"flex", justifyContent:"center", alignItems:"flex-start",
};
const card = {
  background:"#fff", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 16,
  padding:"32px 32px 24px", maxWidth:420, width:"100%",
  boxShadow:"0 8px 32px rgba(0,0,0,0.06)",
  margin:"40px 20px",
};
const btnPrimario = {
  background:"#262421", color:"#fff", border:"none", borderRadius: 12,
  padding:"11px 16px", fontSize:13.5, fontWeight:600, cursor:"pointer",
  fontFamily:"inherit",
};
const btnSecundario = {
  background:"transparent", color:"#4b5563", border:"none",
  padding:"8px", fontSize:12, cursor:"pointer", fontFamily:"inherit",
};
const tdLabel = { color:"#4b5563", padding:"4px 0" };
const tdValor = { textAlign:"right", padding:"4px 0", color:"#111827" };

// ── Helpers ────────────────────────────────────────────────────
function moeda(v) {
  if (typeof v !== "number" || !isFinite(v)) return "R$ —";
  return v.toLocaleString("pt-BR", { style:"currency", currency:"BRL" });
}


// ════════════════════════════════════════════════════════════
// orcamento-config.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// ORÇAMENTO — Configurações de pricing
// ═══════════════════════════════════════════════════════════════
// Aba "Orçamento" da seção Configuração na sidebar. Por enquanto contém
// apenas o botão de "Resetar e refazer calibragem" — dispara o endpoint
// POST /admin/empresas/:id/reset-onboarding e em seguida refetcha /auth/me
// pra que o app.jsx detecte precisa_fazer_onboarding=TRUE e renderize o
// componente Onboarding direto, sem precisar de logout/login.
//
// Permissões:
// - master e admin podem executar (backend já valida).
// - Outros perfis (editor/visualizador) veem mensagem explicando que
//   precisam de admin/master.

function OrcamentoConfig({ usuario, data, setUsuario }) {
  const [executando, setExecutando] = useState(false);

  // URL base da API. Mesma lógica que escritorio.jsx e shared.jsx —
  // env var Vite com fallback pro Railway prod ativo.
  const _API_URL = (typeof import.meta !== "undefined" && import.meta.env && import.meta.env.VITE_API_URL)
    || "https://orbi-production-5f5c.up.railway.app";

  // Dados frescos do servidor. Não confiamos no localStorage `vicke-user`
  // porque ele pode estar desatualizado (ex: após onboarding que não
  // refetchou). Sempre vai buscar /auth/me ao montar a aba.
  const [me, setMe]               = useState(null);
  const [meLoading, setMeLoading] = useState(true);
  const [meErro, setMeErro]       = useState(null);

  // CUB do estado da empresa (R-1 Normal — referência usada no pricing).
  // Carregado em paralelo com /auth/me. Necessário pra calcular o preço
  // base por m² que aparece em "Preço base aplicado".
  const [cub, setCub] = useState(null);

  async function carregarMe() {
    setMeLoading(true);
    setMeErro(null);
    try {
      const token = localStorage.getItem("vicke-token");
      if (!token) throw new Error("Sessão expirada. Faça login novamente.");
      const res = await fetch(`${_API_URL}/auth/me`, {
        headers: { "Authorization": `Bearer ${token}` },
      });
      const json = await res.json();
      if (!json.ok) throw new Error(json.error || "Falha ao carregar dados");
      setMe(json.data);
      // Carrega CUB do estado retornado pelo backend. Se a empresa ainda não
      // tem estado definido (onboarding incompleto), pula — o card de preço
      // base vai mostrar "—" e tudo bem.
      if (json.data?.estado) {
        try {
          const cubRes = await fetch(
            `${_API_URL}/api/cub/atual?estado=${encodeURIComponent(json.data.estado)}&categoria=R-1&padrao=Normal`,
            { headers: { "Authorization": `Bearer ${token}` } }
          );
          const cubJson = await cubRes.json();
          if (cubJson.ok) setCub(cubJson.data);
          // Se CUB falhar, não interrompe — só não mostra o preço base.
          // Outros campos (profissão, padrão, etc.) continuam visíveis.
        } catch { /* silencioso */ }
      }
    } catch (e) {
      setMeErro(e.message);
    } finally {
      setMeLoading(false);
    }
  }

  useEffect(() => { carregarMe(); /* eslint-disable-next-line */ }, []);

  // Permissão pra disparar o reset: master OU admin (backend valida também,
  // mas escondemos o botão dos outros perfis pra não confundir).
  // Usa `usuario` (props) que já está disponível imediatamente — sem esperar
  // o /auth/me — pra decidir se mostra o botão ou o aviso amigável.
  const podeResetar = usuario?.perfil === "master" || usuario?.nivel === "admin";

  // ID da empresa-alvo. Por enquanto o reset só age sobre a própria empresa
  // do usuário (claim empresa_id do JWT). Master que precisar resetar outra
  // empresa continua usando o drill-in do Admin ou o console.
  const empresaId = me?.empresa_id ?? usuario?.empresa_id;

  // Dados de calibragem atuais. Prioriza `me` (fresco do /auth/me); cai pra
  // `usuario` enquanto carrega. Após o fetch, sempre exibe valores atuais.
  const fonte             = me || usuario || {};
  const pctCalibrado      = fonte.pct_calibrado;
  const pctMatriz         = fonte.pct_matriz_calculado;
  // pct_efetivo: o que de fato vale pro pricing. Se calibrou, usa calibrado;
  // se não, usa o calculado pela matriz.
  const pctEfetivo        = pctCalibrado ?? pctMatriz ?? null;
  const profissao         = fonte.profissao;
  const padraoProjetos    = fonte.padrao_projetos;
  const estado            = fonte.estado;

  // Preço base R$/m² = pct_efetivo × CUB R-1 Normal do estado.
  // É o número que entra na fórmula do orçamento (depois multiplicado pelos
  // índices de cômodos e padrão pra chegar no honorário final).
  const cubValor    = cub?.valor_m2 ?? null;
  const precoBaseM2 = (pctEfetivo != null && cubValor != null) ? pctEfetivo * cubValor : null;

  // Labels amigáveis pros valores brutos do banco
  const labelProfissao = { arquiteto: "Arquiteto(a)", engenheiro: "Engenheiro(a)" };
  const labelPadrao    = { simples: "Simples", medio: "Médio", alto: "Alto", luxo: "Luxo" };

  // Helpers de formatação BR (vírgula em vez de ponto)
  const fmtPct  = (v, casas = 2) => v == null ? null : `${(v * 100).toFixed(casas).replace(".", ",")}%`;
  const fmtBRL  = (v) => v == null ? null : v.toLocaleString("pt-BR", { style: "currency", currency: "BRL" });

  async function executarReset() {
    if (!empresaId) {
      dialogo.alertar({
        titulo: "Empresa não identificada",
        mensagem: "Não foi possível identificar sua empresa. Faça login novamente.",
        tipo: "erro",
      });
      return;
    }

    const confirmou = await dialogo.confirmar({
      titulo: "Resetar e refazer calibragem?",
      mensagem:
        "Isso vai apagar as respostas do onboarding (profissão, porte, padrão, estado, capital) e o pct_calibrado da empresa. " +
        "Você cairá direto na tela de onboarding pra refazer a calibragem — sem precisar fazer login de novo.\n\n" +
        "Os clientes, projetos, orçamentos e dados do escritório NÃO são afetados — apenas a calibragem de pricing.",
      confirmar: "Resetar calibragem",
      destrutivo: true,
    });
    if (!confirmou) return;

    setExecutando(true);
    try {
      const token = localStorage.getItem("vicke-token");
      if (!token) throw new Error("Sessão expirada. Faça login novamente.");

      const res = await fetch(`${_API_URL}/admin/empresas/${empresaId}/reset-onboarding`, {
        method: "POST",
        headers: {
          "Authorization": `Bearer ${token}`,
          "Content-Type": "application/json",
        },
      });
      const json = await res.json();
      if (!json.ok) throw new Error(json.error || "Falha ao resetar onboarding");

      // Sucesso: refetch /auth/me pra trazer estado atualizado (precisa_fazer_onboarding=true,
      // campos zerados). Atualizar setUsuario faz o app.jsx detectar a flag e
      // renderizar <Onboarding /> automaticamente — sem logout, sem reload.
      // Se o usuário fechar a aba/navegador depois disso, o token ainda vale (não foi
      // invalidado), mas ao reabrir, /auth/me vai retornar precisa_fazer_onboarding=true
      // e ele vai cair no onboarding direto após login.
      const meRes = await fetch(`${_API_URL}/auth/me`, {
        headers: { "Authorization": `Bearer ${token}` },
      });
      const meJson = await meRes.json();
      if (!meJson.ok) throw new Error(meJson.error || "Falha ao recarregar dados do usuário");

      // Atualiza state global + localStorage. React vai rerenderizar e o
      // app.jsx vai detectar precisa_fazer_onboarding=true automaticamente.
      if (typeof setUsuario === "function") {
        setUsuario(meJson.data);
      }
      try { localStorage.setItem("vicke-user", JSON.stringify(meJson.data)); } catch {}
      // Não precisa de modal de "sucesso" — a transição visual pra tela de
      // onboarding já é o feedback. Se ficar muito instantâneo, dá pra
      // adicionar um toast leve aqui no futuro.
    } catch (e) {
      dialogo.alertar({
        titulo: "Erro ao resetar calibragem",
        mensagem: e.message,
        tipo: "erro",
      });
    } finally {
      setExecutando(false);
    }
  }

  // Estilos — mesma paleta minimalista do escritorio.jsx pra manter
  // consistência visual entre as abas de Configuração.
  const S = {
    wrap:     { fontFamily:"'Inter', system-ui, -apple-system, sans-serif", background:"#fff", minHeight:"100vh", color:"#262421", maxWidth:1200, margin:"0 auto" },
    header:   { borderBottom:"1.5px solid rgba(38,36,33,0.16)", padding:"24px 32px" },
    titulo:   { fontSize:18, fontWeight:700, color:"#262421", margin:0 },
    sub:      { fontSize:13, color:"#9ca3af", marginTop:3 },
    body:     { padding:"32px", maxWidth:760 },
    secao:    { marginBottom:32 },
    secTitulo:{ fontSize:11, fontWeight:700, color:"#9ca3af", textTransform:"uppercase", letterSpacing:1, marginBottom:16 },
    label:    { fontSize:11, color:"#9ca3af", textTransform:"uppercase", letterSpacing:0.5, marginBottom:4 },
    valor:    { fontSize:14, color:"#262421" },
    vazio:    { fontSize:14, color:"#9ca3af", fontStyle:"italic" },
    grid2:    { display:"grid", gridTemplateColumns:"1fr 1fr", gap:16, marginBottom:18 },
    btn:      { background:"#262421", color:"#fff", border:"none", borderRadius: 12, padding:"10px 20px", fontSize:13, fontWeight:600, cursor:"pointer", fontFamily:"inherit" },
    btnDanger:{ background:"#fff", color:"#dc2626", border:"1px solid #fecaca", borderRadius: 12, padding:"10px 20px", fontSize:13, fontWeight:600, cursor:"pointer", fontFamily:"inherit" },
    aviso:    { fontSize:13, color:"#6b7280", lineHeight:1.6, background:"#fafbfc", border:"1px solid #f3f4f6", borderRadius: 12, padding:"14px 16px", marginBottom:16 },
    avisoSemPerm: { fontSize:13, color:"#92400e", lineHeight:1.6, background:"#fffbeb", border:"1px solid #fde68a", borderRadius: 12, padding:"14px 16px" },
    // Box de destaque do preço base R$/m². Visualmente diferente das células
    // do grid pra dar peso ao número que importa no dia a dia.
    boxPrecoBase: { background:"#fafbfc", border:"1.5px solid rgba(38,36,33,0.16)", borderRadius: 14, padding:"18px 20px", marginTop:4 },
    boxLabel:     { fontSize:11, color:"#6b7280", textTransform:"uppercase", letterSpacing:0.6, fontWeight:600, marginBottom:6 },
    boxValor:     { fontSize:28, fontWeight:700, color:"#262421", lineHeight:1, display:"flex", alignItems:"baseline", gap:6 },
    boxUnidade:   { fontSize:14, fontWeight:500, color:"#9ca3af" },
    boxFormula:   { fontSize:12, color:"#9ca3af", marginTop:8 },
  };

  // Helper de exibição: se o valor for nulo/vazio, mostra "—" cinza itálico
  const Campo = ({ label, valor }) => (
    <div>
      <div style={S.label}>{label}</div>
      {valor != null && valor !== "" ? <div style={S.valor}>{valor}</div> : <div style={S.vazio}>—</div>}
    </div>
  );

  return (
    <div style={S.wrap}>
      {/* Header */}
      <div style={S.header}>
        <div style={S.titulo}>Orçamento</div>
        <div style={S.sub}>Configurações de pricing e calibragem</div>
      </div>

      {/* Conteúdo */}
      <div style={S.body}>
        <div style={S.secao}>
          <div style={S.secTitulo}>Calibragem atual</div>

          {meErro && (
            <div style={{ ...S.avisoSemPerm, marginBottom: 12 }}>
              Não foi possível carregar os dados frescos: {meErro}.
              {" "}<a href="#" onClick={(e) => { e.preventDefault(); carregarMe(); }} style={{ color:"#92400e", fontWeight:600 }}>Tentar novamente</a>
            </div>
          )}

          <div style={S.grid2}>
            <Campo label="Profissão"           valor={labelProfissao[profissao] || profissao} />
            <Campo label="Padrão dos projetos" valor={labelPadrao[padraoProjetos] || padraoProjetos} />
            <Campo label="Estado"              valor={estado} />
            <Campo
              label="Percentual aplicado"
              valor={
                pctEfetivo != null
                  ? `${fmtPct(pctEfetivo)}${pctCalibrado != null ? " (calibrado)" : " (matriz)"}`
                  : null
              }
            />
          </div>

          {/* Box de destaque do preço base R$/m² — número que entra na fórmula
              do orçamento (depois multiplicado pelos índices e tamanho da casa
              pra chegar no honorário final). É o que importa no dia a dia. */}
          <div style={S.boxPrecoBase}>
            <div style={S.boxLabel}>Preço base do m²</div>
            <div style={S.boxValor}>
              {precoBaseM2 != null ? fmtBRL(precoBaseM2) : <span style={S.vazio}>—</span>}
              {precoBaseM2 != null && <span style={S.boxUnidade}>/m²</span>}
            </div>
            {pctEfetivo != null && cubValor != null && (
              <div style={S.boxFormula}>
                {fmtPct(pctEfetivo)} × {fmtBRL(cubValor)} (CUB R-1 Normal {estado})
              </div>
            )}
          </div>

          {meLoading && (
            <div style={{ fontSize:12, color:"#9ca3af", marginTop:12 }}>Atualizando…</div>
          )}
        </div>

        <div style={S.secao}>
          <div style={S.secTitulo}>Refazer calibragem</div>

          {!podeResetar ? (
            <div style={S.avisoSemPerm}>
              Apenas <strong>master</strong> ou <strong>administradores</strong> da empresa podem resetar a calibragem.
              Peça pro responsável da sua empresa fazer o reset.
            </div>
          ) : (
            <>
              <div style={S.aviso}>
                Apaga as respostas do onboarding e os percentuais (<code style={{ background:"#fff", padding:"1px 5px", borderRadius:3, border:"1.5px solid rgba(38,36,33,0.16)", fontSize:12 }}>pct_matriz_calculado</code> e <code style={{ background:"#fff", padding:"1px 5px", borderRadius:3, border:"1.5px solid rgba(38,36,33,0.16)", fontSize:12 }}>pct_calibrado</code>) da empresa.
                Você cai direto na tela de onboarding pra refazer a calibragem — sem precisar fazer login novamente.
                Clientes, projetos e orçamentos <strong>não</strong> são afetados.
              </div>
              <button
                onClick={executarReset}
                disabled={executando}
                style={{
                  ...S.btnDanger,
                  opacity: executando ? 0.5 : 1,
                  cursor: executando ? "not-allowed" : "pointer",
                }}>
                {executando ? "Resetando..." : "Resetar e refazer calibragem"}
              </button>
            </>
          )}
        </div>
      </div>
    </div>
  );
}


// ════════════════════════════════════════════════════════════
// whatsapp-piloto.jsx
// ════════════════════════════════════════════════════════════

// ═══════════════════════════════════════════════════════════════
// WHATSAPP PILOTO — teste grátis da Cloud API (só Padovan)
// ═══════════════════════════════════════════════════════════════
// Tela de teste da integração com o número de teste da Meta. Conversa com
// as rotas /api/whatsapp-teste/* do vicke-backend (whatsapp-teste.js), que
// só respondem para a empresa piloto — para as outras o menu nem aparece
// (waPilotoStatus devolve liberado:false).
//
// Duas colunas como a caixa de Mensagens: à esquerda as obras (filtro), à
// direita o status da configuração, a conversa e o campo de envio. No
// celular vira uma coluna só: escolhe a obra e a conversa abre por cima.
// Atualiza sozinha a cada 5s enquanto a aba está visível.

async function waReq(method, path, body) {
  const token = typeof localStorage !== "undefined" ? localStorage.getItem("vicke-token") : null;
  const headers = { "Content-Type": "application/json" };
  if (token) headers.Authorization = `Bearer ${token}`;
  const res = await fetch(`${_API_URL}${path}`, { method, headers, body: body ? JSON.stringify(body) : undefined });
  const json = await res.json().catch(() => ({}));
  if (!json.ok) throw new Error(json.error || `Erro ${res.status}`);
  return json.data;
}

// Usada pelo app.jsx para decidir se o item de menu aparece.
async function waPilotoStatus() {
  try { return await waReq("GET", "/api/whatsapp-teste/status"); }
  catch { return { liberado: false }; }
}

const WA_AZUL = "#0474f4";
const WA_BORDA = "1.5px solid rgba(38,36,33,0.16)";

function waHora(iso) {
  if (!iso) return "";
  try {
    return new Date(iso).toLocaleString("pt-BR", { day: "2-digit", month: "2-digit", hour: "2-digit", minute: "2-digit" });
  } catch { return ""; }
}

function waTelefone(n) {
  const d = String(n || "").replace(/\D/g, "");
  if (d.length === 13) return `+${d.slice(0, 2)} (${d.slice(2, 4)}) ${d.slice(4, 9)}-${d.slice(9)}`;
  if (d.length === 12) return `+${d.slice(0, 2)} (${d.slice(2, 4)}) ${d.slice(4, 8)}-${d.slice(8)}`;
  return n || "";
}

const WA_STATUS = {
  enviado: "✓ enviado", sent: "✓ enviado", delivered: "✓✓ entregue", read: "✓✓ lido",
  failed: "não entregue", falhou: "não enviado", simulado: "simulação",
};

function WhatsappPiloto({ data, usuario }) {
  const [isMobile, setIsMobile] = useState(() => { try { return window.innerWidth < 768; } catch { return false; } });
  useEffect(() => {
    const f = () => { try { setIsMobile(window.innerWidth < 768); } catch {} };
    window.addEventListener("resize", f);
    return () => window.removeEventListener("resize", f);
  }, []);

  const [status, setStatus] = useState(null);
  const [filtroObra, setFiltroObra] = useState("");     // "" = todas, "__sem_obra__", ou id
  const [busca, setBusca] = useState("");
  const [msgs, setMsgs] = useState([]);
  const [carregando, setCarregando] = useState(true);
  const [erro, setErro] = useState("");
  const [para, setPara] = useState("");
  const [paraEditado, setParaEditado] = useState(false);
  const [texto, setTexto] = useState("");
  const [enviando, setEnviando] = useState(false);
  const [abertoMobile, setAbertoMobile] = useState(false);
  const [mostrarConfig, setMostrarConfig] = useState(false);
  const [copiado, setCopiado] = useState(false);
  const fimRef = useRef(null);
  // Respostas de carregar() fora de ordem: a de outra obra (ou mais velha que
  // a já mostrada) é ignorada — senão a conversa da obra anterior voltava.
  const filtroRef = useRef(filtroObra), reqSeq = useRef(0), reqAplicada = useRef(0);
  filtroRef.current = filtroObra;

  const podeEscrever = usuario?.nivel === "admin" || usuario?.nivel === "editor" || usuario?.perfil === "master";
  const obras = useMemo(() => {
    const q = busca.trim().toLowerCase();
    return (data?.obras || [])
      .filter(o => o && o.id && (!q || String(o.nome || "").toLowerCase().includes(q)))
      .sort((a, b) => String(a.nome || "").localeCompare(String(b.nome || ""), "pt-BR"));
  }, [data?.obras, busca]);
  const nomeFiltro = filtroObra === "" ? "Todas as mensagens"
    : filtroObra === "__sem_obra__" ? "Sem obra vinculada"
    : ((data?.obras || []).find(o => o.id === filtroObra)?.nome || "Obra");

  const carregar = useCallback(async () => {
    const meu = ++reqSeq.current;
    const valida = () => filtroRef.current === filtroObra && meu > reqAplicada.current;
    try {
      const qs = filtroObra ? `?obra_id=${encodeURIComponent(filtroObra)}` : "";
      const [st, lista] = await Promise.all([
        waReq("GET", "/api/whatsapp-teste/status"),
        waReq("GET", `/api/whatsapp-teste/mensagens${qs}`),
      ]);
      if (!valida()) return;
      reqAplicada.current = meu;
      setStatus(st);
      setMsgs(lista || []);
      setErro("");
    } catch (e) {
      if (valida()) setErro(e.message);
    } finally {
      if (filtroRef.current === filtroObra) setCarregando(false);
    }
  }, [filtroObra]);
  // Trocar de obra zera o destinatário: sem mensagem recebida na obra nova, o
  // "Para" ficava com o número da obra anterior (e o editado à mão grudava).
  // msgs zera junto, para o destino padrão não ser tirado da conversa velha.
  function trocarObra(id) {
    setAbertoMobile(true);
    if (id === filtroObra) return;
    setFiltroObra(id); setMsgs([]); setPara(""); setParaEditado(false);
  }

  useEffect(() => {
    setCarregando(true);
    carregar();
    const t = setInterval(() => { if (document.visibilityState === "visible") carregar(); }, 5000);
    return () => clearInterval(t);
  }, [carregar]);

  // O destino padrão é quem mandou a última mensagem de verdade: responder
  // para o wa_id que a Meta entregou evita o problema do 9 dos celulares.
  useEffect(() => {
    if (paraEditado) return;
    const ultima = [...msgs].reverse().find(m => m.direcao === "entrada" && m.wa_id && m.wa_id !== "simulado");
    if (ultima) setPara(ultima.wa_id);
  }, [msgs, paraEditado]);

  useEffect(() => { fimRef.current?.scrollIntoView({ block: "end" }); }, [msgs.length]);

  async function enviar() {
    if (!texto.trim() || !para.trim() || enviando) return;
    setEnviando(true); setErro("");
    try {
      const obraId = filtroObra && filtroObra !== "__sem_obra__" ? filtroObra : null;
      await waReq("POST", "/api/whatsapp-teste/enviar", { para, texto, obra_id: obraId });
      setTexto("");
    } catch (e) {
      setErro(e.message);
    } finally {
      setEnviando(false);
      carregar();
    }
  }

  async function simular() {
    setErro("");
    try {
      const obraId = filtroObra && filtroObra !== "__sem_obra__" ? filtroObra : null;
      await waReq("POST", "/api/whatsapp-teste/simular", { obra_id: obraId });
      carregar();
    } catch (e) { setErro(e.message); }
  }

  const urlWebhook = `${_API_URL}${status?.webhookPath || "/webhook/whatsapp-teste"}`;
  function copiarUrl() {
    try { navigator.clipboard.writeText(urlWebhook); setCopiado(true); setTimeout(() => setCopiado(false), 1500); } catch {}
  }

  const configOk = status?.tokenConfigurado && status?.phoneIdConfigurado;

  const S = {
    raiz: { display: "flex", height: "100%", minHeight: 0, fontFamily: "'Inter', system-ui, -apple-system, sans-serif", background: "#fff", color: "#111827" },
    lista: { width: isMobile ? "100%" : 300, minWidth: isMobile ? 0 : 300, borderRight: isMobile ? "none" : WA_BORDA, overflowY: "auto", display: isMobile && abertoMobile ? "none" : "flex", flexDirection: "column" },
    conversa: { flex: 1, minWidth: 0, display: isMobile && !abertoMobile ? "none" : "flex", flexDirection: "column" },
    item: (ativo) => ({ display: "block", width: "100%", textAlign: "left", background: "#fff", border: "none", borderLeft: `3px solid ${ativo ? WA_AZUL : "transparent"}`, padding: isMobile ? "14px 16px" : "10px 14px", fontSize: 13, fontWeight: ativo ? 600 : 400, color: ativo ? WA_AZUL : "#111827", cursor: "pointer", fontFamily: "inherit" }),
    btn: { background: "#fff", color: "#111827", border: WA_BORDA, borderRadius: 8, padding: "8px 12px", fontSize: 13, fontWeight: 500, cursor: "pointer", fontFamily: "inherit" },
    btnAzul: { background: WA_AZUL, color: "#fff", border: "none", borderRadius: 8, padding: "10px 16px", fontSize: 13, fontWeight: 600, cursor: "pointer", fontFamily: "inherit" },
    input: { border: WA_BORDA, borderRadius: 8, padding: "9px 11px", fontSize: isMobile ? 16 : 13, fontFamily: "inherit", color: "#111827", outline: "none", background: "#fff", minWidth: 0 },
  };

  if (status && status.liberado === false) {
    return <div style={{ padding: 32, fontFamily: "'Inter', system-ui, sans-serif", color: "#4b5563", fontSize: 14 }}>O teste de WhatsApp está liberado só para o escritório piloto.</div>;
  }

  return (
    <div style={S.raiz} data-vk-wa-piloto>
      {/* ── Coluna das obras ── */}
      <div style={S.lista}>
        <div style={{ padding: isMobile ? "16px 16px 10px" : "20px 14px 10px" }}>
          <div style={{ fontSize: 18, fontWeight: 600 }}>WhatsApp <span style={{ fontSize: 12, fontWeight: 500, color: "#4b5563" }}>· teste</span></div>
          <div style={{ fontSize: 12, color: "#4b5563", marginTop: 2 }}>Número de teste da Meta, sem custo</div>
          <input style={{ ...S.input, width: "100%", boxSizing: "border-box", marginTop: 12 }} placeholder="Filtrar obras" value={busca} onChange={e => setBusca(e.target.value)} />
        </div>
        <button style={S.item(filtroObra === "")} onClick={() => trocarObra("")}>Todas as mensagens</button>
        <button style={S.item(filtroObra === "__sem_obra__")} onClick={() => trocarObra("__sem_obra__")}>Sem obra vinculada</button>
        <div style={{ fontSize: 11, fontWeight: 600, color: "#6b7280", letterSpacing: 0.4, textTransform: "uppercase", padding: "14px 14px 6px" }}>Obras</div>
        {obras.length === 0 && <div style={{ fontSize: 13, color: "#6b7280", padding: "4px 14px" }}>Nenhuma obra encontrada</div>}
        {obras.map(o => (
          <button key={o.id} style={S.item(filtroObra === o.id)} onClick={() => trocarObra(o.id)}>{o.nome || "(sem nome)"}</button>
        ))}
      </div>

      {/* ── Conversa ── */}
      <div style={S.conversa}>
        <div style={{ padding: isMobile ? "12px 16px" : "16px 20px", borderBottom: WA_BORDA, display: "flex", alignItems: "center", gap: 10 }}>
          {isMobile && <button style={{ ...S.btn, padding: "6px 10px" }} onClick={() => setAbertoMobile(false)}>‹ Obras</button>}
          <div style={{ flex: 1, minWidth: 0 }}>
            <div style={{ fontSize: 15, fontWeight: 600, whiteSpace: "nowrap", overflow: "hidden", textOverflow: "ellipsis" }}>{nomeFiltro}</div>
          </div>
          <button style={{ ...S.btn, borderColor: configOk ? "rgba(38,36,33,0.16)" : WA_AZUL, color: configOk ? "#111827" : WA_AZUL }} onClick={() => setMostrarConfig(v => !v)}>
            {status ? (configOk ? "✓ Configurado" : "Configurar") : "…"}
          </button>
        </div>

        {/* Card de status */}
        {(mostrarConfig || (status && !configOk)) && status && (
          <div style={{ margin: isMobile ? "12px 12px 0" : "14px 20px 0", border: WA_BORDA, borderRadius: 10, padding: 14, fontSize: 13 }}>
            <div style={{ fontWeight: 600, marginBottom: 8 }}>Status do teste</div>
            <div style={{ display: "grid", gridTemplateColumns: isMobile ? "1fr" : "1fr 1fr", gap: "6px 16px", color: "#4b5563" }}>
              <div>{status.tokenConfigurado ? "✓" : "✗"} WHATSAPP_TEST_TOKEN</div>
              <div>{status.phoneIdConfigurado ? "✓" : "✗"} WHATSAPP_TEST_PHONE_ID</div>
              <div>{status.assinaturaLigada ? "✓ assinatura da Meta conferida" : "– assinatura não conferida (opcional)"}</div>
              <div>Última mensagem recebida: <span style={{ color: "#111827" }}>{status.ultimaEntrada ? waHora(status.ultimaEntrada) : "nenhuma ainda"}</span></div>
            </div>
            <div style={{ marginTop: 10, color: "#4b5563" }}>URL do webhook (colar no painel da Meta):</div>
            <div style={{ display: "flex", gap: 8, marginTop: 4, alignItems: "center", flexWrap: "wrap" }}>
              <code style={{ fontSize: 12, background: "#f3f4f6", borderRadius: 6, padding: "6px 8px", wordBreak: "break-all", flex: 1, minWidth: 0, color: "#111827" }}>{urlWebhook}</code>
              <button style={S.btn} onClick={copiarUrl}>{copiado ? "Copiado ✓" : "Copiar"}</button>
            </div>
            <div style={{ marginTop: 6, color: "#4b5563" }}>Verify token: <code style={{ color: "#111827" }}>{status.verifyTokenPadrao ? "vicke_teste_padovan" : "o valor de WHATSAPP_VERIFY_TOKEN"}</code></div>
          </div>
        )}

        {/* Histórico */}
        <div style={{ flex: 1, overflowY: "auto", padding: isMobile ? "12px" : "16px 20px", display: "flex", flexDirection: "column", gap: 8, background: "#fafafa" }}>
          {carregando && msgs.length === 0 && <div style={{ color: "#6b7280", fontSize: 13 }}>Carregando…</div>}
          {!carregando && msgs.length === 0 && (
            <div style={{ color: "#4b5563", fontSize: 13, textAlign: "center", marginTop: 40, lineHeight: 1.6 }}>
              Nenhuma mensagem aqui ainda.<br />Mande um "oi" do seu celular para o número de teste,<br />ou use "Simular mensagem de pedreiro".
            </div>
          )}
          {msgs.map(m => {
            const saida = m.direcao === "saida";
            const falhou = m.status === "failed" || m.status === "falhou";
            return (
              <div key={m.id} style={{ alignSelf: saida ? "flex-end" : "flex-start", maxWidth: isMobile ? "88%" : "70%" }}>
                <div style={{ fontSize: 11, color: "#6b7280", marginBottom: 2, textAlign: saida ? "right" : "left" }}>
                  {saida ? `VICKE → ${waTelefone(m.wa_id)}` : (m.nome_contato || waTelefone(m.wa_id))}
                  {m.obra_nome && filtroObra === "" ? ` · ${m.obra_nome}` : ""}
                </div>
                <div style={{
                  background: saida ? WA_AZUL : "#f3f4f6", color: saida ? "#fff" : "#111827",
                  border: falhou ? "1.5px solid #b91c1c" : "none",
                  borderRadius: 12, padding: "8px 12px", fontSize: 14, lineHeight: 1.45, whiteSpace: "pre-wrap", wordBreak: "break-word",
                }}>
                  {m.tipo !== "texto" && <div style={{ fontSize: 12, fontWeight: 600, opacity: 0.85, marginBottom: m.conteudo_texto ? 4 : 0 }}>[{m.tipo}{m.media_id ? " · mídia guardada" : ""}]</div>}
                  {m.conteudo_texto}
                </div>
                <div style={{ fontSize: 11, color: falhou ? "#b91c1c" : "#6b7280", marginTop: 2, textAlign: saida ? "right" : "left" }}>
                  {waHora(m.created_at)}{saida && m.status ? ` · ${WA_STATUS[m.status] || m.status}` : ""}{!saida && m.status === "simulado" ? " · simulação" : ""}
                </div>
                {falhou && m.erro && <div style={{ fontSize: 12, color: "#b91c1c", marginTop: 2, textAlign: "right" }}>{m.erro}</div>}
              </div>
            );
          })}
          <div ref={fimRef} />
        </div>

        {/* Envio */}
        <div style={{ borderTop: WA_BORDA, padding: isMobile ? "10px 12px 14px" : "12px 20px 16px", display: "flex", flexDirection: "column", gap: 8 }}>
          {erro && <div style={{ fontSize: 13, color: "#b91c1c" }}>{erro}</div>}
          {podeEscrever ? (<>
            <div style={{ display: "flex", gap: 8, alignItems: "center", flexWrap: "wrap" }}>
              <span style={{ fontSize: 12, color: "#4b5563" }}>Para</span>
              <input style={{ ...S.input, flex: isMobile ? "1 1 0" : "0 0 220px" }} inputMode="tel" placeholder="55 14 99999-9999"
                value={para} onChange={e => { setPara(e.target.value); setParaEditado(true); }} />
              <button style={{ ...S.btn, width: isMobile ? "100%" : "auto" }} onClick={simular}>Simular mensagem de pedreiro</button>
            </div>
            <div style={{ display: "flex", gap: 8 }}>
              <textarea style={{ ...S.input, flex: 1, resize: "none", height: 42 }} placeholder="Escreva a resposta"
                value={texto} onChange={e => setTexto(e.target.value)}
                onKeyDown={e => { if (e.key === "Enter" && !e.shiftKey && !isMobile) { e.preventDefault(); enviar(); } }} />
              <button style={{ ...S.btnAzul, opacity: (!texto.trim() || !para.trim() || enviando) ? 0.5 : 1 }} disabled={!texto.trim() || !para.trim() || enviando} onClick={enviar}>
                {enviando ? "Enviando…" : "Enviar"}
              </button>
            </div>
            <div style={{ fontSize: 11, color: "#6b7280" }}>Texto livre só chega a quem mandou mensagem nas últimas 24h e está na lista de números do painel da Meta.</div>
          </>) : (
            <div style={{ fontSize: 13, color: "#4b5563" }}>Seu nível de acesso só permite ver as mensagens.</div>
          )}
        </div>
      </div>
    </div>
  );
}


