    let alt = 3; for (const p of pavsOrd) alt = Math.max(alt, (p.nivel || 0) + Math.max(0, ...((dadosDe(p.id).paredes || []).map((w) => w.h || 0))));
    const ini = { theta: T.theta, phi: T.phi, dist: T.dist, alvo: T.alvo || { x: 0, y: 1, z: 0 } };
