    const fim = { theta: ini.theta + dth, phi: v.phi, dist: Math.max(10, v.id === "persp" ? tam * 1.6 : (Math.max(tam, alt * 1.6) / 2 + 2) / Math.tan(20 * Math.PI / 180)), alvo: { x: 0, y: v.id === "topo" ? 0 : alt / 2, z: 0 } };
